Object.values(C).forEach(x=>{if(!x.token&&x.c>=3&&!x.kw&&!x.bc&&!x.dr&&!x.aura&&!x.poison&&!x.bounty&&!x.onkill&&!x.fuel)x.grow=1});
const PACK_POOL=Object.keys(C).filter(id=>!C[id].out&&!C[id].token&&C[id].st===1);
const RUN_POOL=PACK_POOL.filter(id=>C[id].r!=='L');
/* 新しいカード絵（ChatGPTシート1〜156を切り出したもの） */
['pochi','pochi2','pochi3','rookie','rookie2','rookie3','zombie','zombie2','zombie3','akudo2','akudo3','annie','jacka','scorpio','armadillo','runner','herb','chakka','bull','nanashi','pork','grizzly','bibiri','jesse','belle','akudo','juko','jitchoku','wyatt','masterson','garrett','tink','bruno','mustang','ranger','roybean','gaga','mia','virgil','adara','bass','tenshu','kifujin','doc','pokerfox','ragtime','slim','pyonko','korokichi','harry','bard','lily','shaker','cancan','arai','yoppa','mustache','mog','kishi','ikoku','eichi','calamity','nobel','ferret','hammer','hawk','gantetsu','boya','highnoon','digger','carson','crockett','henry','owl','bunyan','pecos','garako','tarantula','gila','bison','sabota','wolf','vulture','tumble','pony','bob','garasan','dog','jab','kurogoke','eagle','funkoro','rainmaker','hoho','sandman','doo','stargazer','mash','haboob','snakeoil','mist','stella','shadow','clover','bonedoc','amelie','celestia','bagura','hanage','seisei','kaikei','telegraph','boiler','edison','poppo','beaver','geary','betty','ironhorse','bolt','clock','ruler','build','kyu','kibishii','sabishii','atsukama','crow','tesaguri','coyote','tako','dalton','butch','bonnie','bart','soapy','ketcham','sambass','mary','bignose','iguana','axe','tokko','minpei','ice','chousyu','narikin','goblins','goliath','mole','hyena','kerits','pickey','capone','ma','zombino'].forEach(id=>{if(C[id])C[id].img='c/'+id});
const COLLECT=Object.keys(C).filter(id=>!C[id].token);

/* =====================================================================
   レベル（Lv1〜10）
   強くなり方はゆっくり。Lv10でやっと2倍ちょっと
   ===================================================================== */
const MAX_LV=10, EVO_LV=5;
const MERGE_RATE=[0,1,.9,.8,.7,.6,.5,.4,.3,.2];   // Lv1→2 … Lv9→10
const clv=lv=>Math.max(1,Math.min(MAX_LV,lv||1));
/* レベルが上がるたびに、体力→攻撃→体力→攻撃…と1ずつ増える（Lv10は両方+1） */
const lvA=lv=>Math.floor((clv(lv)-1)/2)+(clv(lv)>=MAX_LV?1:0);
const lvH=lv=>Math.floor(clv(lv)/2);
const statA=(id,lv)=>C[id].a+(C[id].kw.includes('noattack')?0:lvA(lv)+(C[id].grow?Math.floor((clv(lv)-1)/5):0));
const statH=(id,lv)=>Math.max(1,C[id].h+lvH(lv)+(C[id].grow?Math.floor(clv(lv)/5):0));
const valX=(v,lv)=>(v||0)+Math.floor(clv(lv)/3);           // ダメージ・回復などの数字（Lv3,6,9で+1）
const lvB=lv=>Math.min(2,Math.floor(clv(lv)/3)),lvP=lv=>clv(lv)>=3?1:0,lvN=lv=>(clv(lv)>=EVO_LV?1:0)+(clv(lv)>=MAX_LV?1:0); /* 10/27 効果の成長：B=Lv3,6で+1 P=Lv3で+1 N=Lv5,10で+1 */
const valN=(v,lv)=>(v||0)+((lv||1)>=EVO_LV?1:0)+((lv||1)>=MAX_LV?1:0); // 枚数・匹数などの数


const KW_T={taunt:'かばう',shield:'バリア',twice:'2回攻撃',quick:'はやうち',revive:'1回復活',home:'たおれたら手札へ',thorns:'トゲ',stealth:'かくれんぼ',
  lone:'一匹オオカミ',nostun:'酔わない',deadly:'必殺',noattack:'攻撃できない',splash:'なぎはらい',feed:'おこぼれ',pack:'群れ'};
const KW_HELP={taunt:'敵はまずこのキャラを攻撃しないといけない',shield:'1回だけダメージを0にする',twice:'1ターンに2回攻撃できる',quick:'出したターンからすぐ攻撃できる',
  revive:'たおれても1回だけ体力1で立ち上がる',home:'たおれたら手札にもどる',thorns:'攻撃されたら、攻撃してきた相手に1ダメージ',stealth:'自分から攻撃するまで、ねらわれない',
  lone:'ほかに仲間がいないと攻撃+2',nostun:'酔っぱらい（1回休み）にならない',deadly:'戦った相手のキャラを一発でたおす',noattack:'自分からは攻撃できない。でも攻撃力99なので、攻撃してきた相手はたおれる。3ターンで燃料切れ',
  splash:'攻撃した相手のとなりにも2ダメージ',feed:'キャラがたおれるたび、攻撃+1',pack:'ほかに動物の仲間がいると攻撃+2',poison:'毒：毎ターン、毒の数だけダメージ'};

function tokName(t){return t&&C[t]?`${C[t].n}（${C[t].a*K}/${C[t].h*K}）`:''}
function bcText(d,lv){
  const x=valX(d.v,lv),n=valN(d.v,lv);
  switch(d.bc){
    case 'draw':return `なかまを${n}人 ひく`;case 'coin':return `このターン、コイン+${n}`;
    case 'healall':return `仲間ぜんいんとあなたの体力を${x}いやす`;case 'dmg':return `いちばん強い敵キャラに${x}ダメージ（いなければ敵ヒーロー）`;
    case 'bomb':return `ランダムな敵に${x}ダメージ`;case 'aoe':return `敵キャラぜんいんに${x}ダメージ`;
    case 'poison':return `いちばん強い敵キャラに毒×${n}`;case 'weaken':return `ねらった敵の攻撃-${x}`;case 'weakall':return `敵ぜんいんの攻撃-${x}`;
    case 'stun':return 'いちばん強い敵を酔っぱらわせる（1回休み）';case 'stunall':return '敵ぜんいんを酔っぱらわせる（1回休み）';
    case 'blow':return 'いちばん強い敵キャラを手札に吹き飛ばす';case 'bounce':return 'ランダムな敵キャラ1体を手札に追い返す';
    case 'sneeze':return `大くしゃみ！ランダムな敵キャラ${n}体を手札に吹き飛ばす`;
    case 'summon':return `${tokName(d.tok)}を${n}匹よぶ`;case 'buff':return `いちばん強い仲間に+${x}/+${x}`;case 'buffr':return `ほかの仲間1体に+${x}/+${x}`;
    case 'buffall':return `仲間ぜんいんの攻撃+${x}`;case 'selfatk':return `自分の攻撃+${x}`;
    case 'flipdraw':return `コイン投げ！表なら なかまを${n}人 ひく`;case 'flipbuff':return `コイン投げ！表なら仲間1体に+${x}/+${x}`;
    case 'quickmg':return `早撃ち勝負！勝ったらいちばん強い敵キャラに${x}ダメージ`;case 'meat':return `お肉タップタプ！10回ごとに+${x}/+${x}`;
    case 'recall':return 'たおれた仲間を1枚、手札にもどす';case 'raise':return `たおれた仲間から${n}体、ランダムによみがえる`;
    case 'drawcoin':return `なかまを${n}人 ひいて、コイン+1`;case 'treasure':return `お宝発見！旅の賞金+＄${n}`;
    case 'lassoup':return 'この戦いのあいだ、投げ縄+30%';case 'scout':return '敵の手札を見やぶる＋なかまを1人 ひく';
    case 'hanage':return `敵が鼻毛ボーボーに！ いま 場に いる 敵ぜんいん、2ターン 攻撃-${x}`;case 'unko':return `敵がウンチをふんだ！2ターン敵の攻撃-${x}`;
    case 'moji':return 'あいての画面の文字が ぜんぶ文字化け！あいては次のターン、なかまを1人しか出せない';case 'mojis':return 'あいての手札の名前が文字化け！あいては次のターン、なかまを1人しか出せない';case 'junk':return 'コイン投げ！裏だとこわれて退場';
  }return ''}
function drText(d,lv){const x=valX(d.dv,lv),n=valN(d.dv,lv);
  switch(d.dr){case 'summon':return `${tokName(d.tok)}を${n}匹よぶ`;case 'boom':return `ランダムな敵に${x}ダメージを${d.boomN||3}回`;
    case 'healhero':return `あなたの体力を${x}いやす`;case 'healall':return `仲間ぜんいんの体力を${x}いやす`;case 'draw':return `なかまを${n}人 ひく`}return ''}
function auraText(d,lv){const x=valX(d.av,lv);
  switch(d.aura){case 'atk':return `いるあいだ、ほかの仲間の攻撃+${x}`;case 'faction':return `いるあいだ、ほかの${FACT[d.f][0]}の攻撃+${x}`;
    case 'coin':return 'いるあいだ、毎ターンコイン+1';case 'draw':return 'いるあいだ、毎ターン1枚多く引く';case 'regen':return `ターンの終わり、仲間ぜんいんの体力を${x}いやす`;
    case 'lasso':return 'いるあいだ、投げ縄+15%';case 'coinflip':return 'いるあいだ、毎ターン50%でコイン+1';case 'miner':return 'ターンの終わり、50%で＄1見つける'}return ''}
function cardText(id,lv){const d=C[id],p=[];
  d.kw.split(' ').filter(Boolean).forEach(k=>p.push(KW_T[k]));
  if(d.poison)p.push(`撃った敵に毒×${d.poison}`);if(d.bounty)p.push(`賞金首とボスに攻撃+${valX(d.bounty,lv)}`);
  if(d.onkill)p.push('敵をたおすたび なかまを1人 ひく');if(d.fuel)p.push(`${d.fuel}ターンで退場`);
  if(d.aura)p.push(auraText(d,lv));if(d.bc)p.push('見参！'+bcText(d,lv));if(d.dr)p.push('やられたら：'+drText(d,lv));
  return p.join('。')||'とくになし'}

