/* ===== テスト版：デッキの上限と、同じカードの枚数 ===== */
const DECK_BASE=8,DECK_CAP=30;
const bossClears=g=>Object.keys(STAGES).filter(k=>(((g||G).clear)||{})[k]>0).length;
const deckMax=g=>Math.min(DECK_CAP,DECK_BASE+2*bossClears(g)+(((g||G).deckBonus)||0));
const copyMax=id=>C[id]&&C[id].r==='L'?1:2;
const ownN=(id,g)=>{const e=(g||G).col[id];return e?1+(e.n||0):0};
const partyCnt=id=>G.party.filter(x=>x===id).length;
function fixParty(g){g=g||G;const cnt={};g.party=(g.party||[]).filter(id=>{if(!g.col[id])return false;cnt[id]=(cnt[id]||0)+1;return cnt[id]<=Math.min(copyMax(id),ownN(id,g))}).slice(0,deckMax(g));return g.party}


