/* やられかた：ゾンビはくずれる、スチームはこわれる、魔法はドロン、ほかはぴゅ〜っと飛んでいく */
function koStyle(id){const d=C[id];if(!d)return 'fly';if(d.f==='zo'||/^zombie/.test(id))return 'crumble';if(d.f==='st'&&!['beaver','betty','edison','kaikei','seisei','build','ruler'].includes(id))return 'boom';if(d.f==='ma')return 'poof';return 'fly'}
