const SLOT_KEY=n=>'wippy-journey2-slot'+n;
let G=null,CUR=0;
function freshSave(){
  /* 最初の仲間は6人（あき枠2つ）。財布は3コインまで */
  const start=['pochi','rookie','zombie','akudo','annie','jacka'];
  const col={};start.forEach(id=>col[id]={lv:1,n:0});
  /* 最初のデッキはシンプルな6枚。のこりは冒険のごほうびで少しずつ出会う */
  return {v:2,wallet:3,money:30,gems:0,unl:{board:1},col,party:[...start],jail:[],day:1,runs:0,clear:{wild:0,hill:0},best:{wild:0,hill:0},items:{rope:0,kit:0,map:0},
    seen:Object.fromEntries(start.map(id=>[id,1])),rumor:null,ach:{},st:{wins:0,caught:0,merges:0,evos:0,maxRelic:0,hanage:0,k990:0},intro:0,created:Date.now(),last:Date.now()}}
function fixSave(g){
  if(g.unl==null&&g.runs>0){g.unl={};g.unlSeen={};['board','party','shop','saloon','sheriff','dex','ach','data'].forEach(k=>{g.unl[k]=1;g.unlSeen[k]=1})}
  if(g.wallet==null)g.wallet=Math.min(10,3+Object.keys(STAGES).filter(k=>(g.clear||{})[k]>0).length);
  const f=freshSave();for(const k in f)if(g[k]==null)g[k]=f[k];
  for(const k in f.st)if(g.st[k]==null)g.st[k]=0;
  Object.keys(g.col).forEach(id=>{if(!C[id]||C[id].token)delete g.col[id];else g.col[id].lv=Math.max(1,Math.min(MAX_LV,g.col[id].lv||1))});
  fixParty(g);g.jail=(g.jail||[]).filter(j=>C[j.id]);return g}
function readSlot(n){const s=lsGet(SLOT_KEY(n));if(!s)return null;try{return fixSave(JSON.parse(s))}catch(e){return null}}
function save(){if(!G||!HUMAN&&!window.__SIMSAVE)return;G.last=Date.now();lsSet(SLOT_KEY(CUR),JSON.stringify(G))}
/* 前のバージョンのデータを引っこす */
function migrateV1(){
  const s=lsGet('wippy-bounty-journey-v1');if(!s||lsGet(SLOT_KEY(1)))return;
  try{const o=JSON.parse(s),g=freshSave();g.col={};
    Object.entries(o.col||{}).forEach(([id,e])=>{if(C[id]&&!C[id].token&&!C[id].out)g.col[id]={lv:Math.min(5,e.lv||1),n:e.n||0}});
    (o.caught||[]).forEach(id=>{if(C[id])g.jail.push({id,lv:1,until:1})});
    if(!Object.keys(g.col).length)return;
    g.party=(o.party||[]).filter(id=>g.col[id]).slice(0,8);if(!g.party.length)g.party=Object.keys(g.col).slice(0,8);
    g.money=Math.round((o.money||0)*3)+30;g.runs=o.runs||0;g.intro=1;Object.keys(g.col).forEach(id=>g.seen[id]=1);
    lsSet(SLOT_KEY(1),JSON.stringify(g))}catch(e){}}
/* 引っこしコード（ほかのスマホやブラウザへ） */
function makeCode(g){return 'WIPPY2-'+btoa(unescape(encodeURIComponent(JSON.stringify(g))))}
function readCode(code){try{code=code.trim().replace(/\s/g,'');if(!code.startsWith('WIPPY2-'))return null;
  const g=JSON.parse(decodeURIComponent(escape(atob(code.slice(7)))));if(!g||typeof g.money!=='number'||!g.col)return null;return fixSave(g)}catch(e){return null}}

