/* ElevenLabsの声：voice/ に v_ID_s.mp3（よぶ）v_ID_t.mp3（出会い）w_ID.mp3（ウィピィの返事）を置くと自動で使う */
const VOICE={on:VOICE_FILES.size?lsGet('wippy-voice')!=='0':lsGet('wippy-voice')==='1',ja:null,cur:null,cache:{}};
function playClip(key){try{if(VOICE.cur){VOICE.cur.pause();VOICE.cur.currentTime=0}let a=VOICE.cache[key];if(!a){a=new Audio('voice/'+key+'.mp3');a.preload='auto';VOICE.cache[key]=a}a.volume=.95;VOICE.cur=a;a.currentTime=0;const p=a.play();if(p&&p.catch)p.catch(()=>{})}catch(e){}}
function preloadClips(keys){for(const k of keys)if(VOICE_FILES.has(k)&&!VOICE.cache[k]){const a=new Audio();a.preload='auto';a.src='voice/'+k+'.mp3';VOICE.cache[k]=a}}
function pickJa(){try{if(VOICE.ja||!window.speechSynthesis)return VOICE.ja;const v=speechSynthesis.getVoices().filter(v=>/^ja/i.test(v.lang));VOICE.ja=v.find(x=>/Kyoko|O-ren|Nanami|Haruka|female/i.test(x.name))||v[0]||null;return VOICE.ja}catch(e){return null}}

const voicePitch=id=>{if(id==='wippy')return 1.9;let h=0;for(const c of String(id))h=(h*31+c.charCodeAt(0))%997;return 1.15+(h%60)/100};
function speak(text,id='wippy',key){if(!HUMAN||MUTED||!VOICE.on)return;if(key&&VOICE_FILES.has(key)){playClip(key);return}if(VOICE_FILES.size||!window.speechSynthesis)return;try{const t=String(text).replace(/<[^>]+>/g,'').replace(/[\u{1F000}-\u{1FFFF}☀-➿]/gu,'').trim();if(!t)return;
  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';const v=pickJa();if(v)u.voice=v;u.pitch=Math.min(2,voicePitch(id));u.rate=1.08;u.volume=.9;speechSynthesis.speak(u)}catch(e){}}


