/* 勝ったとき・負けたときのジングル（1回だけ鳴る） */
function jingle(kind){if(!HUMAN||MUTED)return;const J={win:[[72,0],[76,.12],[79,.24],[84,.36],[79,.54],[84,.66]],lose:[[67,0],[66,.25],[65,.5],[64,.8]],clear:[[72,0],[72,.1],[72,.2],[76,.3],[79,.5],[77,.7],[79,.8],[84,1.0]]}[kind]||[];
  J.forEach(([m,t])=>tone(N_(m),kind==='lose'?.4:.3,{type:'square',vol:.05,at:t}));if(kind!=='lose')[60,64,67,72].forEach(m=>tone(N_(m),.9,{type:'triangle',vol:.05,at:J[J.length-1][1]}))}
const MUS={cur:null,timer:null,step:0,nextT:0,bus:null};
function musBus(){const a=ac();if(!a)return null;if(!MUS.bus){MUS.bus=a.createGain();MUS.bus.gain.value=.8;MUS.bus.connect(a.destination)}return MUS.bus}
function playStep(tr,i,t,a=AC,bus=musBus()){const spb=60/tr.bpm/2;
  const b=tr.bass[i];if(b){const o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=N_(b);g.gain.setValueAtTime(.16,t);g.gain.exponentialRampToValueAtTime(.001,t+spb*(tr.stride?1.6:.9));o.connect(g).connect(bus);o.start(t);o.stop(t+spb*2)}
  if(tr.chords&&(i%8===2||i%8===6)){tr.chords[Math.floor(i/8)].forEach(m=>{const o=a.createOscillator(),g=a.createGain();o.type='triangle';o.frequency.value=N_(m);g.gain.setValueAtTime(.045,t);g.gain.exponentialRampToValueAtTime(.001,t+.16);o.connect(g).connect(bus);o.start(t);o.stop(t+.2)})}
  const m=tr.lead[i];if(m>0){let len=1;while(tr.lead[(i+len)%32]===-1&&len<8)len++;const d=spb*len*.95;const o=a.createOscillator(),g=a.createGain();o.type=tr.wave||'triangle';o.frequency.value=N_(m);
    if(tr.vib){const l=a.createOscillator(),lg=a.createGain();l.frequency.value=5.5;lg.gain.value=6;l.connect(lg).connect(o.frequency);l.start(t);l.stop(t+d)}
    let node=g;if(tr.wave==='square'||tr.wave==='sawtooth'){const f=a.createBiquadFilter();f.frequency.value=2200;g.connect(f);node=f}
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(tr.lv,t+.02);g.gain.setValueAtTime(tr.lv,t+d*.7);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);node.connect(bus);o.start(t);o.stop(t+d+.02)}
  const dc=tr.drum[i];
  if(dc==='k'||dc==='K'){const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(150,t);o.frequency.exponentialRampToValueAtTime(45,t+.12);g.gain.setValueAtTime(dc==='K'?.45:.32,t);g.gain.exponentialRampToValueAtTime(.001,t+.14);o.connect(g).connect(bus);o.start(t);o.stop(t+.15)}
  else if(dc==='s')noise(.11,{vol:.16,freq:1800,type:'bandpass',t0:t,dest:bus,ctx:a});
  else if(dc==='h')noise(.035,{vol:.07,freq:7000,type:'highpass',t0:t,dest:bus,ctx:a});
  else if(dc==='t'||dc==='b'){const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=dc==='t'?1050:720;g.gain.setValueAtTime(.09,t);g.gain.exponentialRampToValueAtTime(.001,t+.05);o.connect(g).connect(bus);o.start(t);o.stop(t+.06)}
}
/* 曲は先に「1ループぶんの音」に書き出して、くり返し再生する。画面が重くても音がとぎれない */
MUS.buf={};MUS.src=null;MUS.rendering={};
function renderTrack(name){const tr=TRACKS[name];if(!tr||MUS.buf[name]||MUS.rendering[name]||!AC)return MUS.rendering[name]||Promise.resolve(MUS.buf[name]);
  const spb=60/tr.bpm/2,len=spb*32,sr=AC.sampleRate;const O=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!O)return Promise.resolve(null);
  let oc;try{oc=new O(1,Math.ceil((len+1)*sr),sr)}catch(e){return Promise.resolve(null)}
  const bus=oc.createGain();bus.gain.value=.7;bus.connect(oc.destination);
  for(let i=0;i<32;i++)playStep(tr,i,i*spb,oc,bus);
  /* ループの最後にはみ出た音（のびる音）を頭に重ねて、つなぎ目をなめらかに */
  const pr=new Promise(res=>{oc.oncomplete=e=>res(e.renderedBuffer);const r=oc.startRendering();if(r&&r.then)r.then(res).catch(()=>res(null))}).then(full=>{if(!full)return null;
    const n=Math.round(len*sr),b=AC.createBuffer(1,n,sr),src=full.getChannelData(0),dst=b.getChannelData(0);for(let k=0;k<n;k++)dst[k]=src[k];for(let k=n;k<src.length&&k-n<n;k++)dst[k-n]+=src[k];
    /* 曲ごとの音量をそろえる（平均の大きさを同じに） */let e=0,pk=0;for(let k=0;k<n;k++){e+=dst[k]*dst[k];pk=Math.max(pk,Math.abs(dst[k]))}const rms=Math.sqrt(e/n)||1;const gn=Math.min(.045/rms,.9/(pk||1));for(let k=0;k<n;k++)dst[k]*=gn;
    MUS.buf[name]=b;delete MUS.rendering[name];return b});
  MUS.rendering[name]=pr;return pr}
function prerenderAll(){if(!AC)return;let p=Promise.resolve();Object.keys(TRACKS).forEach(n=>{p=p.then(()=>renderTrack(n)).then(()=>new Promise(r=>setTimeout(r,50)))})}
function musStop(){clearInterval(MUS.timer);MUS.timer=null;if(MUS.src){try{MUS.src.stop()}catch(e){}MUS.src.disconnect();MUS.src=null}}
function musLoop(name,at,offset=0){const b=MUS.buf[name];if(!b||!AC)return false;const s=AC.createBufferSource();s.buffer=b;s.loop=true;s.connect(musBus());s.start(at,offset%b.duration);MUS.src=s;return true}
/* 町の曲（mp3）は、ファイル自体の音量をほかの曲にそろえてある（iPhoneは audio.volume が効かないため） */
function music(name){
  if(!HUMAN)return;if(MUS.cur===name&&(name!=='town'||!$('bgm').paused||MUTED))return;MUS.cur=name;
  musStop();const mp3=$('bgm');
  if(MUTED){mp3.pause();return}
  if(name==='town'){mp3.volume=1;mp3.play().catch(()=>{});return}
  mp3.pause();const tr=TRACKS[name];const a=ac();if(!tr||!a)return;
  if(musLoop(name,a.currentTime+.05))return;
  /* まだ書き出し中：いつもの方法で鳴らしておいて、できたら切りかえる */
  MUS.step=0;MUS.nextT=a.currentTime+.08;const spb=60/tr.bpm/2;
  MUS.timer=setInterval(()=>{if(MUTED||!AC)return;if(MUS.nextT<AC.currentTime)MUS.nextT=AC.currentTime+.05;while(MUS.nextT<AC.currentTime+1.5){playStep(tr,MUS.step,MUS.nextT);MUS.nextT+=spb;MUS.step=(MUS.step+1)%32}},60);
  renderTrack(name).then(b=>{if(!b||MUS.cur!==name||!MUS.timer)return;clearInterval(MUS.timer);MUS.timer=null;musLoop(name,MUS.nextT,MUS.step*spb)});
}
/* iPhoneで音が止められても、自動で戻す */
setInterval(()=>{if(AC&&HUMAN&&!MUTED&&AC.state!=='running'&&AC.state!=='closed')AC.resume().catch(()=>{})},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden||MUTED)return;if(AC)AC.resume().catch(()=>{});if(MUS.cur==='town'){const m=$('bgm');if(m&&m.paused)m.play().catch(()=>{})}});
function setMute(m){MUTED=m;lsSet('wippy-mute',m?'1':'0');$('mute').textContent=m?'🔇':'🔊';const c=MUS.cur;if(m){musStop();$('bgm').pause()}else{MUS.cur=null;music(c||'town')}}

