function burst(el,chars,n=10,spread=90){if(!HUMAN||!el)return;const r=el.getBoundingClientRect();const x=r.left+r.width/2,y=r.top+r.height/2;
  for(let i=0;i<n;i++){const s=document.createElement('span');s.className='pt';s.textContent=Array.isArray(chars)?pick(chars):chars;const ang=Math.random()*Math.PI*2,d=spread*(.4+Math.random()*.8);
    s.style.left=x+'px';s.style.top=y+'px';s.style.setProperty('--dx',Math.cos(ang)*d+'px');s.style.setProperty('--dy',Math.sin(ang)*d-30+'px');document.body.appendChild(s);setTimeout(()=>s.remove(),950)}}
function shakeApp(){if(!HUMAN)return;const a=app();a.classList.remove('shake');void a.offsetWidth;a.classList.add('shake')}
function flash(){if(!HUMAN)return;const f=document.createElement('div');f.className='flash';document.body.appendChild(f);setTimeout(()=>f.remove(),650)}
function toast(t,...a){SFX.ding&&SFX.ding();return toast0(t,...a)}
function toast0(t){if(!HUMAN)return;const e=document.createElement('div');e.className='toast';e.innerHTML=t;document.body.appendChild(e);setTimeout(()=>e.remove(),2700)}

