function artStyle(id){const c=C[id];return c.img?`background-image:url(${artUrl(c.img)})`:''}
function artHtml(id){const c=C[id];return c.img?`<div class="art img" style="${artStyle(id)}"></div>`:`<div class="art">${c.em}</div>`}

const KW_IC={taunt:'🛡️',shield:'💠',twice:'✌️',quick:'⚡',revive:'👼',home:'🏠',thorns:'🌵',stealth:'👻',lone:'🐺',nostun:'🥛',deadly:'💀',noattack:'🚫',splash:'🪓',feed:'🍖',pack:'🐾'};
/* アイコンごとに背景色を変える（同じ丸だと見分けがつかないので） */
const KW_COL={grow:'#58b04a',taunt:'#6b7a8f',shield:'#1a9fd4',twice:'#f08a24',quick:'#e6b800',revive:'#ff6fb5',home:'#9a6b3f',thorns:'#3a9a48',stealth:'#6a4fc8',lone:'#7a7a7a',nostun:'#5fb8e8',deadly:'#2a2a2a',noattack:'#a33a3a',splash:'#d9452b',feed:'#c8743c',pack:'#a8834a',
  poison:'#8a3ad0',bounty:'#e0443a',onkill:'#b08a3a',fuel:'#555',aura:'#d9a520',bc:'#ff7a1a',dr:'#3f4a5c'};
/* 短い名前（カードの上に出す用） */
const KW_SHORT={grow:'そだつ？',taunt:'かばう',shield:'バリア',twice:'2回',quick:'早撃',revive:'復活',home:'わが家',thorns:'トゲ',stealth:'かくれ',lone:'一匹狼',nostun:'ミルク',deadly:'一撃',noattack:'攻撃×',splash:'まわり',feed:'ごはん',pack:'群れ',
  poison:'毒',bounty:'賞金',onkill:'ごほうび',fuel:'燃料',aura:'応援',bc:'見参',dr:'やられたら'};
/* カードの効果を「アイコン＋説明」のリストにする  [icon, 名前, 説明, 色, 短い名前] */
function effList(id,lv){const d=C[id],L=[];const E=(k,ic,n,t)=>L.push([ic,n,t,KW_COL[k],KW_SHORT[k]]);
  d.kw.split(' ').filter(Boolean).forEach(k=>E(k,KW_IC[k],KW_T[k],KW_HELP[k]));
  if(d.poison)E('poison','☠️','毒',`戦った相手に毒×${d.poison}（毎ターン1ダメージずつ）`);
  if(d.bounty)E('bounty','🎯','賞金稼ぎ',`賞金首とボスに攻撃+${valX(d.bounty,lv)}`);
  if(d.onkill)E('onkill','📜','ごほうび','敵をたおすと なかまを1人 ひく');
  if(d.fuel)E('fuel','⛽','燃料',`${d.fuel}ターンで退場`);
  if(d.aura)E('aura','✨','いるあいだ',auraText(d,lv).replace(/^いるあいだ、/,''));
  if(d.bc)E('bc','📣','見参！',bcText(d,lv));
  if(d.dr)E('dr','🪦','やられたら',drText(d,lv));
  if(d.grow)E('grow','🌱','そだつ…かも','合成で レベルが 上がると、ほかの子より すこしだけ つよく なる');
  return L}
const kwChip=x=>`<i style="--k:${x[3]||'#7a5a3a'}">${x[0]}<b>${x[4]||x[1]}</b></i>`;
function cardEl(id,lv=1,{badge,cls='',cost,hideLv=false,plus=0}={}){
  const c=C[id],el=document.createElement('div');el.className=`card ${c.r} ${cls}`;el.dataset.cid=id;el.dataset.clv=lv;
  const holo=c.r!=='N'||c.st>1;const ic=effList(id,lv).slice(0,3).map(kwChip).join('');
  const evoLine=c.evo||c.st>1;const nl=[...c.n].length;
  el.innerHTML=`${artHtml(id)}${holo?'<div class="shine"></div>':''}<div class="fr"></div>
    <div class="nm${nl>9?' xlong':nl>6?' long':''}">${c.n}</div>
    <span class="stat cost">${cost??c.c}</span>${c.token?'':`<img class="rar" src="${{N:'@@D7@@',R:'@@D8@@',L:'@@D9@@'}[c.r]||'@@D7@@'}" alt="">`}
    ${evoLine?`<span class="stars">${[1,2,3].map(i=>`<img src="${i<=c.st?'@@D10@@':'@@D11@@'}" alt="">`).join('')}</span>`:''}
    ${c.out?'<span class="rib">お尋ね者</span>':''}${c.token||hideLv?'':`<span class="lv${lv>=MAX_LV?' max':''}">${lv>=MAX_LV?'MAX':'Lv'+lv}${plus?' ＋'+plus:''}</span>`}
    <div class="tb">${ic?`<div class="kws">${ic}</div>`:''}</div>
    <span class="stat a${plus>0?' up':''}">${statA(id,lv)+plus}</span><span class="stat h${plus>0?' up':''}">${statH(id,lv)+plus}</span>${badge?`<span class="badge">${badge}</span>`:''}`;
  return el}
/* 回転するコインの山（手札の上にのせる。前に作ったやつ） */
const coinStack=(n,poo)=>`<div class="stack" aria-label="${n}コイン">${poo?'<span style="font-size:18px">💩</span>':Array.from({length:Math.min(n,10)},(_,i)=>`<div class="coin" style="z-index:${10-i}"><div class="spin" style="--i:${i}"><div class="face back"><svg viewBox="0 0 100 100"><use href="#coin"/></svg></div><div class="edge e2"></div><div class="edge e1"></div><div class="face front"><svg viewBox="0 0 100 100"><use href="#coin"/></svg></div></div></div>`).join('')}</div>`;
/* コインが飛んでいく演出 */
function coinFly(from,to,n=1){if(!HUMAN||!from||!to)return;const a=from.getBoundingClientRect(),b=to.getBoundingClientRect();
  for(let i=0;i<Math.min(n,8);i++){const c=document.createElement('div');c.className='flycoin';c.innerHTML='<svg viewBox="0 0 100 100"><use href="#coin"/></svg>';document.body.appendChild(c);
    const x0=a.left+a.width/2+(Math.random()-.5)*30,y0=a.top+a.height/2+(Math.random()-.5)*20,x1=b.left+b.width/2,y1=b.top+b.height/2;
    const an=c.animate([{transform:`translate(${x0}px,${y0}px) scale(.6) rotateY(0)`,opacity:0},{transform:`translate(${(x0+x1)/2}px,${Math.min(y0,y1)-70}px) scale(1.25) rotateY(540deg)`,opacity:1,offset:.5},{transform:`translate(${x1}px,${y1}px) scale(.7) rotateY(1080deg)`,opacity:1}],{duration:620+i*70,delay:i*70,easing:'cubic-bezier(.4,0,.6,1)',fill:'both'});
    an.onfinish=()=>{c.remove();SFX.tink();if(i===0){to.animate([{transform:'scale(1.35)'},{transform:'scale(1)'}],{duration:260});SFX.coin&&SFX.coin()}}}}

function sheetCard(id,lv,body,acts,plus=0){const c=C[id];const L=effList(id,lv);
  $('sheet').innerHTML=`<div class="in"><div id="shc"></div><div><h3>${c.n} <span class="small">${lv>=MAX_LV?'Lv MAX':'Lv'+lv}${plus?' ＋'+plus:''}</span></h3><p class="q">「${c.s}」</p>
    <div class="kwlist">${L.length?L.map(x=>`<div><i style="background:${x[3]}">${x[0]}</i><span><b>${x[1]}</b>：${x[2]}</span></div>`).join(''):''}</div>${body||''}
    <div class="acts">${acts||''}<button class="btn ghost" id="shX">とじる</button></div></div></div>`;
  $('shc').appendChild(cardEl(id,lv,{plus}));$('sheet').hidden=false;$('shX').onclick=closeSheet;
  /* マークをタップすると、ふきだしで説明 */
  const bind=els=>els.forEach((e,i)=>{if(!L[i])return;e.classList.add('kwtap');e.onclick=ev=>{ev.stopPropagation();kwBubble(e,L[i])}});
  bind([...$('shc').querySelectorAll('.kws i')]);bind([...$('sheet').querySelectorAll('.kwlist i')])}
const KW_WHAT={'そだつ…かも':'しょうらい つよく なる…かも','見参！':'よびだした ときに でる こうか','やられたら':'やられた ときに でる こうか','いるあいだ':'場に いるあいだ ずっと きく','ごほうび':'てきを たおした ときの ごほうび','賞金稼ぎ':'賞金首と ボスに つよい','毒':'たたかった あいてに 毒','燃料':'しばらくすると いなくなる'};
function kwBubble(el,x){tipBubble(el,x[0],x[1],x[2],x[3],KW_WHAT[x[1]]||'')}
function tipBubble(el,ic,title,text,col='#7a5a3a',what=''){document.querySelectorAll('.kwbub').forEach(b=>b.remove());SFX.pop&&SFX.pop();
  const b=document.createElement('div');b.className='kwbub';b.style.setProperty('--k',col||'#7a5a3a');
  b.innerHTML=`<div class="kh"><i>${ic}</i><b>${title}</b></div>${what?`<div class="kw2">${what}</div>`:''}<div class="kt">${text}</div>`;
  document.body.appendChild(b);const r=el.getBoundingClientRect(),w=b.offsetWidth,h=b.offsetHeight;
  const up=r.top>h+20;b.classList.add(up?'up':'dn');
  b.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+'px';b.style.top=(up?r.top-h-12:r.bottom+12)+'px';
  b.style.setProperty('--ax',Math.max(18,Math.min(w-18,r.left+r.width/2-parseFloat(b.style.left)))+'px');
  const off=()=>{b.classList.add('out');setTimeout(()=>b.remove(),200);document.removeEventListener('pointerdown',off,true)};
  setTimeout(()=>document.addEventListener('pointerdown',off,true),50)}
function closeSheet(){document.querySelectorAll('.kwbub').forEach(b=>b.remove());$('sheet').hidden=true;$('sheet').classList.remove('top')}
function modal(html){if(typeof clearCoach==='function')clearCoach();const m=$('modal');m.innerHTML=`<div class="box">${html}</div>`;m.hidden=false;return m}
function closeModal(){$('modal').hidden=true}
