/* やりこみチェック */
const gemOf=a=>Math.max(1,Math.round(a.pay/10));
function checkAch(){if(!G)return;ACH.forEach(a=>{if(!G.ach[a.id]&&a.t(G)){G.ach[a.id]=1;G.gems=(G.gems||0)+gemOf(a);if(G.runs>=4){toast(`🏆 やりこみ達成！「${a.n}」 ＋💎${gemOf(a)}`);SFX.sparkle()}}});save()}

/* 勝利のハンコ＋コインの雨 */
async function winFx(txt='勝利！'){if(!HUMAN)return;const w=document.createElement('div');w.className='winban';w.innerHTML=`<div class="rays"></div><div class="wp" style="background-image:url(${HERO.pose(3)})"></div><div class="w">${txt}</div>`;document.body.appendChild(w);
  for(let i=0;i<14;i++){const c=document.createElement('div');c.className='flycoin';c.innerHTML='<svg viewBox="0 0 100 100"><use href="#coin"/></svg>';document.body.appendChild(c);
    const x=innerWidth*(.15+Math.random()*.7);c.animate([{transform:`translate(${x}px,-40px) rotateY(0)`},{transform:`translate(${x+(Math.random()-.5)*80}px,${innerHeight+40}px) rotateY(${720+Math.random()*720}deg)`}],{duration:900+Math.random()*700,delay:Math.random()*400,easing:'cubic-bezier(.5,0,.8,.6)',fill:'both'}).onfinish=()=>c.remove()}
  SFX.coin();await sleep(1150);w.remove()}

/* かけあいの場面（相手 → ウィピィ → 結果）。できごとなどで使う */
function talkScene(foe,heroLine,result,face=1){return new Promise(res=>{const st=$('stage');st.hidden=false;
  st.innerHTML=`<div class="talk"><div class="rays"></div>
    <div class="trow foe"><div class="fp">${foe.img?`<div class="hart" style="background-image:url(${foe.img})"></div>`:`<span>${foe.em||'❓'}</span>`}</div><div class="tb"><b>${foe.name}</b><p>「${foe.line}」</p></div></div>
    <div class="trow me" hidden><div class="tb"><b>${HERO.name}</b><p>「${heroLine}」</p></div><div class="fp"><div class="hart" style="background-image:url(${HERO.face(face)})"></div></div></div>
    ${result?`<div class="tres" hidden>${result}</div>`:''}<div class="ttap">タップ ▼</div></div>`;
  speak(foe.line,foe.name);let step=0,tl=performance.now();const next=()=>{if(performance.now()-tl<450)return;tl=performance.now();step++;if(step===1){st.querySelector('.trow.me').hidden=false;SFX.blip(900);speak(heroLine,'wippy')}
    else if(step===2&&result){const r=st.querySelector('.tres');r.hidden=false;(/bad/.test(result)?SFX.bad:SFX.coin)()}
    else{st.onclick=null;st.hidden=true;res()}};
  SFX.blip(500);st.onclick=next})}

/* どこを押しても小さく「カチッ」 */
document.addEventListener('pointerdown',e=>{if(e.target.closest&&e.target.closest('button,.pop,.an,.card,.u,.fac button,.slot'))SFX.click()},{passive:true});

/* カードや仲間を長押しすると、くわしい説明が出る */
(()=>{let t=null,sx=0,sy=0,fired=false;
  const target=e=>e.target.closest&&e.target.closest('[data-cid]');
  document.addEventListener('pointerdown',e=>{const el=target(e);fired=false;if(!el||el.closest('#sheet'))return;sx=e.clientX;sy=e.clientY;clearTimeout(t);
    t=setTimeout(()=>{fired=true;if(navigator.vibrate)navigator.vibrate(15);SFX.pop&&SFX.pop();const id=el.dataset.cid,lv=+el.dataset.clv||1;sheetCard(id,lv);$('sheet').classList.add('top')},450)},true);
  const cancel=()=>clearTimeout(t);
  document.addEventListener('pointermove',e=>{if(Math.abs(e.clientX-sx)+Math.abs(e.clientY-sy)>12)cancel()},true);
  document.addEventListener('pointerup',cancel,true);document.addEventListener('pointercancel',cancel,true);
  document.addEventListener('click',e=>{if(fired){fired=false;e.stopPropagation();e.preventDefault()}},true);
  document.addEventListener('contextmenu',e=>{if(target(e))e.preventDefault()});})();


/* バージョン：おおきい変更.機能を足した.小さな直し　（1.0.0 = 正式リリース） */
const VERSION='0.76.0';
/* =====================================================================
   タイトル・データ管理
   ===================================================================== */
function slotInfo(g){return `${g.run&&g.run.map?'<i class="pill run" style="font-style:normal">⏸ 冒険のとちゅう</i><br>':''}<b>${g.day}日目 ・ ＄${g.money}</b><br>冒険${g.runs}回 ・ 図鑑 ${Object.keys(g.seen).length}/${COLLECT.length} ・ やりこみ ${Object.keys(g.ach).length}/${ACH.length}${g.clear.wild?` ・ 🏜️Lv${g.clear.wild}`:''}${g.clear.hill?` ・ ⚰️Lv${g.clear.hill}`:''}`}
function title(){
  G=null;R=null;B=null;closeSheet();closeModal();setBg('bg/bg_sunset.jpg');hideHair();music('title');
  app().innerHTML=`<div class="logo"><div class="t1">賞金稼ぎの旅</div><div class="t2">ウィピィのモンスターカードバトル</div></div>
    <div class="panel"><h2>データ</h2><p class="small" style="margin-top:2px">あそぶデータをえらんでね（このブラウザに自動でセーブされる）</p></div>
    <div id="slots" style="display:grid;gap:9px"></div>
    <div class="row" style="justify-content:center;margin-top:4px"><button class="btn ghost" id="mv">📦 引っこし（ほかのスマホへ）</button></div>
    <div class="fukugen"><input id="fk" placeholder="ふくげんコード" autocomplete="off" autocapitalize="off"><button class="btn" id="fkb">OK</button></div>
    <p class="small" style="text-align:center;opacity:.75">ver ${VERSION}${/テスト/.test(document.title)?'（テスト版）':''}</p>`;
  for(let n=1;n<=3;n++){const g=readSlot(n),d=document.createElement('div');d.className='slot';
    d.innerHTML=`<div class="no">${n}</div><div class="info">${g?slotInfo(g):'<b>からっぽ</b><br>新しい賞金稼ぎをはじめる'}</div>
      ${g?`<div style="display:grid;gap:6px"><button class="btn" data-p>プレイ</button><button class="btn ghost" data-d>けす</button></div>`:`<button class="btn green" data-n>はじめから</button>`}`;
    const p=d.querySelector('[data-p]'),x=d.querySelector('[data-d]'),nw=d.querySelector('[data-n]');
    if(p)p.onclick=()=>{SFX.tap();CUR=n;G=g;enterTown()};
    if(nw)nw.onclick=()=>{SFX.tap();CUR=n;G=freshSave();save();enterTown()};
    if(x)x.onclick=()=>{modal(`<h2>データ${n}をけす？</h2><p class="muted">${slotInfo(g)}</p><p class="muted" style="margin-top:6px">集めた なかまも 賞金もぜんぶ消えて、もどせません。</p>
      <div class="row" style="margin-top:12px"><button class="btn ghost" id="no">やめる</button><span class="sp"></span><button class="btn red" id="yes">けす</button></div>`);
      $('no').onclick=closeModal;$('yes').onclick=()=>{lsDel(SLOT_KEY(n));SFX.bad();closeModal();title()}};
    $('slots').appendChild(d)}
  $('mv').onclick=moveData;
  const fk=()=>{const v=$('fk').value.trim().toLowerCase();if(v==='test'){testSlots();SFX.win();toast('🧪 テストデータを入れたよ');title()}else if(v==='boss'&&typeof bossGallery==='function'){$('fk').value='';bossGallery()}else if(v==='bossbattle'&&typeof bossBattleMenu==='function'){$('fk').value='';bossBattleMenu()}else if(v==='book'&&typeof bookView==='function'){$('fk').value='';SFX.win&&SFX.win();bookView()}else{SFX.bad&&SFX.bad();toast('コードがちがうみたい…')}};
  $('fkb').onclick=fk;$('fk').onkeydown=e=>{if(e.key==='Enter')fk()};
}
/* 【テスト用】ふくげんコード「test」：1＝からっぽ、2＝1面クリア後、3＝2面クリア後 */
function testSave(stage){const g=freshSave();const add=(ids,lv)=>ids.forEach(id=>{if(!C[id])return;g.col[id]={lv,n:0};g.seen[id]=1});
  Object.assign(g,{intro:1,runs:stage===1?3:7,day:stage===1?4:9,money:stage===1?120:260,wallet:3+stage,clear:{wild:1,hill:stage>=2?1:0},best:{wild:7,hill:stage>=2?9:0}});
  add(['kishi','tenshu','wolf','gila','hawk','bull','sabota','armadillo'],stage===1?2:3);
  if(stage>=2)add(['crow','doc','mia','ranger','garako','sandman','bonedoc','herb','stella','hoho'],2);
  g.col.pochi.lv=stage===1?3:5;g.col.rookie.lv=stage===1?2:4;g.col.annie.lv=stage===1?2:3;g.col.akudo.n=1;g.col.zombie.lv=stage===1?1:3;
  g.party=stage===1?['pochi','rookie','akudo','annie','jacka','kishi','wolf','zombie']:['pochi','rookie','annie','kishi','doc','crow','garako','zombie'];
  g.unl=stage===1?{board:1,party:1,data:1,shop:1,saloon:1,dex:1}:{board:1,party:1,data:1,shop:1,saloon:1,dex:1,ach:1,sheriff:1};g.unlSeen={...g.unl};
  g.st.wins=stage===1?14:32;g.st.caught=stage;g.st.merges=stage===1?1:4;
  if(stage>=2)g.jail=[{id:'zombino',lv:2,until:0}];return g}
function testSlots(){lsDel(SLOT_KEY(1));lsSet(SLOT_KEY(2),JSON.stringify(testSave(1)));lsSet(SLOT_KEY(3),JSON.stringify(testSave(2)))}
function moveData(){
  const opts=[1,2,3].map(n=>({n,g:readSlot(n)}));
  modal(`<h2>📦 引っこし</h2><p class="muted">データを「引っこしコード」にして、ほかのスマホやブラウザに持っていける。</p>
    <div class="choice">${opts.map(o=>`<button data-out="${o.n}" ${o.g?'':'disabled'}><span class="i">📤</span><div>データ${o.n}のコードを出す<small>${o.g?o.g.day+'日目 ・ ＄'+o.g.money:'からっぽ'}</small></div></button>`).join('')}
    <button id="in"><span class="i">📥</span><div>コードを読みこむ<small>はりつけたデータを、えらんだスロットに入れる</small></div></button></div>
    <button class="btn ghost" id="cx" style="width:100%">とじる</button>`);
  $('cx').onclick=closeModal;
  document.querySelectorAll('[data-out]').forEach(b=>b.onclick=()=>{const g=readSlot(+b.dataset.out),code=makeCode(g);
    modal(`<h2>データ${b.dataset.out}の引っこしコード</h2><p class="muted">ぜんぶコピーして、新しいほうで「コードを読みこむ」にはりつけてね。</p><textarea class="code" id="ct" readonly>${code}</textarea>
      <div class="row"><button class="btn" id="cp">コピー</button><span class="sp"></span><button class="btn ghost" id="cx">とじる</button></div>`);
    $('cx').onclick=closeModal;$('cp').onclick=async()=>{const t=$('ct');t.select();let ok=false;try{await navigator.clipboard.writeText(code);ok=true}catch(e){try{ok=document.execCommand('copy')}catch(e2){}}$('cp').textContent=ok?'コピーした！':'長押しでコピーしてね'}});
  $('in').onclick=()=>{modal(`<h2>コードを読みこむ</h2><textarea class="code" id="ci" placeholder="WIPPY2-…"></textarea>
      <div class="row">入れる場所：${[1,2,3].map(n=>`<label class="small"><input type="radio" name="sl" value="${n}" ${n===1?'checked':''}> データ${n}</label>`).join(' ')}</div>
      <p class="small" id="ce" style="margin:6px 0"></p><div class="row"><button class="btn ghost" id="cx">やめる</button><span class="sp"></span><button class="btn" id="cl">読みこむ</button></div>`);
    $('cx').onclick=closeModal;$('cl').onclick=()=>{const g=readCode($('ci').value);if(!g){$('ce').textContent='コードが読めなかった…もう一度コピーしてみてね';return}
      const n=+document.querySelector('input[name=sl]:checked').value;lsSet(SLOT_KEY(n),JSON.stringify(g));SFX.win();closeModal();title()}};
}

/* =====================================================================
   町（拠点）
   ===================================================================== */
const FAC=[
  {id:'board',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'しょうきん首',d:'てはいしょを えらんで 冒険へ'},
  {id:'party',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'なかま',d:'合成・進化・連れていく仲間'},
  {id:'shop',ic:'<img class="fi" src="@@D12@@" alt="">',n:'雑貨屋',d:'パック・旅の道具'},
  {id:'saloon',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'酒場',d:'うわさ話を聞く'},
  {id:'sheriff',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'保安官事務所',d:'お尋ね者を突き出す・説得する'},
  {id:'dex',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'図鑑',d:'集めた なかま'},
  {id:'ach',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'やりこみ',d:'達成すると💎ジェム'},
  {id:'data',ic:'<img class="fi" src="data:image/png;base64," alt="">',n:'データ',d:'タイトルにもどる'},
];
/* 施設は少しずつ解放。解放されるまでボタン自体が見えない */
/* 10/28：しせつは「クリアした回数」で ひらく（とちゅうで 帰っても ひらかない）。いちど ひらいた ものは そのまま */
const clrN=g=>Math.max((g.st&&g.st.clr)||0,Object.values(g.clear||{}).filter(v=>v>0).length);
const FAC_OPEN={board:g=>1,party:g=>clrN(g)>=1,data:g=>clrN(g)>=1,shop:g=>clrN(g)>=2,sheriff:g=>g.st.caught>0||g.jail.length>0,saloon:g=>clrN(g)>=3,dex:g=>clrN(g)>=3,ach:g=>clrN(g)>=4};

const facOpen=f=>!!((G.unlSeen&&G.unlSeen[f.id])||FAC_OPEN[f.id](G));
function ensureRumor(){if(G.rumor)return;
  G.rumor={elite:pick(STAGES.wild.elites),floor:3+rnd(5),feature:pick(PACK_POOL.filter(id=>C[id].r!=='N'&&C[id].c<=(G.wallet||3))),event:pick(['gold','storm','party','relic'])};save()}
function enterTown(){if(!G.intro)return intro();if(G.run&&G.run.map)return resumeAsk();music('town');town()}
/* 冒険のとちゅうでアプリを閉じても、マップから つづきが できる */
function resumeAsk(){const r=G.run,s=STAGES[r.sid]||STAGES.wild;setBg(s.bg);music('town');
  app().innerHTML='';const _k=Math.max(0,Object.keys(STAGES).indexOf(r.sid)),_P=WANTED_UI[_k%3];modal(`<div class="unlock"><div class="rsposter"><div class="wpp" style="aspect-ratio:${_P.ar};--wl:${_P.w[0]*100}%;--wt:${_P.w[1]*100}%;--ww:${(_P.w[2]-_P.w[0])*100}%;--wh:${(_P.w[3]-_P.w[1])*100}%"><div class="wpart"><span style="background-image:url(${cardArt(s.boss)})"></span></div><div class="wpimg" style="background-image:url(${_P.img})"></div><div class="wpname">${C[s.boss].n}</div></div></div><h2>冒険の とちゅう！</h2><p class="money">${s.n}${r.star?' ・ レベル'+(r.star+1):''}</p>
    <p class="small">❤️ ${r.hp}/${r.maxhp} ・ ＄${r.money} ・ ${r.floor}/${r.floors}マス${r.caught&&r.caught.length?' ・ 🪢'+r.caught.length:''}</p>
    <button class="btn big green" id="rs" style="width:100%;margin-top:10px">▶ つづきから</button><button class="btn ghost" id="rq" style="width:100%;margin-top:8px">🏠 町へ帰る（お金は もらえる）</button></div>`);
  $('rs').onclick=async()=>{SFX.tap();closeModal();R=G.run;
    const crit=['bg/bg_map.jpg',s.bg,cardArt(s.boss),...mapParts(R.sid)];R.map.flat().forEach(n=>{if(n&&n.foe)crit.push(cardArt(n.foe));if(n&&n.who)crit.push(cardArt(n.who))});R.deck.forEach(c=>crit.push(cardArt(c.id)));for(let i=1;i<=9;i++)crit.push(HERO.face(i));for(let i=1;i<=4;i++)crit.push(HERO.pose(i));
    await loadAssets(crit.filter(Boolean),s.ic);bgLoad(STAGE_ASSETS(R.sid));setBg(s.bg);mapView()};
  $('rq').onclick=()=>{SFX.tap();closeModal();R=G.run;endRun('retreat')}}
function town(){
  ensureRumor();closeSheet();closeModal();hideHair();setBg('bg/bg_town.jpg');music('town');checkAch();
  const ready=G.jail.filter(j=>j.until&&G.day>=j.until).length,wait=G.jail.filter(j=>!j.until).length;
  app().innerHTML=`<div class="panel row"><h1>ダストタウン</h1><span class="sp"></span><div style="text-align:right"><div class="money">＄${G.money}</div><div class="walletv"><img src="@@D13@@" alt="">🪙${G.wallet}まで</div>${G.runs>=4?`<div class="gems">💎${G.gems||0}</div>`:''}</div></div>
    <div class="fac" id="fac"></div>`;
  const fresh=FAC.filter(f=>facOpen(f)&&!G.unl[f.id]);
  FAC.filter(facOpen).forEach(f=>{const b=document.createElement('button');if(fresh.includes(f))b.classList.add('new');b.innerHTML=`<span>${f.ic}</span>${f.n}${f.id==='sheriff'&&(ready||wait)?`<i>${ready?'！':wait}</i>`:''}`;
    if(f.id==='board')b.classList.add('hot');b.onclick=()=>{SFX.tap();G.unl[f.id]=1;save();FACS[f.id]()};$('fac').appendChild(b)});
  G.unlSeen=G.unlSeen||{};const ann=FAC.filter(f=>facOpen(f)&&!G.unlSeen[f.id]&&f.id!=='board');ann.forEach(f=>G.unlSeen[f.id]=1);save();
  if(ann.length){const fresh=ann;SFX.legend();modal(`<div class="unlock"><div class="uic">${fresh.map(f=>f.ic).join('')}</div><h2>NEW!</h2>
    <p class="money">${fresh.map(f=>f.n).join('・')}</p><button class="btn big" id="ok" style="margin-top:8px">やったー！</button></div>`);$('ok').onclick=closeModal}
}
const back=()=>`<button class="btn ghost" id="back">← 🏠</button>`;
const bindBack=()=>{$('back').onclick=()=>{SFX.tap();town()}};
const head=()=>`<div class="row">${back()}<span class="sp"></span><span class="money">＄${G.money}</span></div>`;
/* 手配書の紙：4種類（4枚目は まだひみつ用）。写真のまどの位置（左・上・右・下の割合） */
const WANTED_UI=[{img:'@@D14@@',ar:'320/475',w:[.1677,.322,.8721,.7401]},{img:'data:image/png;base64,',ar:'320/481',w:[.1463,.3215,.8514,.7389]},{img:'data:image/png;base64,',ar:'320/486',w:[.1377,.3515,.8517,.7559]},{img:'data:image/png;base64,',ar:'320/488',w:[.1472,.339,.8377,.7291]}];
const bossPay=sid=>({wild:50,hill:100,canyon:150,saloon:200,mine:250,ranch:300,train:350,steam:400,bayou:450,snow:475,oasis:500,volcano:525,forest:550,mafia:650}[sid]||250); /* 10/28：手配書の お金＝ボスを たおすと ほんとうに もらえる */
const wantedPay=(sid,star)=>bossPay(sid)+(star||0)*Math.max(50,Math.round(bossPay(sid)*.5/25)*25);
const bountyOf=id=>{const c=C[id];return 6+c.c*5+(c.r==='R'?10:c.r==='L'?40:0)};
const persuadeDays=id=>{const c=C[id];return 1+Math.floor(c.c/3)+(c.r==='L'?2:c.r==='R'?1:0)};
const FACS={
  board(){
    /* 賞金首の手配書がはってある。手配書をおすと、その賞金首をつかまえに冒険へ */
    const st=G.boardStar||{};const sids=Object.keys(STAGES);
    app().innerHTML=`${head()}<div class="wboard"><div class="wtitle">しょうきん首</div><div class="wgrid" id="stl"></div></div>`;bindBack();
    sids.forEach((sid,k)=>{const s=STAGES[sid];const open=k===0||G.clear[sids[k-1]]>0;const maxStar=Math.min(10,G.clear[sid]||0);let star=Math.min(st[sid]||0,maxStar);
      const d=document.createElement('div');d.className='wpost'+(open?'':' lock')+(G.clear[sid]?' done':'');d.style.setProperty('--r',[-3,2.5,-1.5,3.5,-2.5,1.5][k%6]+'deg');d.style.marginTop=(k%2?14:0)+'px';
      const pay=()=>wantedPay(sid,star);/* 10/27 勝率から：荒野Lv2≒墓場Lv1 */const P=WANTED_UI[open?k%3:3];
      const draw=()=>{d.innerHTML=`<div class="wpp" style="aspect-ratio:${P.ar};--wl:${P.w[0]*100}%;--wt:${P.w[1]*100}%;--ww:${(P.w[2]-P.w[0])*100}%;--wh:${(P.w[3]-P.w[1])*100}%">
          <div class="wpart">${open?`<span style="background-image:url(${cardArt(s.boss)})"></span>`:'<b>？</b>'}</div>
          <div class="wpimg" style="background-image:url(${P.img})"></div>
          <div class="wpname" style="${open&&[...C[s.boss].n].length>8?'font-size:clamp(8px,2.4vw,11px)':''}">${open?C[s.boss].n:'？？？'}</div>${G.clear[sid]?'<div class="wstamp">つかまえた！</div>':''}</div>
        <div class="winfo"><div class="wpay">＄${open?pay():'???'}</div><div class="wst">${s.ic} ${open?s.n:'まだ ひみつ'}</div>
        ${open&&maxStar>0?`<div class="wstar"><button data-m ${star<=0?'disabled':''}>−</button><b>レベル ${star+1}</b><button data-p ${star>=maxStar?'disabled':''}>＋</button></div>`:open?'<div class="wlv">レベル 1</div>':''}</div>`;
        if(!open){d.onclick=()=>{SFX.bad&&SFX.bad();tipBubble(d,'🔒','まだ ひみつ',`まえの しょうきん首を つかまえると わかるよ`,'#7a5a3a')};return}
        if(maxStar>0){d.querySelector('[data-m]').onclick=e=>{e.stopPropagation();star--;G.boardStar={...G.boardStar,[sid]:star};SFX.tap();draw()};d.querySelector('[data-p]').onclick=e=>{e.stopPropagation();star++;G.boardStar={...G.boardStar,[sid]:star};SFX.tap();draw()}}
        d.onclick=()=>{SFX.flip&&SFX.flip();d.animate([{transform:'rotate(var(--r)) scale(1)'},{transform:'rotate(0) scale(1.06)'},{transform:'rotate(var(--r)) scale(1)'}],{duration:300});
          modal(`<div class="wgo"><div class="wart big"><span style="background-image:url(${cardArt(s.boss)})"></span></div><h2>${C[s.boss].n}</h2><p class="money">＄${pay()}${` ・ レベル${star+1}`}</p><p class="small">${s.ic} ${s.n}</p>
            <div class="row" style="justify-content:center;gap:10px;margin-top:10px"><button class="btn ghost" id="wno">やめる</button><button class="pop gold" id="wyes">つかまえに いく！</button></div></div>`);
          $('wno').onclick=()=>{SFX.tap();closeModal()};$('wyes').onclick=()=>{closeModal();G.boardStar={...G.boardStar,[sid]:star};startRun(sid,star)}}};
      draw();$('stl').appendChild(d)});
  },
  party(){partyView()},
  shop(){shopView()},
  saloon(){
    ensureRumor();music('saloon');const r=G.rumor;
    const ev={gold:'荒野で金鉱が見つかったらしい。「？」のマスでもうかるかも',storm:'近いうちに砂嵐が来るらしい。「？」のマスは気をつけな',party:'荒野のどこかで、流れの楽団がお祭りをしてるらしい',relic:'荒野に、だれかがお宝を落としたらしいぜ'}[r.event];
    const tips=['🛡かばうキャラがいると、敵はそいつを先に倒さないといけない','💤出したばかりのキャラは次のターンから攻撃できる。⚡はやうちは別だ',
      '賞金首は弱らせてから投げ縄。なぐりすぎると倒しちゃって、仲間にできないぞ','行商人では いらない どうぐを 売って お金に できるよ',
      'はなげ仙人には気をつけな。画面が鼻毛だらけになるぞ…','合成はLv10まで。高いレベルほど成功しにくいが、Lv10は伝説の強さだ','Lv5になったら進化できる。進化するとLv1にもどるが、もっと強くなれる'];
    app().innerHTML=`${head()}<div class="panel"><h2>🍺 酒場</h2><p class="muted">マスターがグラスをみがきながら、うわさ話を教えてくれる。</p></div>
      <div class="rumor">🗣️「荒野の<b>${r.floor}戦目あたり</b>に、賞金首<b>${C[r.elite].n}</b>が出るらしいぜ」</div>
      <div class="rumor">🗣️「雑貨屋のパックに、今だけ<b>${C[r.feature].n}</b>が入りやすいんだと」</div>
      <div class="rumor">🗣️「${ev}」</div><div class="rumor">🗣️「${pick([...tips,...TIPS.game])}」</div><div class="rumor">🗣️「${pick([...TIPS.west,...TIPS.life])}」</div>
      <p class="small" style="text-align:center">うわさは冒険から帰るたびに変わる</p>`;
    $('back').onclick=()=>{SFX.tap();town()};
  },
  sheriff(){sheriffView()},
  dex(){
    app().innerHTML=`${head().replace(`<span class="money">＄${G.money}</span>`,`<span class="small">${COLLECT.filter(id=>G.seen[id]).length} / ${COLLECT.length}</span>`)}
      <div class="panel"><h2>📖 図鑑</h2><p class="muted">一度でも手に入れたカードがのる。進化した姿や、捕まえたお尋ね者も。</p></div><div class="grid" id="dg"></div>`;
    bindBack();
    COLLECT.forEach(id=>{let el;if(G.seen[id]){el=cardEl(id,1,{hideLv:true});el.onclick=()=>sheetCard(id,1)}else{el=document.createElement('div');el.className='card back';el.innerHTML='<div class="q">？</div>'}
      el.style.setProperty('--cw','min(22vw,84px)');$('dg').appendChild(el)});
  },
  ach(){
    app().innerHTML=`${head()}<div class="panel"><h2>🏆 やりこみ</h2><p class="muted">達成すると💎ジェムがもらえる（今${G.gems||0}個）。ジェムは…何かに使えるらしい？　${Object.keys(G.ach).length}/${ACH.length}</p></div><div id="al"></div>`;
    bindBack();$('al').innerHTML=ACH.map(a=>`<div class="ach ${G.ach[a.id]?'done':''}"><span class="ic">${G.ach[a.id]?'🏆':'🔒'}</span><div style="flex:1">${a.n}<small>${a.d}</small></div><span class="gems" style="font-size:13px">💎${gemOf(a)}</span></div>`).join('');
  },
  data(){title()},
};

/* ---- 保安官事務所（留置所） ---- */
function sheriffView(){
  const list=G.jail;
  app().innerHTML=`${head()}<div class="panel"><h2>⭐ 保安官事務所</h2><p class="muted">捕まえたお尋ね者は、<b>突き出して賞金</b>にするか、<b>説得して仲間</b>にするか。<br>説得には日にちがかかる（冒険から帰るたびに1日たつ）。大物ほど長い。</p></div>
    <div class="grid" id="cg"></div>${list.length?'':'<p class="muted" style="text-align:center">留置所はからっぽ。冒険で「賞金首」を弱らせて、投げ縄で捕まえよう</p>'}`;
  bindBack();
  list.forEach((j,i)=>{const id=j.id,left=j.until?j.until-G.day:null;
    const badge=!j.until?'どうする？':left<=0?'説得完了！':`説得中 あと${left}日`;
    const el=cardEl(id,j.lv||1,{badge});el.onclick=()=>{
      const done=j.until&&left<=0;
      sheetCard(id,j.lv||1,`<p>突き出すと＄${bountyOf(id)}。説得すると${persuadeDays(id)}日で仲間になる。${j.until&&!done?`<br>今は説得中（あと${left}日）。`:''}</p>`,
        `${done?'<button class="btn green" id="join">仲間にする！</button>':''}${!j.until?`<button class="btn blue" id="per">説得する（${persuadeDays(id)}日）</button>`:''}<button class="btn" id="sell">突き出す（＄${bountyOf(id)}）</button>`);
      const s=$('sell');s.onclick=()=>{G.money+=bountyOf(id);G.jail.splice(i,1);save();SFX.coin();burst(s,['💰','🪙'],12);setTimeout(()=>{closeSheet();sheriffView()},350)};
      const p=$('per');if(p)p.onclick=()=>{j.until=G.day+persuadeDays(id);save();SFX.tap();closeSheet();sheriffView()};
      const jn=$('join');if(jn)jn.onclick=async()=>{G.jail.splice(i,1);addCard(id,j.lv||1);save();closeSheet();SFX.legend();await showText('🤝 仲間になった！',`${C[id].n}「${C[id].s}」`,1800);sheriffView()};
    };$('cg').appendChild(el)});
}
function addCard(id,lv=1){G.seen[id]=1;if(G.col[id]){G.col[id].n++;return false}G.col[id]={lv,n:0};if(G.party.length<deckMax())G.party.push(id);return true}

/* ---- 仲間・デッキ（合成と進化） ---- */
function partyView(){
  const ids=Object.keys(G.col).sort((a,b)=>C[a].c-C[b].c);
  const mine=ids.filter(id=>G.party.includes(id)),rest=ids.filter(id=>!G.party.includes(id));
  app().innerHTML=`${head()}
    <div class="dhead go"><span>🎒 つれていく</span><b>${G.party.length}<small>/8</small></b></div><div class="grid pgrid" id="pg1"></div>
    <div class="dhead stay"><span>🏠 おるすばん</span><b>${rest.length}</b></div><div class="grid pgrid" id="pg2"></div>`;
  bindBack();setTimeout(()=>{const g1=$('pg1');if(!g1)return;for(let i=G.party.length;i<8;i++)g1.insertAdjacentHTML('beforeend','<div class="pcell empty"><div class="aki">あき</div></div>')},0);
  const put=(id,box)=>{const e=G.col[id],inP=G.party.includes(id);const canEvo=e.lv>=EVO_LV&&C[id].evo,canMerge=e.n>0&&e.lv<MAX_LV;
    const w=document.createElement('div');w.className='pcell';w.dataset.id=id;const el=cardEl(id,e.lv,{cls:inP?'':'dim'});el.onclick=()=>colSheet(id);w.appendChild(el);
    if(canEvo)w.insertAdjacentHTML('beforeend','<i class="ptag evo">✨しんか！</i>');else if(canMerge)w.insertAdjacentHTML('beforeend',`<i class="ptag mg">🔨×${e.n}</i>`);
    const t=document.createElement('button');t.className='pop sm '+(inP?'gray':'green');t.innerHTML=inP?'⬇ おるすばん':'⬆ つれていく';
    t.onclick=()=>{SFX.swish();if(inP){if(G.party.length<=1)return;G.party=G.party.filter(x=>x!==id)}else{if(G.party.length>=8){toast('🎒 8まいまで！');return}G.party.push(id)}SFX.tap();save();
      w.animate([{transform:'none',opacity:1},{transform:`translateY(${inP?60:-60}px) scale(.8)`,opacity:0}],{duration:220,easing:'ease-in'}).onfinish=()=>{partyView();const n=[...document.querySelectorAll('.pcell')].find(c=>c.dataset.id===id);if(n)n.animate([{transform:`translateY(${inP?-40:40}px) scale(.8)`,opacity:0},{transform:'none',opacity:1}],{duration:300,easing:'cubic-bezier(.2,1.5,.4,1)'})}};
    w.appendChild(t);$(box).appendChild(w)};
  mine.forEach(id=>put(id,'pg1'));rest.forEach(id=>put(id,'pg2'));
}
function colSheet(id){
  const e=G.col[id],c=C[id],inP=G.party.includes(id);
  const canMerge=e.lv<MAX_LV&&e.n>0;const canEvo=e.lv>=EVO_LV&&c.evo;
  const rate=Math.round((MERGE_RATE[e.lv]||0)*100);
  let body='';
  if(e.lv<MAX_LV)body+=`<div class="upline"><b>Lv${e.lv}</b> → <b class="up">Lv${e.lv+1}</b><span>⚔️${statA(id,e.lv)}→<b class="up">${statA(id,e.lv+1)}</b></span><span>❤️${statH(id,e.lv)}→<b class="up">${statH(id,e.lv+1)}</b></span></div>`;
  else body+='<div class="upline"><b class="up">Lv MAX!</b></div>';
  if(c.evo)body+=`<div class="upline small">✨ Lv${EVO_LV} → ${C[c.evo].n}</div>`;
  sheetCard(id,e.lv,body,`<div class="popcol">
    ${canEvo?`<button class="pop rainbow" id="ev">✨ しんか！</button>`:''}
    ${e.lv<MAX_LV?`<button class="pop pink" id="mg" ${canMerge?'':'disabled'}>🔨 合成 <small>せいこう ${rate}%</small><i class="cnt">×${e.n}</i></button>`:''}
    <button class="pop ${inP?'gray':'green'}" id="tp">${inP?'⬇ おるすばんへ':'⬆ つれていく'}</button></div>`);
  const m=$('mg');if(m)m.onclick=()=>mergeAnim(id);
  const v=$('ev');if(v)v.onclick=()=>evolveAnim(id);
  $('tp').onclick=()=>{if(inP){if(G.party.length<=1)return;G.party=G.party.filter(x=>x!==id)}else{if(G.party.length>=8){toast('🎒 8まいまで！');return}G.party.push(id)}SFX.tap();save();closeSheet();partyView()};
}
function mbub(el,t){if(!el||!t)return;const b=document.createElement('div');b.className='mbub';b.textContent=t;el.appendChild(b);speak(t,el.dataset.cid||'wippy');setTimeout(()=>b.remove(),2200)}
async function mergeAnim(id){
  closeSheet();const e=G.col[id],ok=Math.random()<MERGE_RATE[e.lv];e.n--;
  const st=$('stage');st.hidden=false;
  st.innerHTML=`<div style="text-align:center;position:relative"><div class="title">🔨 合成！ せいこう ${Math.round(MERGE_RATE[e.lv]*100)}%</div><div class="row" style="justify-content:center;gap:6px" id="mr"></div><div class="result" id="mres"></div><div class="sub" id="msub"></div></div>`;
  const a=cardEl(id,e.lv,{showTx:false}),b=cardEl(id,1,{showTx:false,hideLv:true});a.style.setProperty('--cw','120px');b.style.setProperty('--cw','80px');
  $('mr').append(a,Object.assign(document.createElement('span'),{textContent:'＋',style:'font-size:30px;font-family:var(--display)'}),b);
  mbub(a,lineOf(id,1));
  for(let i=0;i<8;i++){SFX.tap();a.classList.toggle('glowR');await sleep(200+i*14)}
  b.style.transition='transform .3s,opacity .3s';b.style.transform='translateX(-80px) scale(.5)';b.style.opacity='0';await sleep(300);
  if(ok){e.lv++;G.st.merges++;SFX.win();flash();const n=cardEl(id,e.lv,{showTx:false,cls:'glowL flip'});n.style.setProperty('--cw','120px');a.replaceWith(n);burst(n,['✨','⭐','💫'],16,120);
    mbub(n,lineOf(id,2));$('mres').textContent=e.lv>=MAX_LV?'レベルMAX！伝説の強さだ！':`成功！Lv${e.lv}になった！`;$('msub').textContent=`攻撃${statA(id,e.lv)} 体力${statH(id,e.lv)}`;if(e.lv>=MAX_LV)SFX.legend()}
  else{SFX.bad();a.classList.add('wob');mbub(a,lineOf(id,3));$('mres').textContent='失敗…';$('msub').textContent='使った1枚は消えてしまった。レベルはそのまま'}
  save();checkAch();await sleep(2300);st.hidden=true;partyView();
}
async function evolveAnim(id){
  closeSheet();const to=C[id].evo,e=G.col[id];
  const st=$('stage');st.hidden=false;st.innerHTML=`<div class="rays"></div><div style="text-align:center;position:relative"><div class="title">おや…？ ${C[id].n}のようすが…！</div><div id="er" style="display:flex;justify-content:center"></div><div class="result" id="eres"></div></div>`;
  let el=cardEl(id,e.lv,{showTx:false});el.style.setProperty('--cw','150px');$('er').appendChild(el);
  mbub(el,lineOf(id,1));
  for(let i=0;i<12;i++){el.style.filter=i%2?'brightness(3)':'none';SFX.tap();await sleep(150-i*8)}
  SFX.legend();flash();const n=cardEl(to,1,{showTx:false,cls:'glowL flip'});n.style.setProperty('--cw','150px');el.replaceWith(n);burst(n,['✨','⭐','🌟'],22,140);
  $('eres').textContent=`${C[to].n}に進化した！`;mbub(n,C[to].s||lineOf(to,2));
  const left=e.n;G.seen[to]=1;if(G.col[to])G.col[to].n++;else G.col[to]={lv:1,n:0};
  if(left>0)G.col[id]={lv:1,n:left-1};else delete G.col[id];
  const pi=G.party.indexOf(id);if(pi>=0){if(G.col[id]){if(G.party.length<deckMax())G.party.push(to)}else G.party=G.party.map(x=>x===id?to:x)}fixParty();
  G.st.evos++;save();checkAch();await sleep(2300);st.hidden=true;partyView();
}

/* ---- 雑貨屋（パック・道具） ---- */
const PACKS={
  normal:{n:'西部劇パック',ic:'🎴',price:25,d:'なかま5人',L:.015,R:.12,minR:0},
  gold:{n:'金のパック',ic:'🌟',price:70,d:'なかま5人。レア以上が1枚は入っている、レジェンドが出やすい',L:.05,R:.25,minR:1},
};
function shopView(){
  ensureRumor();
  app().innerHTML=`${head()}<div class="panel"><h2><img class="ri" src="@@D12@@" alt=""> 雑貨屋</h2><p class="muted">「らっしゃい！西部劇パック、入荷してるよ」</p></div>
    <div class="choice">
      ${Object.entries(PACKS).map(([k,p])=>`<button data-pk="${k}" ${G.money<p.price?'disabled':''}><span class="i">${p.ic}</span><div>${p.n} ＄${p.price}<small>${p.d}。今だけ「${C[G.rumor.feature].n}」が出やすい！</small></div></button>`).join('')}
      <button id="i1"><span class="i"><img class="ri" src="@@D15@@" alt=""></span><div>予備の投げ縄 ＄8 ${G.items.rope?'（持ってる）':''}<small>次の冒険だけ、投げ縄の成功率+10%</small></div></button>
      <button id="i2"><span class="i"><img class="ri" src="@@D16@@" alt=""></span><div>救急箱 ＄8 ${G.items.kit?'（持ってる）':''}<small>次の冒険だけ、体力+8でスタート</small></div></button>
      <button id="i3"><span class="i"><img class="ri" src="@@D17@@" alt=""></span><div>古い地図 ＄5 ${G.items.map?'（持ってる）':''}<small>次の冒険だけ、「？」マスの中身が見える</small></div></button>
    </div>`;
  bindBack();
  [['i1','rope',8],['i2','kit',8],['i3','map',5]].forEach(([b,k,p])=>{$(b).disabled=G.money<p||G.items[k];$(b).onclick=()=>{G.money-=p;G.items[k]=1;SFX.coin();save();shopView()}});
  document.querySelectorAll('[data-pk]').forEach(b=>b.onclick=()=>openPack(b.dataset.pk));
}
function rollPackCard(pk,forceR){
  const P=PACKS[pk||'normal'],f=G.rumor&&G.rumor.feature;
  if(f&&C[f].c<=G.wallet&&Math.random()<(C[f].r==='L'?.02:.06))return f;
  const r=Math.random();const rar=r<P.L?'L':(r<P.L+P.R||forceR)?'R':'N';
  /* 財布で出せるコストまでの仲間だけ出る */
  const ok=id=>C[id].c<=G.wallet;let pool=PACK_POOL.filter(id=>C[id].r===rar&&ok(id));
  if(!pool.length)pool=PACK_POOL.filter(id=>C[id].r==='R'&&ok(id));if(!pool.length)pool=PACK_POOL.filter(ok);
  return pick(pool);
}
function rollPack(pk){const P=PACKS[pk];const got=Array.from({length:5},(_,i)=>rollPackCard(pk,i<P.minR));
  return got.sort((a,b)=>'NRL'.indexOf(C[a].r)-'NRL'.indexOf(C[b].r))}
async function openPack(pk){
  const P=PACKS[pk];G.money-=P.price;SFX.coin();const got=rollPack(pk);
  const fresh=got.map(id=>!G.seen[id]);
  got.forEach(id=>addCard(id));save();
  const st=$('stage');st.hidden=false;
  /* めくった瞬間に絵が空っぽにならないよう、先に全部読んでおく */
  st.innerHTML='<div class="oploading"><span>🎴</span></div>';await Promise.race([Promise.all(got.map(id=>fetchImg(cardArt(id)))),sleep(6000)]);
  st.innerHTML=`<div id="pray"></div><div style="text-align:center;width:min(94vw,520px);position:relative"><div class="title">${P.ic} ${P.n}</div><div class="grid" id="pkg"></div><div class="sub" id="pks">タップして めくろう</div>
    <div class="row" style="justify-content:center;margin-top:12px"><button class="btn ghost" id="pka">ぜんぶめくる</button><button class="btn" id="pkd" hidden>OK</button></div></div>`;
  let opened=0;
  const reveal=async(b,id,i)=>{if(b.dataset.o)return;b.dataset.o=1;opened++;
    const r=C[id].r;
    if(r!=='N'){b.classList.add('wob');SFX.drum();await sleep(r==='L'?700:380);b.classList.remove('wob')}
    if(r==='L'){flash();$('pray').innerHTML='<div class="rays"></div>'}else if(r==='R'&&!$('pray').innerHTML)$('pray').innerHTML='<div class="rays R"></div>';
    const el=cardEl(id,1,{badge:fresh[i]?'NEW!':G.col[id].n?`ダブり！×${G.col[id].n}`:'',cls:'flip'+(r==='L'?' glowL':r==='R'?' glowR':''),showTx:false});el.style.setProperty('--cw','min(27vw,104px)');b.replaceWith(el);
    el.onclick=()=>sheetCard(id,G.col[id].lv);
    if(r==='L'){SFX.legend();burst(el,['✨','⭐','🌟','💛'],26,160);$('pks').textContent=`レジェンド！${C[id].n}！`}else if(r==='R'){SFX.sparkle();burst(el,['✨','💎'],12,90)}else SFX.tap();
    if(opened===5){$('pkd').hidden=false;$('pka').hidden=true}};
  got.forEach((id,i)=>{const b=document.createElement('div');b.className='card back';b.style.setProperty('--cw','min(27vw,104px)');b.innerHTML='<div class="q">★</div>';
    if(C[id].r==='L')b.classList.add('glowL');else if(C[id].r==='R')b.classList.add('glowR');
    b.onclick=()=>reveal(b,id,i);$('pkg').appendChild(b)});
  $('pka').onclick=async()=>{const bs=[...document.querySelectorAll('#pkg .card.back')];for(const b of bs){b.click();await sleep(260)}};
  $('pkd').onclick=()=>{st.hidden=true;checkAch();shopView()};
}

/* ---- はじめて ---- */
/* オープニング。画像は先に全部読みこんでから始める（とちゅうで真っ暗にならない）。
   1枚ごとに演出を変える：pan=横スライド / shake=ゆれ+いなずま / slide=右から登場 / rays=光 / punch=ドン+紙ふぶき / rise=朝日 */
const OPENING=[
  {bg:'art/op/op1.jpg',fx:'pan',p:'dust',t:'ここは ワイルド・ウェスト。'},
  {bg:'art/op/op2.jpg',fx:'shake',p:'ember',t:'こうやには わるい 親分たちが いっぱい。'},
  {bg:'art/op/op3.jpg',fx:'slide',p:'sparkle',t:'わたしは ウィピィ。<br>しんまいの 賞金かせぎ！'},
  {bg:'art/op/op4.jpg',fx:'rays',p:'stars',t:'ゆめは… こうやの でんせつ<br>「金の星」に なること！'},
  {bg:'art/op/op5.jpg',fx:'punch',p:'confetti',t:'親分たちを ぜんぶ つかまえるんだ！'},
  {bg:'art/op/op6.jpg',fx:'rise',p:'sparkle',t:'さあ、なかまと しゅっぱつだ！'},
];
/* decode()はiPhoneで止まることがあるので使わない。onloadだけ＋1枚ごとに時間切れ */

async function intro(){
  const st=$('stage');st.hidden=false;st.onclick=null;
  st.innerHTML='<div class="oploading"><span>🌵</span><b id="opp" style="display:block;margin-top:8px;font-family:var(--display);color:#fff2b0">0%</b></div>';
  /* 絵が最後まで読めてから出す（とちゅうのボヤボヤした絵を見せない）。最初の2枚を待って、のこりは見ながら読む */
  const bgs=OPENING.map(o=>o.bg);let got=0;const upd=()=>{const e=$('opp');if(e)e.textContent=Math.round(got/2*100)+'%'};
  bgs.forEach(u=>fetchImg(u));await Promise.race([Promise.all(bgs.slice(0,2).map(u=>fetchImg(u).then(()=>{got++;upd()}))),sleep(25000)]);
  st.innerHTML=`<div class="opwrap" id="opw"><canvas id="opc"></canvas><div class="opcap" id="opcap"></div><button class="btn ghost opskip" id="skip">スキップ ▶▶</button><div class="ttap">▼</div></div>`;
  const w=$('opw'),cv=$('opc'),cap=$('opcap');let k=0,timer,stop=false,pt=null;
  const fin=()=>{if(stop)return;stop=true;clearTimeout(timer);pt&&pt.stop();st.hidden=true;st.onclick=null;music('town');G.intro=1;save();town()};
  const show=async()=>{clearTimeout(timer);if(k>=OPENING.length)return fin();const o=OPENING[k];
    if(!LOADED.has(o.bg)){await Promise.race([fetchImg(o.bg),sleep(15000)]);if(stop)return}
    const l=document.createElement('div');l.className='opl fx-'+o.fx;l.innerHTML=`<div class="opbox" style="--img:url(${o.bg})"><div class="c"></div></div>`;w.insertBefore(l,cv);const im2=l.querySelector('.opbox');
    const old=[...w.querySelectorAll('.opl')].slice(0,-1);setTimeout(()=>old.forEach(x=>x.remove()),900);
    if(o.fx==='shake'){setTimeout(()=>{w.classList.remove('opshake');void w.offsetWidth;w.classList.add('opshake');const f=document.createElement('div');f.className='opflash';w.appendChild(f);setTimeout(()=>f.remove(),700)},500)}
    if(o.fx==='punch'){setTimeout(()=>{w.classList.remove('opshake');void w.offsetWidth;w.classList.add('opshake')},250)}
    if(o.fx==='rays'){/* 星の位置を、画面に表示された絵の座標に合わせる（cover・位置50% 40%） */
      const Wd=w.clientWidth,Hd=w.clientHeight,sc=Math.max(Wd/2,Hd/3),dw=2*sc,dh=3*sc,ox=(Wd-dw)*.5,oy=(Hd-dh)*.4,P=(fx,fy)=>[ox+fx*dw,oy+fy*dh];
      const [cx,cy]=P(.633,.2305),[sx,sy]=P(.3154,.0456);
      im2.insertAdjacentHTML('beforeend',`<div class="oprays" style="left:${cx}px;top:${cy}px;width:${dw*2.6}px"></div><div class="opglow" style="left:${cx}px;top:${cy}px;width:${dw*.75}px"></div><div class="opglow2" style="left:${cx}px;top:${cy}px;width:${dw*.3}px"></div>`)}
    if(o.fx==='rise'){im2.insertAdjacentHTML('beforeend','<div class="opsun"></div>')}
    pt&&pt.stop();pt=particles(cv,o.p);(OPSFX[o.fx]||(()=>{}))();
    /* 文字：1文字ずつ */
    cap.innerHTML='';const box=document.createElement('p');box.className='opt2';cap.appendChild(box);
    const parts=o.t.split(/(<br>)/);let n=0;parts.forEach(seg=>{if(seg==='<br>'){box.appendChild(document.createElement('br'));return}
      seg.split(' ').forEach((word,wi)=>{if(wi)box.appendChild(document.createTextNode(' '));const wd=document.createElement('span');wd.className='wd';
        [...word].forEach(ch=>{const sp=document.createElement('span');sp.textContent=ch;const dl=0.35+n*0.045;sp.style.animationDelay=dl+'s';{const ii=n;setTimeout(()=>{if(!stop)OPSFX.type(ii)},dl*1000)}wd.appendChild(sp);n++});box.appendChild(wd)})});
    k++;timer=setTimeout(show,4200)};
  $('skip').onclick=e=>{e.stopPropagation();fin()};st.onclick=()=>show();show();
}
/* 小さなパーティクル（砂ぼこり・火の粉・キラキラ・星・紙ふぶき） */
function particles(cv,kind){const W=cv.width=cv.offsetWidth*devicePixelRatio,H=cv.height=cv.offsetHeight*devicePixelRatio,x=cv.getContext('2d'),d=devicePixelRatio;let on=true;const P=[];
  const cols={confetti:['#ff6fb5','#ffcd3c','#5fd38a','#5ac8ff','#b07aff']};
  const make=()=>{const r=Math.random;switch(kind){
    case 'dust':return{x:W+10,y:H*(.4+r()*.6),vx:-(1+r()*2)*d,vy:(r()-.5)*.4*d,s:(2+r()*4)*d,a:.25+r()*.3,c:'255,230,190'};
    case 'ember':return{x:r()*W,y:H+10,vx:(r()-.5)*.6*d,vy:-(1+r()*1.5)*d,s:(1.5+r()*2.5)*d,a:.8,c:'255,140,60'};
    case 'stars':return{x:r()*W,y:r()*H*.7,vx:0,vy:0,s:(1+r()*2.5)*d,a:0,t:0,tw:1,c:'255,245,200'};
    case 'confetti':return{x:r()*W,y:-10,vx:(r()-.5)*2*d,vy:(2+r()*3)*d,s:(4+r()*4)*d,a:1,rot:r()*6,vr:(r()-.5)*.3,cc:cols.confetti[Math.floor(r()*5)]};
    default:return{x:r()*W,y:r()*H,vx:0,vy:-(.2+r()*.5)*d,s:(1.5+r()*3)*d,a:0,t:0,tw:1,c:'255,250,220'}}};
  const N={dust:40,ember:50,stars:70,confetti:90,sparkle:45}[kind]||40;
  const tick=()=>{if(!on)return;x.clearRect(0,0,W,H);if(P.length<N)for(let i=0;i<3;i++)P.push(make());
    for(let i=P.length-1;i>=0;i--){const p=P[i];p.x+=p.vx;p.y+=p.vy;
      if(p.tw){p.t+=.03;p.a=Math.max(0,Math.sin(p.t))*.9;if(p.t>Math.PI){P[i]=make();continue}}
      if(p.cc){p.rot+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.rot);x.fillStyle=p.cc;x.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);x.restore()}
      else{x.globalAlpha=p.a;const g=x.createRadialGradient(p.x,p.y,0,p.x,p.y,p.s);g.addColorStop(0,`rgba(${p.c},1)`);g.addColorStop(1,`rgba(${p.c},0)`);x.fillStyle=g;x.beginPath();x.arc(p.x,p.y,p.s,0,7);x.fill();x.globalAlpha=1}
      if(p.x<-20||p.y<-20||p.y>H+20||p.x>W+20)P[i]=make()}
    requestAnimationFrame(tick)};tick();return{stop:()=>{on=false;x.clearRect(0,0,W,H)}}}


/* =====================================================================
   冒険（ラン）
   ===================================================================== */
let R=null;

const hasRelic=k=>R&&R.relics.includes(k);
const stageFloors=(sid,star)=>STAGES[sid].floors+Math.min(3,star);
const starHp=()=>1+(R?R.star:0)*.05;
function heal(n){R.hp=Math.min(R.maxhp,R.hp+n)}
/* あみだくじ式マップ：スタートは1マス → 上に行くほど枝分かれ → 最後は全員同じボス */
function buildMap(sid,floors){
  const s=STAGES[sid],n=G.runs,maxW=floors<=6?3:floors<=10?4:5,rows=[];
  const rumor=sid==='wild'&&n>=3?G.rumor:null;
  const mooks=(s.mooks||[]).filter(id=>C[id]);
  for(let f=1;f<=floors;f++){
    if(f===floors){rows.push([{t:'boss',next:[]}]);continue}
    const w=f===1?1:Math.min(maxW,1+Math.floor((f-1)*(maxW)/(floors-2)+.5));
    const pool=['fight','fight','fight','fight','saloon'];if(n>=1)pool.push('event','shop');if(n>=2&&f>=3)pool.push('elite','elite');
    const row=[];const used=new Set();
    for(let j=0;j<w;j++){let t=f===1?'fight':f===floors-1?(n>=1&&j%2?'shop':'saloon'):pick(pool);
      if(j>0&&t===row[j-1].t&&t!=='fight'&&Math.random()<.7)t='fight';
      const nd={t,next:[]};
      if(t==='fight'){let m=pick(mooks.filter(x=>!used.has(x)))||pick(mooks);used.add(m);nd.foe=m}
      if(t==='elite')nd.who=pick(s.elites);if(t==='event')nd.ev=pickEvent();row.push(nd)}
    if(rumor&&f===rumor.floor){const k=rnd(row.length);row[k]={t:'elite',who:rumor.elite,next:[]}}
    rows.push(row);
  }
  /* つなぐ（線が交差しないように） */
  for(let i=0;i<rows.length-1;i++){const A=rows[i],Bn=rows[i+1],a=A.length,b=Bn.length;
    if(b===1)A.forEach(nd=>nd.next.push(0));else for(let k=0;k<b;k++){const j=Math.min(a-1,Math.floor(k*a/b));A[j].next.push(k)}
    if(b===a&&b>1)for(let j=0;j<a-1;j++)if(Math.random()<.35)A[j].next.push(j+1);
    A.forEach(nd=>nd.next=[...new Set(nd.next)].sort((x,y)=>x-y))}
  return rows;
}
const nextNodes=()=>{const row=R.map[R.floor];if(!row)return [];if(R.floor===0)return row.map((n,j)=>j);const prev=R.map[R.floor-1][R.pos];return prev?prev.next:row.map((n,j)=>j)};
async function startRun(sid,star){
  if(!G.party.length){modal(`<h2>仲間がいない！</h2><p class="muted">「仲間・デッキ」で連れていく仲間をえらんでね。</p><button class="btn" id="ok">OK</button>`);$('ok').onclick=closeModal;return}
  const hp=34+(G.runs<1?6:0)+(G.items.kit?8:0)+(G.hpBonus||0);
  /* レベルが上がるほど、たたかう回数がふえる（+3まで）。敵も強くなる */
  const floors=G.runs<1&&sid==='wild'?6:stageFloors(sid,star||0);
  R={sid,star:star||0,floor:0,floors,hp,maxhp:hp,money:0,deck:G.party.map(id=>({id,lv:G.col[id]?G.col[id].lv:1,plus:0})),
     skills:{lasso:G.items.rope?.1:0,atk:0,coin:0,draw:0},relics:[],caught:[],bag:[],recruits:0,map:buildMap(sid,floors),seeEvents:!!G.items.map};
  G.items={rope:0,kit:0,map:0};G.runs++;save();checkAch();
  /* まず「すぐ見るもの」だけ読む（マップの敵・手札の仲間・顔）。のこりは うしろで こっそり */
  if(HUMAN){const crit=['bg/bg_map.jpg',STAGES[sid].bg,cardArt(STAGES[sid].boss),...mapParts(sid)];R.map.flat().forEach(n=>{if(n&&n.foe)crit.push(cardArt(n.foe));if(n&&n.who)crit.push(cardArt(n.who))});
    R.deck.forEach(c=>crit.push(cardArt(c.id)));for(let i=1;i<=9;i++)crit.push(HERO.face(i));for(let i=1;i<=4;i++)crit.push(HERO.pose(i));
    await loadAssets(crit.filter(Boolean),STAGES[sid].ic);bgLoad(STAGE_ASSETS(sid))}
  setBg(STAGES[sid].bg);mapView();
}
function relicRow(){return R.relics.length?`<div class="relics">${R.relics.map(k=>`<span title="${RELICS[k].n}" data-r="${k}">${RELICS[k].ic}</span>`).join('')}</div>`:''}
function bindRelics(){document.querySelectorAll('[data-r]').forEach(s=>s.onclick=()=>{const r=RELICS[s.dataset.r];toast(`${r.ic} ${r.n}：${r.d}`)})}
const MFRAME={fight:['ui/m_f_w1.png',.245,.315,.813,.74],elite:['ui/m_f_w2.png',.258,.38,.819,.745],boss:['ui/m_f_w3.png',.256,.355,.781,.76]};
const MTRAY={fight:'t_stone',elite:'t_elite',boss:'t_boss',saloon:'t_wood',shop:'t_sand',event:'t_grass'};
const MOBJ={saloon:'o_mug',shop:'o_wagon',event:'o_map'};
const MROAD={wild:'dirt',hill:'rock',canyon:'rock',saloon:'cobble',mine:'rail',ranch:'grass',train:'rail',steam:'cobble',bayou:'plank',snow:'snow',forest:'grass',mafia:'cobble',oasis:'dirt',volcano:'lava'};
const MDECO={wild:['d_cactus','d_cactus2','d_rocks','d_tumble','d_mesa','d_bush'],hill:['d_rocks','d_fence','d_sign','o_cowskull','d_bush'],canyon:['d_mesa','d_rocks','d_cactus','d_bush'],saloon:['o_barrel','d_fence','d_sign','o_lantern'],mine:['o_cart','o_barrel','d_rocks','o_lantern'],ranch:['o_hay','d_fence','o_barrel','d_bush'],train:['o_barrel','d_sign','d_rocks','d_fence'],steam:['o_barrel','o_lantern','o_cart'],bayou:['o_lantern','d_bush','o_barrel'],snow:['d_fence','o_lantern','d_rocks','o_tent'],forest:['d_cactus2','d_cactus','d_bush'],mafia:['o_barrel','o_lantern','d_fence'],oasis:['d_cactus','o_tent','o_well','d_bush'],volcano:['d_rocks','d_mesa','o_cowskull']};
const mapParts=sid=>[...[...MAP_PARTS,...(MDECO[sid]||MDECO.wild)].map(k=>`ui/m_${k}.png`),...['s1','s2','s3','deco'].map(c=>`ui/r_${MROAD[sid]||'dirt'}_${c}.png`)];
const MAP_PARTS=['t_wood','t_stone','t_grass','t_sand','t_elite','t_boss','t_done','f_w1','f_w2','f_w3','o_mug','o_wagon','o_map'];
/* ステージごとにマップの色味を変える（専用マップができるまでの仮） */
const MAP_TINT={hill:'linear-gradient(rgba(30,20,60,.55),rgba(20,10,40,.75))',snow:'linear-gradient(rgba(225,240,255,.55),rgba(150,180,225,.6))',bayou:'linear-gradient(rgba(60,30,90,.5),rgba(20,50,40,.7))',steam:'linear-gradient(rgba(60,60,70,.5),rgba(30,30,40,.72))',forest:'linear-gradient(rgba(60,20,90,.4),rgba(30,60,40,.65))',mafia:'linear-gradient(rgba(20,20,40,.6),rgba(10,10,25,.78))',oasis:'linear-gradient(rgba(255,170,90,.25),rgba(120,60,30,.6))',volcano:'linear-gradient(rgba(120,20,10,.5),rgba(40,10,5,.75))'};
function mapView(){
  if(HUMAN&&G&&R){try{G.run=JSON.parse(JSON.stringify(R));save()}catch(e){}}
  closeSheet();closeModal();hideHair();music(['hill','bayou'].includes(R.sid)?'mapnight':'map');setBg('bg/bg_map.jpg',MAP_TINT[R.sid]);
  const s=STAGES[R.sid],RH=104,H=R.map.length*RH+40;
  app().innerHTML=`<div class="panel row" style="padding:6px 10px"><span style="font-size:22px">${s.ic}</span><span class="hpbar">❤️ ${R.hp}/${R.maxhp}</span><span class="money">＄${R.money}</span><span class="sp"></span>${relicRow()}<button class="btn ghost" id="dk">🃏${R.deck.length}</button><button class="btn ghost" id="giveup">🏠</button></div>
    <div class="amap" id="map" style="height:${H}px"><svg class="alines" viewBox="0 0 100 ${H}" preserveAspectRatio="none" id="al"></svg></div>`;
  bindRelics();
  const can=nextNodes(),pos=(i,j)=>[(j+.5)/R.map[i].length*100,H-10-(i+.5)*RH];
  /* 立体マップ：台 → 絵 → WANTEDの額 の順に重ねる。道はパーツを並べる */
  const MW=$('map').clientWidth||360,px=(i,j)=>{const [x,y]=pos(i,j);return [x/100*MW,y]};
  if(!R.deco){R.deco=[];const pool=[...(MDECO[R.sid]||MDECO.wild)];pool.push('ROAD');R.map.forEach((row,i)=>{const xs=row.map((_,j)=>pos(i,j)[0]);for(let t=0;t<2;t++){const x=4+Math.random()*92;if(xs.every(v=>Math.abs(v-x)>14)&&Math.random()<.7)R.deco.push({k:pool[Math.floor(Math.random()*pool.length)],x,y:H-10-(i+.5)*RH+(Math.random()-.5)*40,s:.8+Math.random()*.5})}})}
  const lay=document.createElement('div');lay.className='mroad';
  R.deco.forEach(d=>lay.insertAdjacentHTML('beforeend',`<img class="mdeco" src="${d.k==='ROAD'?`ui/r_${MROAD[R.sid]||'dirt'}_deco.png`:`ui/m_${d.k}.png`}" style="left:${d.x}%;top:${d.y}px;width:${Math.round(44*d.s)}px" alt="">`));
  const road=MROAD[R.sid]||'dirt';
  R.map.forEach((row,i)=>row.forEach((nd,j)=>nd.next.forEach(k=>{const [x1,y1]=px(i,j),[x2,y2]=px(i+1,k);
    const walked=R.trail&&R.trail[i]===j&&R.trail[i+1]===k,open=i===R.floor-1&&j===R.pos&&can.includes(k);
    const d=Math.hypot(x2-x1,y2-y1),ang=Math.atan2(y2-y1,x2-x1)*180/Math.PI,n=Math.max(1,Math.round(d/34)),seg=d/n;
    for(let q=0;q<n;q++){const t=(q+.5)/n;lay.insertAdjacentHTML('beforeend',`<img class="mseg ${walked?'w':open?'o':''}" src="ui/r_${road}_s${1+(q+i+j)%3}.png" style="left:${x1+(x2-x1)*t}px;top:${y1+(y2-y1)*t}px;width:${seg+3}px;transform:translate(-50%,-50%) rotate(${ang}deg);animation-delay:${(q*.08).toFixed(2)}s" alt="">`)}})));
  $('map').appendChild(lay);
  R.map.forEach((row,i)=>row.forEach((nd,j)=>{const [x,y]=pos(i,j);const b=document.createElement('button');
    const done=R.trail&&R.trail[i]===j,now=i===R.floor&&can.includes(j),past=i<R.floor&&!done;
    const foe=nd.t==='fight'?nd.foe:nd.t==='elite'?nd.who:nd.t==='boss'?s.boss:null;
    b.className=`an3 ${nd.t}${now?' now':''}${done?' done':''}${past||(!now&&!done&&i<=R.floor)?' off':''}`;
    b.style.left=x+'%';b.style.top=y+'px';b.style.zIndex=10+i;
    const tray=done?'t_done':(MTRAY[nd.t]||'t_wood');let top='';
    if(foe){const F=MFRAME[nd.t]||MFRAME.fight;top=`<div class="pic"><span class="art" style="background-image:url(${cardArt(foe)});left:${F[1]*100}%;top:${F[2]*100}%;width:${(F[3]-F[1])*100}%;height:${(F[4]-F[2])*100}%"></span><img class="frm" src="${F[0]}" alt=""></div>`}
    else top=`<img class="obj" src="ui/m_${MOBJ[nd.t]||'o_sack'}.png" alt="">`;
    b.innerHTML=`<img class="tray" src="ui/m_${tray}.png" alt="">${top}${done?`<i class="ok okimg">${(window.FXD&&FXD['fx/check'])?`<img src="${FXD['fx/check']}" alt="✓">`:'✓'}</i>`:''}`;
    if(now)b.onclick=()=>{SFX.step();R.pos=j;R.trail=R.trail||[];R.trail[i]=j;
      /* えらばなかった方は 動きを止めて 下に しずめる */
      document.querySelectorAll('.an3.now').forEach(x=>{if(x!==b){x.classList.remove('now');x.classList.add('sink');x.disabled=true}});document.querySelectorAll('.mstep.o').forEach(x=>{x.classList.remove('o');x.classList.add('dim')});
      b.classList.add('go');setTimeout(()=>enterNode(nd),HUMAN?520:0)};else b.disabled=true;
    $('map').appendChild(b)}));
  $('dk').onclick=()=>{modal(`<h2>🃏 ${R.deck.length}</h2><div class="grid" id="dg"></div><button class="btn" id="ok" style="width:100%">OK</button>`);
    R.deck.forEach(c=>{const el=cardEl(c.id,c.lv);el.style.setProperty('--cw','min(25vw,96px)');$('dg').appendChild(el)});$('ok').onclick=closeModal};
  $('giveup').onclick=()=>{modal(`<div class="unlock"><div class="uic">🏠</div><h2>町へ帰る？</h2><p class="money">＄${R.money}${R.caught.length?' ・ 🪢'+R.caught.length:''}</p><div class="row" style="margin-top:10px"><button class="btn ghost" id="no">つづける</button><span class="sp"></span><button class="btn" id="yes">帰る</button></div></div>`);$('no').onclick=closeModal;$('yes').onclick=()=>endRun('retreat')};
  setTimeout(()=>{const n=document.querySelector('.an.now');if(n)n.scrollIntoView({block:'center',behavior:'smooth'})},60);
}

async function enterNode(n){
  const row=R.map[R.floor];if(row){const j=row.indexOf(n);if(j>=0){R.pos=j;R.trail=R.trail||[];R.trail[R.floor]=j}}
  R.floor++;
  if(n.t==='fight')return battle(makeFight(R.floor,n.foe));
  if(n.t==='elite')return battle(makeElite(R.floor,n.who));
  if(n.t==='boss')return battle(makeBoss());
  if(n.t==='saloon')return saloonNode();
  if(n.t==='shop')return peddler();
  if(n.t==='event')return runEvent(n.ev);
}
function afterNode(){if(R.hp<=0)return endRun('dead');mapView()}
function saloonNode(){
  /* 酒場：休んで体力回復か、なかまを1人やとうか（3人から） */
  const h=Math.round(R.maxhp*.5*(hasRelic('milk')?2:1));
  if(!HUMAN){if(R.hp<R.maxhp*.6)heal(h);else{const c=offerCards(3).filter(c=>hirePrice(c)<=R.money).sort((a,b)=>(statA(b.id,b.lv)+statH(b.id,b.lv))-(statA(a.id,a.lv)+statH(a.id,a.lv)))[0];if(c){R.money-=hirePrice(c);R.deck.push(c)}else heal(h)}return}
  music('saloon');
  talkScene({img:artUrl(C.tenshu.img),name:C.tenshu.n,line:pick(['いらっしゃい！ 休んでく？ それとも なかま さがし？','ここには 腕っぷしの いい子が そろってるよ！','ミルクで 一休みも いいわよ〜'])},'どうしようかな〜',null,1).then(()=>{
    modal(`<div class="unlock"><h2>🍺 酒場</h2><div class="popcol" style="margin-top:6px">
      <button class="pop green" id="rest">🥛 休む <small>❤️ ${h}いやす</small></button>
      <button class="pop pink" id="hire">🤝 なかまを やとう <small>${R.floor>=R.map.length-1?"✨ つよい子が いるかも":"＄で 3人から1人"}</small></button></div></div>`);
    $('rest').onclick=()=>{heal(h);SFX.heal();closeModal();toast(`❤️ ${h} いやした（${R.hp}/${R.maxhp}）`);afterNode()};
    $('hire').onclick=()=>{const boss=R.floor>=R.map.length-1;const cards=boss?hireRare(3):offerCards(3);
      modal(`<h2>🤝 だれを やとう？</h2><p class="money" style="text-align:center;margin:2px 0">＄${R.money}</p>${boss?'<p class="small" style="text-align:center;color:#ffd76a">✨ ボスの まえだから、つよい なかまが いるよ！</p>':''}<div class="grid" id="hg"></div><div class="row" style="justify-content:center"><button class="btn ghost" id="hback">やっぱり 休む（❤️ ${h}いやす）</button></div>`);
      cards.forEach((c,i)=>{const pr=hirePrice(c),ok=R.money>=pr;const el=cardEl(c.id,c.lv,{badge:'＄'+pr,cls:ok?'':'poor'});el.style.setProperty('--cw','min(30vw,112px)');el.classList.add('reveal');el.style.animationDelay=(i*.12)+'s';setTimeout(()=>SFX.flip(),i*120);
        el.onclick=()=>{SFX.tap();sheetCard(c.id,c.lv,ok?'':'<p class="small" style="color:#ff9a8a">おかねが たりない…</p>',`<button class="pop green" id="take" ${ok?'':'disabled'}>🤝 やとう！ ＄${pr}</button>`);$('sheet').classList.add('top');
          $('take').onclick=()=>{if(R.money<pr)return;R.money-=pr;closeSheet();if(!G.col[c.id]){addCard(c.id,c.lv);save()}c._got=1;R.deck.push(c);SFX.coin&&SFX.coin();SFX.fanfare();closeModal();toast(`🤝 ${C[c.id].n} が なかまに なった！`);afterNode()}};$('hg').appendChild(el)});
      $('hback').onclick=()=>{heal(h);SFX.heal();closeModal();afterNode()}};
  });
}

/* ---- レリック ---- */
function giveRelic(k){const left=RELIC_IDS.filter(x=>!R.relics.includes(x));if(!left.length)return null;k=k||pick(left);R.relics.push(k);G.st.maxRelic=Math.max(G.st.maxRelic,R.relics.length);
  if(k==='wanted'){}if(HUMAN){SFX.sparkle();toast(`${RELICS[k].ic} レリック「${RELICS[k].n}」：${RELICS[k].d}`)}return k}
function relicChoice(title){return new Promise(res=>{
  const left=shuffle(RELIC_IDS.filter(x=>!R.relics.includes(x))).slice(0,3);if(!left.length)return res();
  if(!HUMAN){giveRelic(left[0]);return res()}
  modal(`<h2>${title}</h2><p class="muted">お宝（レリック）を1つえらぼう。この冒険のあいだ、持ってるだけで効く。</p><div class="choice">${left.map(k=>`<button data-k="${k}"><span class="i">${RELICS[k].ic}</span><div>${RELICS[k].n}<small>${RELICS[k].d}</small></div></button>`).join('')}</div>`);
  document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{giveRelic(b.dataset.k);closeModal();res()});
})}

/* ---- 冒険で手に入るカード＝町で持っているカード（パックや合成で増える・強くなる） ---- */
function ownedPool(){return Object.keys(G.col).filter(id=>C[id]&&!C[id].token)}
/* 酒場でやとうお金：強いほど高い（コスト・レア・★・レベル） */
const hirePrice=c=>{const d=C[c.id];return Math.round(3+d.c*2+({N:0,R:8,L:20}[d.r]||0)+((d.st||1)-1)*5+((c.lv||1)-1)*1.5)};
/* ボスの前の酒場：レアやレジェンドが出やすい（まだ持っていない子も） */
function hireRare(n){const own=ownedPool().filter(id=>C[id].r!=='N');const fresh=PACK_POOL.filter(id=>C[id]&&!C[id].token&&C[id].c<=G.wallet&&(C[id].r==='R'||(C[id].r==='L'&&Math.random()<.12))&&!G.col[id]);
  const ids=[...new Set(shuffle([...own,...shuffle(fresh).slice(0,4)]))].slice(0,n);const out=ids.map(id=>({id,lv:1,plus:0}));
  return out.length<n?[...out,...offerCards(n).filter(c=>!ids.includes(c.id)).slice(0,n-out.length)]:out}
function offerCards(n){const pool=shuffle(ownedPool());const out=[];
  for(const id of pool){if(out.length>=n)break;if(out.includes(id))continue;out.push(id)}
  return out.map(id=>({id,lv:G.col[id].lv,plus:0}))}
/* ---- 行商人 ---- */
function peddler(){
  const offers=offerCards(3);let relic=pick(RELIC_IDS.filter(x=>!R.relics.includes(x)));let removed=false;
  if(!HUMAN){if(R.money>=6&&Math.random()<.5&&offers[0]){R.money-=6;R.deck.push(offers[0])}if(R.money>=4&&R.hp<R.maxhp*.6){R.money-=4;heal(8)}return}
  music('shop');
  const draw_=()=>{modal(`<h2>🏪 行商人</h2><p class="muted">「旅の役に立つもの、あるよ」 旅の賞金：＄${R.money}</p><div class="grid" id="og"></div>
    <div class="choice"><button id="hl"><span class="i">🩹</span><div>手当て ＄4<small>体力を8いやす（今${R.hp}/${R.maxhp}）</small></div></button>
    <button id="rm" ${removed||R.deck.length<=4?'disabled':''}><span class="i">🗑️</span><div>なかまを1人 おわかれ ＄5<small>いらない なかまを 山札から ぬく（デッキがスッキリ）</small></div></button>
    ${relic?`<button id="rl"><span class="i">${RELICS[relic].ic}</span><div>${RELICS[relic].n} ＄${RELIC_PRICE(relic)}<small>${RELICS[relic].d}（この冒険のあいだ ずっと）</small></div></button>`:''}</div><button class="btn" id="ok" style="width:100%">先へ進む</button>`);
    offers.forEach((c,i)=>{if(!c)return;const el=cardEl(c.id,c.lv,{badge:'＄6'});el.style.setProperty('--cw','min(27vw,100px)');el.onclick=()=>{if(R.money<6)return toast('お金がたりない');R.money-=6;R.deck.push(c);offers[i]=null;SFX.coin();draw_()};$('og').appendChild(el)});
    $('hl').disabled=R.money<4||R.hp>=R.maxhp;$('hl').onclick=()=>{R.money-=4;heal(8);SFX.heal();draw_()};
    $('rm').onclick=async()=>{if(R.money<5)return toast('お金がたりない');const ok=await pickDeckCard('👋 おわかれする なかまを えらんで');if(ok!=null){R.money-=5;R.deck.splice(ok,1);removed=true;SFX.coin()}draw_()};
    const rl=$('rl');if(rl){rl.disabled=R.money<RELIC_PRICE(relic);rl.onclick=()=>{R.money-=RELIC_PRICE(relic);giveRelic(relic);relic=null;draw_()}}
    $('ok').onclick=()=>{closeModal();afterNode()}};
  draw_();
}
function pickDeckCard(title){return new Promise(res=>{modal(`<h2>${title}</h2><div class="grid" id="tg"></div><button class="btn ghost" id="cx" style="width:100%">やめる</button>`);
  R.deck.forEach((c,i)=>{const el=cardEl(c.id,c.lv,{plus:c.plus||0});el.style.setProperty('--cw','min(25vw,92px)');el.onclick=()=>{closeModal();res(i)};$('tg').appendChild(el)});
  $('cx').onclick=()=>{closeModal();res(null)}})}
/* ---- できごと ---- */
function pickEvent(){const r=G.rumor;let e=pick(EVENTS);
  if(r&&r.event==='gold'&&Math.random()<.4)e=EVENTS[0];if(r&&r.event==='storm'&&Math.random()<.4)e=EVENTS[1];if(r&&r.event==='party'&&Math.random()<.4)e=EVENTS[2];if(r&&r.event==='relic'&&Math.random()<.4)e=EVENTS[8];return e}
function runEvent(e){const got=e.f();if(!HUMAN)return;music('event');
  talkScene({img:C[e.who]?.img?artUrl(C[e.who].img):null,em:C[e.who]?.em||'❓',name:C[e.who]?.n||e.n,line:e.l},e.w,`<span class="${e.bad?'bad':'good'}">${e.r}</span>${got?`<small>${got}</small>`:''}`,e.bad?6:e.r==='👃'?4:3).then(afterNode)}

/* ---- 報酬 ---- */

function reward(title,extra){
  /* えらぶのは「デッキにくわえる1枚」だけ。この冒険だけ強くなる系はなし。最初は2枚から、なれたら3枚 */
  return new Promise(res=>{
    if(!HUMAN){autoReward();return res()}
    const cards=offerCards(G.runs<=2?2:3);
    modal(`<h2>${title}</h2>${extra||''}<p class="muted" style="margin-top:6px">なかまに する のは だれ？</p><div class="grid" id="rg"></div>
      <div class="row" style="justify-content:center"><button class="btn ghost" id="rh">いらない（❤️5いやす）</button></div>`);
    cards.forEach((c,i)=>{const el=cardEl(c.id,c.lv,{});el.style.setProperty('--cw','min(36vw,128px)');el.classList.add('reveal');el.style.animationDelay=(i*.12)+'s';setTimeout(()=>SFX.flip(),i*120);
      el.onclick=()=>{SFX.tap();sheetCard(c.id,c.lv,'',`<button class="pop green" id="take">なかまにする！</button>`);$('sheet').classList.add('top');
        $('take').onclick=()=>{closeSheet();R.deck.push(c);SFX.fanfare();closeModal();toast(`🤝 ${C[c.id].n} が なかまに なった！`);res()}};$('rg').appendChild(el)});
    $('rh').onclick=()=>{heal(5);SFX.heal();closeModal();res()};
  });
}
function autoReward(){if(R.hp<R.maxhp*.35){heal(5);return}const c=offerCards(G.runs<=2?2:3).sort((a,b)=>(statA(b.id,b.lv)+statH(b.id,b.lv))-(statA(a.id,a.lv)+statH(a.id,a.lv)))[0];if(c)R.deck.push(c)}

/* ---- 冒険の終わり ---- */
function endRun(how){
  const dead=how==='dead',cleared=how==='clear';
  const got=dead?Math.floor(R.money*.6):R.money,caught=dead?[]:[...R.caught],lost=dead?R.caught.length:0,lostMoney=dead?R.money-got:0;
  G.money+=got;caught.forEach(c=>{G.jail.push({id:c.id,lv:c.lv,until:0});G.seen[c.id]=1});G.st.caught+=caught.length;
  G.best[R.sid]=Math.max(G.best[R.sid]||0,R.floor);const first=cleared&&!(G.clear[R.sid]>0);if(cleared)G.clear[R.sid]=Math.max(G.clear[R.sid]||0,Math.min(11,R.star+1));if(cleared){G.st.clr=(G.st.clr||0)+1}
  let up=null;if(first){up={sid:R.sid,wal:G.wallet<10};if(up.wal)G.wallet++;else G.hpBonus=(G.hpBonus||0)+3}
  const drop=cleared&&!first&&Math.random()<.12;if(drop){G.freePacks=G.freePacks||{};G.freePacks[R.sid]=(G.freePacks[R.sid]||0)+1}const dropSid=R.sid;
  G.day++;G.rumor=null;delete G.run;save();
  const r0=R;R=null;B=null;
  if(!HUMAN){checkAch();return}
  hideHair();
  jingle(cleared?'clear':dead?'lose':'win');
  modal(`<div class="unlock"><div class="endpose" style="background-image:url(${HERO.pose(dead?4:cleared?3:1)})"></div><div class="ribn ${dead?'lose':'win'}">${cleared?'<img class="rays" src="data:image/png;base64," alt="">':''}<img src="${dead?'data:image/png;base64,':'data:image/png;base64,'}" alt=""><b>${cleared?'クリア！':dead?'やられた…':'おかえり'}</b></div>
    <p class="money" style="font-size:24px">${dead?`<img class="coinp" src="@@D18@@" alt="">＄${got} <small style="opacity:.7">（6わり もちかえった）</small>`:`<img class="coinp" src="@@D18@@" alt="">＄${got}`}${caught.length?` ・ 🪢${caught.length}`:''}</p>
    ${cleared&&r0.star<10?`<p class="money">🆙 レベル${r0.star+2} が あそべる！</p>`:''}<button class="btn big" id="ok" style="margin-top:12px">🏠 町へ</button></div>`);
  $('ok').onclick=()=>{closeModal();if(up)return bossUnlock(up);if(drop)return packDrop(dropSid);town()};
}
/* はじめてクリアすると、大きなコイン袋が手に入る */



/* =====================================================================
   戦い（ハースストーン式）
   - おたがいに手札・山札・コイン。コインは毎ターン1ずつ増える（最大10）
   - 出したキャラは次のターンから攻撃できる（⚡はやうちはすぐ）
   - 自分のキャラをタップ → 攻撃する相手をタップ。おたがいにダメージ
   - 親分のやる気を0にするか、子分を出しきらせたら、親分はこうさん＝勝ち。賞金首はやる気をへらして投げ縄！
   ===================================================================== */
let B=null;
const enemyLv=f=>{const s=STAGES[R.sid];return Math.max(1,Math.min(MAX_LV,Math.round(s.lvBase+(f-1)*s.lvStep+(R.star||0)*.2)))};
const MAXB=3; /* 場に出せるのは3体まで（シンプルに） */
const bmax=sd=>(sd&&sd.maxB)||MAXB;
const TUT_RUN=()=>R&&R.floors<STAGES[R.sid].floors;
/* 敵のコインも、ステージごとの上限まで（1面は3、2面は4…） */
const foeCap=()=>Math.min(10,3+Object.keys(STAGES).indexOf(R.sid)+Math.floor((R.star||0)/2));
function foeDeck(f,n,elv){const s=STAGES[R.sid],maxCost=Math.min(foeCap(),TUT_RUN()?Math.min(3,1+Math.ceil(f/2)):Math.min(8,2+Math.ceil(f/1.5)));let pool=s.pool.filter(id=>C[id].c<=maxCost);
  /* なれるまで、敵はシンプルなカードだけ使う */
  if(G.runs<=2){const simple=pool.filter(id=>{const d=C[id];return !d.bc&&!d.dr&&!d.aura&&!d.poison&&!d.fuel&&d.kw.split(' ').filter(Boolean).every(k=>['taunt','shield','revive'].includes(k))});if(simple.length>=3)pool=simple}
  return shuffle(Array.from({length:n},()=>({id:pick(pool),lv:elv,plus:Math.floor(R.star/3)})))}
function makeFight(f,foeId){
  const elv=enemyLv(f);const names=[['ならず者のボス','😠'],['牛どろぼうの頭','🐮'],['荒野の用心棒','🤠'],['ゴブリンの親分','👺'],['ハゲワシ使い','🦅']];let [nm,em]=pick(names),img;const mk=foeId&&C[foeId]?foeId:pick((STAGES[R.sid].mooks||[]).filter(id=>C[id]&&C[id].img));if(mk){nm=C[mk].n;em=C[mk].em;img=C[mk].img}const cid=mk;
  return {kind:'fight',title:`${f}戦目：${nm}`,foe:{name:nm,em,img,cid,hp:Math.round((TUT_RUN()?4+f:6+f)*starHp())},deck:foeDeck(f,(TUT_RUN()?3:R.sid==='wild'?4:5)+Math.floor(f/(R.sid==='wild'?3:2)),elv),pay:3+Math.floor(f/2)+rnd(3)};
}
function makeElite(f,who){
  const elv=enemyLv(f);const c=C[who];
  let hp=Math.round((9+f)*starHp());if(hasRelic('wanted'))hp=Math.round(hp*.85);
  const deck=foeDeck(f,5+Math.floor(f/2),elv);for(let i=0;i<2;i++)deck.splice(rnd(deck.length),0,{id:who,lv:elv,plus:0});
  return {kind:'elite',title:`賞金首：${c.n}`,foe:{name:c.n,em:c.em,img:c.img,cid:who,hp,wanted:true,catchId:who,escape:9+(hasRelic('badge')?2:0)},deck,pay:12+f};
}
function makeBoss(){
  const s=STAGES[R.sid],elv=TUT_RUN()?1:Math.min(MAX_LV,enemyLv(R.floors)),c=C[s.boss];
  let hp=Math.round((TUT_RUN()?15:s.bossHp)*starHp());if(hasRelic('wanted'))hp=Math.round(hp*.85);
  return {kind:'boss',title:`ボス：${c.n}`,foe:{name:c.n,em:c.em,img:c.img,cid:s.boss,hp,wanted:true,boss:true,catchId:s.boss,escape:20+(hasRelic('badge')?2:0)},deck:foeDeck(R.floors,TUT_RUN()?6:R.floors+4,elv),pay:30,bossSummon:!TUT_RUN()};
}

/* ---- 基本 ---- */
const opp=sd=>sd===B.me?B.foe:B.me;
const isMe=sd=>sd===B.me;
function mkMinion(sd,id,lv,plus=0){const k=new Set(C[id].kw.split(' ').filter(Boolean));
  const m={uid:Math.random(),id,lv,f:C[id].f,atk:statA(id,lv)+plus,hp:statH(id,lv)+plus,kw:k,sleep:!k.has('quick'),attacks:0,frozen:0,poison:0,fuel:C[id].fuel||0,revived:false,fresh:true};
  m.max=m.hp;m.baseAtk=m.atk;if(isMe(sd)&&hasRelic('bone')){m.hp++;m.max++}return m}
function summon(sd,id,lv,plus=0,card=null){if(sd.board.length>=bmax(sd))return null;const m=mkMinion(sd,id,lv,plus);m.card=card;if(!m.sleep)m.attacks=m.kw.has('twice')?2:1;sd.board.push(m);return m}
/* 使ったカードは戻らない。山札がなくなったら、もう引けないだけ（ダメージはなし） */
function drawCard(sd,n=1){for(let i=0;i<n;i++){if(!sd.deck.length)continue;
  const c=sd.deck.shift();if(isMe(sd))c._new=1;if(sd.hand.length<8)sd.hand.push(c);else sd.grave.push(c)}}
function auraBonus(sd,m){let v=0;for(const b of sd.board){if(b===m)continue;const d=C[b.id];if(d.aura==='atk')v+=valX(d.av,b.lv);if(d.aura==='faction'&&b.f===m.f)v+=valX(d.av,b.lv)}return v}
function atkOf(sd,m,target){
  if(m.kw.has('noattack'))return m.atk;
  let v=m.atk+auraBonus(sd,m);
  if(isMe(sd))v+=R.skills.atk+(hasRelic('hat')?1:0);
  if(m.kw.has('pack')&&sd.board.some(b=>b!==m&&b.f==='an'))v+=2+lvB(m.lv);
  if(m.kw.has('lone')&&sd.board.length===1)v+=2+lvB(m.lv);
  const d=C[m.id];if(d.bounty&&target&&target.hero&&target.wanted)v+=valX(d.bounty,m.lv);
  if(sd.hanage>0&&m._hng)v-=sd.hanageV;if(sd.unko>0)v-=sd.unkoV;
  return Math.max(0,v)}
const canAttack=m=>!m.sleep&&m.attacks>0&&!m.frozen&&!m.kw.has('noattack')&&m.hp>0;
function heroOf(sd){return isMe(sd)?{hero:true,me:true}:{hero:true,me:false,wanted:B.foe.wanted}}
function validTargets(sd){const o=opp(sd);const vis=o.board.filter(x=>x.hp>0&&!x.kw.has('stealth'));const t=vis.filter(x=>x.kw.has('taunt'));
  if(t.length)return t;if(vis.length)return vis; /* 相手のキャラが残っているあいだは、顔には攻撃できない */
  return (o===B.foe&&B.foe.hidden)?[]:[heroOf(o)]}
function lassoChance(){const f=B.foe;let p=.15+(1-f.hp/f.max)*.85+R.skills.lasso+B.lassoBonus+(hasRelic('goldrope')?.15:0)+Math.max(0,...B.me.board.filter(a=>C[a.id].aura==='lasso').map(a=>.15+.05*lvB(a.lv)));if(f.boss)p-=.1;return Math.max(.05,Math.min(.95,p))}
const LASSO_MAX=3;/* 10/26：投げ縄は 1回の 戦いで 3回まで */
const lassoLeft=()=>B?Math.max(0,LASSO_MAX-(B.lassoTries||0)):0;
const canLasso=()=>B&&B.foe.wanted&&B.foe.hp>0&&B.foe.hp<=B.foe.max/2&&!B.lassoUsed&&!B.foe.hidden&&B.side===B.me&&lassoLeft()>0;

async function battle(spec){
  if(HUMAN)setBg(STAGES[R.sid].bg);
  const myDeck=shuffle(R.deck.map(c=>({...c})));
  const f=spec.foe;
  B={spec,turn:0,side:null,over:null,busy:false,sel:null,lassoUsed:false,lassoBonus:0,caughtNow:null,kills:0,scout:false,firstPlay:false,
    me:{board:[],hand:[],deck:myDeck,grave:[],coin:0,maxCoin:0,hanage:0,hanageV:0,unko:0,unkoV:0,moji:0},
    foe:{...f,max:f.hp,board:[],hand:[],deck:spec.deck,grave:[],coin:0,maxCoin:0,hanage:0,hanageV:0,unko:0,unkoV:0,moji:0,hidden:false}};
  drawCard(B.me,3+R.skills.draw+(hasRelic('boots')?1:0));drawCard(B.foe,3);
  if(HUMAN){music(spec.kind==='boss'?'boss':spec.kind==='elite'?'elite':'battle');await foeIntro(spec)}
  await startTurn(B.me);
  if(!HUMAN)return;
  renderBattle();
}
async function startTurn(sd){
  B.side=sd;if(isMe(sd)){B.turn++;
}
  /* 自分のコインは「財布」の大きさまで（大きなコイン袋で増える） */
  sd.maxCoin=Math.min(sd===B.me?Math.min(10,(G&&G.wallet)||10):foeCap(),sd.maxCoin+1);
  let c=sd.maxCoin;sd.board.forEach(m=>{const d=C[m.id];if(d.aura==='coin')c++;if(d.aura==='coinflip'&&Math.random()<.5+.25*lvN(m.lv))c++});
  if(isMe(sd)){c+=R.skills.coin;if(hasRelic('horseshoe')&&B.turn===1)c++;if(hasRelic('dice')&&Math.random()<.5)c++;B.lassoUsed=false;B.firstPlay=false}
  sd.coin=c;if(isMe(sd))B.coinIn=c;
  drawCard(sd,1+sd.board.filter(m=>C[m.id].aura==='draw').length);
  for(const m of sd.board){m.sleep=false;m.attacks=m.kw.has('twice')?2:1;if(m._lazy){m._lazy=0;m.sleep=true;m.attacks=0}if(m.frozen>0){m.frozen--;m.wasFrozen=true}else m.wasFrozen=false}
  for(const m of sd.board)if(m.poison){const p=m.poison*(isMe(sd)?1:(hasRelic('skull')?2:1));m.hp-=p;floatAt(uEl(m),'☠-'+p);impact(uEl(m),'poison')}
  if(!isMe(sd)&&hasRelic('snakeoil')){const t=pick(sd.board);if(t){t.hp-=1;floatAt(uEl(t),'🧴-1')}}
  if(!isMe(sd)&&B.foe.hidden)B.foe.hidden=false;
  await cleanup();
}
async function endTurnFx(sd){
  for(const m of sd.board){const d=C[m.id];
    if(d.aura==='regen'){const x=valX(d.av,m.lv);sd.board.forEach(b=>{if(b.hp<b.max){b.hp=Math.min(b.max,b.hp+x);floatAt(uEl(b),'+'+x,'heal')}})}
    if(d.aura==='miner'&&isMe(sd)&&Math.random()<.5+.25*lvN(m.lv)){R.money++;floatAt(uEl(m),'＄1','heal')}
    if(m.fuel){m.fuel--;if(m.fuel<=0){m.hp=0}}}
  if(isMe(sd)&&hasRelic('harmonica')&&sd.coin>0){heal(1);floatAt($('meHero'),'+1','heal')}
  sd.hanage=Math.max(0,sd.hanage-1);sd.unko=Math.max(0,sd.unko-1);sd.moji=Math.max(0,sd.moji-1);
  if(!B.me.hanage)hideHair();
  await cleanup();
}

/* ---- カードを出す ---- */
async function playCard(sd,i){
  const c=sd.hand[i],d=C[c.id];if(!c||d.c>sd.coin||sd.board.length>=bmax(sd)||B.over)return false;
  sd.coin-=d.c;sd.hand.splice(i,1);const m=summon(sd,c.id,c.lv,c.plus||0,c);
  if(isMe(sd)&&hasRelic('twin')&&!B.firstPlay){m.sleep=false;m.attacks=m.kw.has('twice')?2:1}
  if(isMe(sd))B.firstPlay=true;
  if(HUMAN&&!isMe(sd))await showPlay(c.id,c.lv);
  if(HUMAN){const ce=$('coins');const from=ce?ce.getBoundingClientRect():null;SFX.place();renderBattle();if(isMe(sd)&&ce&&d.c)coinFly($('coins'),uEl(m),d.c);summonFx(m,isMe(sd));await sleep(isMe(sd)?900:600);await kwFx(m)}
  await battlecry(sd,m,c);
  await cleanup();if(HUMAN)renderBattle();return true;
}
const trumpet=sd=>isMe(sd)&&hasRelic('trumpet')?1:0;
function strongest(list){return list.slice().sort((a,b)=>b.atk-a.atk||b.hp-a.hp)[0]}
async function battlecry(sd,m,c){
  const d=C[c.id];if(!d.bc)return;if(HUMAN)await bcFx(m);const x=valX(d.v,c.lv)+0,n=valN(d.v,c.lv);const o=opp(sd);const me=isMe(sd);
  const foesM=()=>o.board.filter(e=>e.hp>0);const mine=()=>sd.board.filter(b=>b!==m&&b.hp>0);
  const X=x+trumpet(sd);
  switch(d.bc){
    case 'draw':drawCard(sd,n);break;
    case 'coin':sd.coin+=n;SFX.coin();burst(uEl(m),['🪙'],6,60);break;
    case 'healall':if(me)heal(X);else B.foe.hp=Math.min(B.foe.max,B.foe.hp+X);sd.board.forEach(b=>{b.hp=Math.min(b.max,b.hp+X);floatAt(uEl(b),'+'+X,'heal')});SFX.heal();break;
    case 'dmg':{const t=strongest(foesM());await bcShot(m,t?uEl(t):heroEl(o));await damage(o,t||heroOf(o),X,{fx:'magic'});break}
    case 'bomb':{const all=[...foesM(),heroOf(o)];const t=pick(all);await fly(uEl(m),t.hero?heroEl(o):uEl(t),'enemy');await damage(o,t,X,{fx:'enemy'});break}
    case 'aoe':shakeApp();SFX.crit();for(const e of foesM())await damage(o,e,X,{fx:'magic',quiet:true});break;
    case 'poison':{const t=strongest(foesM());if(t){await fly(uEl(m),uEl(t),'magic');t.poison+=n;floatAt(uEl(t),'☠×'+n,'info');impact(uEl(t),'poison');SFX.poison()}break}
    case 'weaken':{const t=strongest(foesM());if(t){t.atk=Math.max(0,t.atk-x);floatAt(uEl(t),'攻撃-'+x,'info');impact(uEl(t),'magic')}break}
    case 'weakall':foesM().forEach(e=>{e.atk=Math.max(0,e.atk-x);floatAt(uEl(e),'攻撃-'+x,'info')});break;
    case 'stun':{let pl=foesM().filter(e=>!e.kw.has('nostun'));for(let i=0;i<1+lvN(c.lv);i++){const t=strongest(pl);if(!t)break;pl=pl.filter(e=>e!==t);t.frozen=1;floatAt(uEl(t),'🍺','info')}break}
    case 'stunall':foesM().forEach(e=>{if(!e.kw.has('nostun')){e.frozen=1;floatAt(uEl(e),'🍺','info')}});SFX.sparkle();break;
    case 'blow':{const t=strongest(foesM());if(t){await bounceTo(o,t);SFX.whoosh();say(`${C[t.id].n}は空のかなたへ！（手札にもどった）`)}break}
    case 'bounce':{const t=pick(foesM());if(t){await bounceTo(o,t);SFX.whoosh()}break}
    case 'sneeze':{const ts=shuffle(foesM()).slice(0,n);SFX.boing();shakeApp();for(const t of ts)await bounceTo(o,t);say(`ハ…ハ…ハックショーン！！ ${ts.length}体を吹き飛ばした！`);break}
    case 'summon':for(let i=0;i<n;i++)summon(sd,d.tok,c.lv);break;
    case 'buff':{const t=strongest(mine());if(t){t.atk+=x;t.hp+=x;t.max+=x;floatAt(uEl(t),`+${x}/+${x}`,'heal');impact(uEl(t),'heal')}break}
    case 'buffr':{const t=pick(mine());if(t){t.atk+=x;t.hp+=x;t.max+=x;floatAt(uEl(t),`+${x}/+${x}`,'heal');impact(uEl(t),'heal')}break}
    case 'buffall':sd.board.forEach(b=>{b.atk+=x;floatAt(uEl(b),'攻撃+'+x,'heal')});SFX.sparkle();break;
    case 'selfatk':m.atk+=x;break;
    case 'flipdraw':{const h=B.flip!=null?B.flip:Math.random()<.5;B.flip=null;if(h)drawCard(sd,n);if(me)say(h?'コイン投げ…表！':'コイン投げ…裏…');break}
    case 'flipbuff':{const h=B.flip!=null?B.flip:Math.random()<.5;B.flip=null;const t=pick(mine())||m;if(h){t.atk+=x;t.hp+=x;t.max+=x}if(me)say(h?'コイン投げ…表！':'コイン投げ…裏…');break}
    case 'quickmg':{const w=me&&HUMAN?await mgQuick():Math.random()<.5;const t=strongest(foesM());if(w){await damage(o,t||heroOf(o),X,{crit:true});if(me)say('早撃ち勝負に勝った！')}else if(me)say('早撃ちに負けた…');break}
    case 'meat':{const k=me&&HUMAN?await mgMeat():10+rnd(18);const b=Math.min(4,Math.floor(k/10))*x;m.atk+=b;m.hp+=b;m.max+=b;if(me)say(`お肉を${k}回！+${b}/+${b}`);break}
    case 'recall':{sd.grave.sort((p,q)=>C[q.id].c-C[p.id].c);const g=sd.grave.shift();if(g){sd.hand.push(g);if(me)say(`${C[g.id].n}が手札にもどってきた！`)}break}
    case 'raise':{for(let i=0;i<n;i++){if(!sd.grave.length)break;const g=sd.grave.splice(rnd(sd.grave.length),1)[0];if(!g)break;summon(sd,g.id,g.lv,g.plus||0,g)}SFX.sparkle();break}
    case 'drawcoin':drawCard(sd,n);sd.coin++;break;
    case 'treasure':if(me){R.money+=n;SFX.coin();burst(uEl(m),['💰','🪙'],10);say(`お宝発見！＄${n}`)}break;
    case 'lassoup':if(me){B.lassoBonus+=.3;say('投げ縄の名人がいる！この戦い、投げ縄+30%')}break;
    case 'scout':drawCard(sd,1+lvN(c.lv));if(me){B.scout=true;say('敵の手札を見やぶった！')}break;
    case 'hanage':o.hanage=2;o.hanageV=x;o.board.forEach(u=>{if(u.hp>0)u._hng=1});SFX.boing();if(o===B.me&&!hasRelic('clipper')){G.st.hanage++;showHair();say(`（敵）${d.n}「ふぉっふぉっ、伸びるぞ〜」 画面が鼻毛だらけ！（2ターン攻撃-${x}）`)}else if(o===B.me){o.hanage=0}else say(`敵が鼻毛ボーボーに！2ターン攻撃-${x}`);break;
    case 'unko':o.unko=2;o.unkoV=x;SFX.squish();if(o===B.me&&hasRelic('clipper'))o.unko=0;else say(o===B.me?'ウンチをふんだ！手札の数字が💩に…（2ターン攻撃-1）':`敵がウンチをふんだ！2ターン攻撃-${x}`);break;
    case 'moji':case 'mojis':{const lite=d.bc==='mojis';o.moji=2;o.mojiLite=lite;say(o===B.me?(lite?'手札の名前が文字化けした！':'画面の文字が ぜんぶ文字化けした！'):'敵の頭の中が文字化け！次のターン、敵は なかまを1人しか出せない');break}
    case 'junk':if(Math.random()<.5){m.hp=0;if(me)say('ガガガ…ピー…こわれた！')}break;
  }
}
async function bounceTo(sd,m){if(HUMAN&&window.CFX){const e=uEl(m);if(e)await CFX.blow(e,sd===B.me?$('hand'):document.querySelector('#foeStage .fh'))}sd.board=sd.board.filter(x=>x!==m);if(m.card&&sd.hand.length<8)sd.hand.push(m.card);if(!window.CFX)burst(uEl(m),['💨','🌪️'],8);if(HUMAN)renderBattle()}

/* ---- ダメージ ---- */
/* 親分がビビる（やる気がへる） */
function scared(){if(!HUMAN)return;const fs=$('foeStage');if(!fs)return;fs.querySelectorAll('.fbub.eek').forEach(b=>b.remove());
  const b=document.createElement('div');b.className='fbub eek';b.textContent=pick(['ひえっ！','ビクッ！','こ、こわい…','ひぃ〜！','うわわっ！']);fs.appendChild(b);setTimeout(()=>b.remove(),1100)}
async function damage(sd,t,n,{fx='',quiet,src,crit}={}){
  if(t.hero){const el=heroEl(sd);
    if(sd===B.me){if(hasRelic('tinshield'))n=Math.max(1,n-1);R.hp-=n;vignette()}else{B.foe.hp-=n;scared()}SFX.heroHit();
    impact(el,fx||(sd===B.me?'enemy':''));floatAt(el,sd===B.me?'-'+n:'💔-'+n,n>=5?'crit':'');if(!quiet)(n>=5?SFX.crit:SFX.hit)();if(n>=6)shakeApp();
    if(sd===B.foe&&B.foe.boss&&!TUT_RUN()&&STAGES[R.sid].boss==='bibiri'&&B.foe.hp>0&&B.foe.hp<=B.foe.max/2&&Math.random()<.3){B.foe.hidden=true;say('ビビリは 岩かげに かくれた！')}
    updHero();return}
  if(t.hp<=0)return;const el=uEl(t);
  if(t.kw.has('shield')){t.kw.delete('shield');floatAt(el,'バリア！','info');impact(el,'magic');SFX.guard();return}
  if(src&&src.kw.has('deadly'))n=Math.max(n,t.hp);
  t.hp-=n;impact(el,fx);floatAt(el,'-'+n,crit||n>=5?'crit':'');if(!quiet)(n>=5?SFX.crit:SFX.hit)();if(n>=6)shakeApp();
  if(src&&C[src.id].poison&&t.hp>0){const pz=C[src.id].poison+lvP(src.lv);t.poison+=pz;floatAt(el,'☠+'+pz,'info')}
  updUnit(t);
}
async function attack(sd,m,t){
  if(!canAttack(m)||B.over)return;const o=opp(sd);m.attacks--;m.kw.delete('stealth');
  const a=atkOf(sd,m,t);const el=uEl(m),tel=t.hero?heroEl(o):uEl(t);
  if(HUMAN&&el&&tel&&!isMe(sd)){el.classList.add('aiming');tel.classList.add('aimed');await sleep(900);el.classList.remove('aiming');tel.classList.remove('aimed')}
  if(HUMAN&&el&&tel)await atkFx(m,el,tel,isMe(sd));
  await damage(o,t,a,{src:m,fx:isMe(sd)?'':'enemy'});
  if(!t.hero){const back=atkOf(o,t);if(back>0&&!(t.kw.has('noattack')&&false)){await damage(sd,m,back,{src:t,fx:'enemy',quiet:true})}
    if(t.kw.has('thorns')&&m.hp>0){const tg=(typeof togeN==='function')?togeN(t):1;m.hp-=tg;floatAt(el,'トゲ -'+tg);updUnit(m)}
    if(m.kw.has('splash')){const i=o.board.indexOf(t);for(const nb of [o.board[i-1],o.board[i+1]])if(nb&&nb.hp>0)await damage(o,nb,2+lvN(m.lv),{quiet:true})}
    if(t.kw.has('noattack')&&isMe(o)){G.st.k990++;say('ゴゴゴゴ…キュウジュウキュウ号の反撃！')}}
  const killed=!t.hero&&t.hp<=0;
  if(killed&&C[m.id].onkill)drawCard(sd,1);
  await cleanup();if(HUMAN)renderBattle();
}
/* 復活：たおれる → 天から光とわっか → ふわっと立ちあがる */
async function reviveFx(m){const el=uEl(m);if(!el)return;if(window.CFX)return CFX.revive(m);const [x,y]=ctr(el);const r=el.getBoundingClientRect();
  SFX.poof&&SFX.poof();
  const a1=el.animate([{transform:'none',filter:'none'},{transform:'translateY(10px) rotate(-8deg) scale(.92)',filter:'grayscale(1) brightness(.6)'}],{duration:320,fill:'forwards',easing:'ease-in'});await a1.finished.catch(()=>{});
  const beam=document.createElement('div');beam.className='rvbeam';beam.style.cssText=`left:${x}px;top:${r.top-140}px;width:${r.width*1.1}px;height:${r.height+150}px`;document.body.appendChild(beam);
  const halo=document.createElement('div');halo.className='rvhalo';halo.style.cssText=`left:${x}px;top:${r.top-60}px;width:${r.width*.62}px`;document.body.appendChild(halo);
  SFX.reviveUp&&SFX.reviveUp();
  halo.animate([{transform:'translate(-50%,-40px) scale(.6)',opacity:0},{transform:'translate(-50%,0) scale(1)',opacity:1,offset:.4},{transform:'translate(-50%,46px) scale(.9)',opacity:1}],{duration:800,easing:'ease-out',fill:'forwards'});
  burst(el,['✨','🪶','✨'],10,60);await sleep(700);
  el.animate([{transform:'translateY(10px) rotate(-8deg) scale(.92)',filter:'grayscale(1) brightness(.6)'},{transform:'translateY(-16px) scale(1.12)',filter:'brightness(1.9)',offset:.55},{transform:'none',filter:'none'}],{duration:620,easing:'cubic-bezier(.2,.9,.3,1.3)',fill:'forwards'}).finished.then(a=>{try{a1.cancel();a.cancel()}catch(e){}}).catch(()=>{});
  floatAt(el,'👼 ふっかつ！','heal');impact(el,'heal');
  await sleep(450);beam.classList.add('out');halo.animate([{opacity:1},{opacity:0}],{duration:400,fill:'forwards'});setTimeout(()=>{beam.remove();halo.remove()},450);await sleep(250)}
async function giveUp(lines){if(!HUMAN)return;renderBattle();const fs=$('foeStage');if(fs){fs.classList.add('give');fs.insertAdjacentHTML('beforeend',`<div class="fbub">${pick(lines)}</div><img class="flag" src="@@D19@@" alt="">`)}SFX.lose();speak('まいった、こうさんだ',B.foe.cid||'foe');await sleep(2000)}
async function cleanup(){
  let died=0;
  for(const sd of [B.me,B.foe]){
    for(const m of [...sd.board]){if(m.hp>0)continue;
      if(m.kw.has('revive')&&!m.revived){m.revived=true;m.hp=Math.min(m.max||9,1+lvN(m.lv));/* ダメージを受けた状態の体力1でもどる */if(HUMAN)await reviveFx(m);continue}
      if(HUMAN){try{const e0=uEl(m);if(e0)m._lastRect=e0.getBoundingClientRect()}catch(e){}await koFx(m,uEl(m),isMe(sd))}
      sd.board=sd.board.filter(x=>x!==m);died++;
      if(!isMe(sd)){B.kills++;if(hasRelic('cowbell'))R.money++}
      const d=C[m.id];
      if(HUMAN&&d.dr&&typeof drMark==='function')try{await drMark(m)}catch(e){}
      if(HUMAN&&d.dr&&typeof DR_FX!=='undefined'){const f=DR_FX[m.id]||DR_FX[d.dr];if(f)try{await f(sd,m)}catch(e){}}
      if(d.dr){const x=valX(d.dv,m.lv),n=valN(d.dv,m.lv),o=opp(sd);
        if(d.dr==='summon')for(let i=0;i<n;i++)summon(sd,d.tok,m.lv);
        if(d.dr==='boom')for(let i=0;i<(d.boomN||3);i++){const t=pick([...o.board.filter(e=>e.hp>0),heroOf(o)]);if(t)await damage(o,t,x,{quiet:true})}
        if(d.dr==='healhero'){if(isMe(sd))heal(x);else B.foe.hp=Math.min(B.foe.max,B.foe.hp+x)}
        if(d.dr==='healall')sd.board.forEach(b=>b.hp=Math.min(b.max,b.hp+x));if(d.dr==='draw')drawCard(sd,n)}
      if(m.card){if(m.kw.has('home')&&sd.hand.length<8)sd.hand.push(m.card);else sd.grave.push(m.card)}
    }}
  if(died)for(const sd of [B.me,B.foe])sd.board.forEach(m=>{if(m.kw.has('feed'))m.atk+=died});
  if(R.hp<=0)B.over='lose';
  /* 勝ちはぜんぶ「こうさん」：親分のやる気が0になるか、子分がだれもいなくなるか */
  else if(B.foe.hp<=0){B.over='win';B.surrender=true;await giveUp(['ひえ〜！ もう むり〜！ こうさん！','こ、こわすぎる〜！ まいった！','やる気 ゼロ… こうさんです…'])}
  else if(!B.foe.deck.length&&!B.foe.hand.length&&!B.foe.board.length){B.over='win';B.surrender=true;await giveUp(['もう だれも いない… こうさん！','ま、まいった〜！ こうさんだ！','お、おぼえてろよ〜！ こうさん！'])}
  if(died&&HUMAN)renderBattle();
}

/* ---- 投げ縄 ---- */
async function tryLasso(){
  if(!canLasso())return;B.lassoUsed=true;B.lassoTries=(B.lassoTries||0)+1;const f=B.foe;
  const p=lassoChance(),ok=Math.random()<p;
  if(HUMAN)await lassoFx(ok,p);
  if(ok){B.caughtNow=f.catchId;R.caught.push({id:f.catchId,lv:Math.max(1,Math.min(5,enemyLv(R.floor)-1))});B.over='win'}
  if(B.over)return finishBattle();renderBattle();
}

/* ---- 敵（と自動プレイ）の考え ---- */
async function aiPlay(sd){
  let plays=0;const limit=sd.moji?1:9;
  for(let k=0;k<9&&plays<limit;k++){
    const opts=sd.hand.map((c,i)=>({c,i})).filter(x=>C[x.c.id].c<=sd.coin);
    if(!opts.length||sd.board.length>=bmax(sd))break;
    opts.sort((a,b)=>C[b.c.id].c-C[a.c.id].c||Math.random()-.5);
    await playCard(sd,opts[0].i);plays++;if(B.over)return;
  }
}
async function aiAttack(sd){
  for(let k=0;k<12;k++){
    const ms=sd.board.filter(canAttack);if(!ms.length||B.over)return;
    const m=ms[0];const ts=validTargets(sd);if(!ts.length){m.attacks=0;continue}
    const a=atkOf(sd,m);let best=null,score=-99;
    for(const t of ts){let s;
      if(t.hero){s=isMe(sd)?(B.foe.wanted&&B.foe.hp-a<=0&&B.foe.hp>B.foe.max/2?-5:2.2):2.5;if(!isMe(sd)&&R.hp<=a)s=50;if(isMe(sd)&&!B.foe.wanted){if(B.foe.hp<=a)s=50;else if(B.foe.hp<=8)s+=1}}
      else{const o=opp(sd);const kills=t.hp<=a||(m.kw.has('deadly')&&!t.kw.has('shield'));const dies=atkOf(o,t)>=m.hp&&!m.kw.has('shield');
        s=(kills?2+atkOf(o,t)*.6:0)+(dies?-1-a*.4:0.3)+(t.kw.has('taunt')?1:0)}
      s+=Math.random()*.6;if(s>score){score=s;best=t}}
    await attack(sd,m,best);if(HUMAN)await sleep(isMe(sd)?200:600);
  }
}
async function foeTurn(){
  await startTurn(B.foe);if(B.over)return;
  if(HUMAN){renderBattle();await turnBanner('敵のターン','foe')}
  if(B.spec.bossSummon&&B.turn%4===0&&B.foe.board.length<bmax(B.foe)){const s=STAGES[R.sid];const id=pick(s.pool.filter(x=>C[x].c<=3));const m=summon(B.foe,id,enemyLv(R.floors));if(m&&HUMAN){say(`「親分！加勢しますぜ！」${C[id].n}が出てきた`);renderBattle();await sleep(400)}}
  await aiPlay(B.foe);if(B.over)return;
  await aiAttack(B.foe);if(B.over)return;
  await endTurnFx(B.foe);
  if(B.foe.wanted&&B.foe.escape&&B.turn>=B.foe.escape&&!B.over){B.foe.escaped=true;B.over='escape';if(HUMAN)await showText('逃げられた！',`${B.foe.name}は荒野のかなたへ逃げていった…`,1400)}
}
async function endTurn(){
  if(B.busy||B.over||B.side!==B.me)return;B.busy=true;B.sel=null;
  await endTurnFx(B.me);
  if(!B.over){if(HUMAN)renderBattle();await foeTurn()}
  if(B.over){B.busy=false;return finishBattle()}
  if(HUMAN)await turnBanner('あなたのターン','me');
  await startTurn(B.me);B.busy=false;
  if(B.over)return finishBattle();
  if(HUMAN){renderBattle();
  }
}
async function finishBattle(){
  const spec=B.spec,res=B.over;hideHair();
  if(res==='lose'){if(HUMAN){jingle('lose');await showText('💀',B&&B.meGiveUp?'こうさん した…':'たおれてしまった…',1400)}return endRun('dead')}
  let pay=spec.pay+rnd(2);const caught=B.caughtNow;
  if(spec.kind!=='fight'&&res==='win'&&!caught)pay+=Math.round(spec.pay*.3);
  if(res==='escape')pay=Math.round(pay*.5);
  if(R.star)pay=Math.round(pay*(1+R.star*.15));if(spec.kind==='boss'&&res!=='escape'&&typeof wantedPay==='function')pay=wantedPay(R.sid,R.star||0);if(hasRelic('goldtooth'))pay=Math.round(pay*1.3);
  R.money+=pay;G.st.wins++;if(hasRelic('cactus'))heal(2);
  if(spec.kind==='boss'&&res!=='escape'){if(HUMAN){SFX.legend();flash();await showText('🏆 ボスをやっつけた！',(caught?`${C[caught].n}を捕まえた！`:`${spec.foe.name}をたおした！`)+`<br><b style="color:#ffd76a">しょうきん ＄${pay}</b>`,2200)}return endRun('clear')}
  if(spec.kind==='boss'){return endRun('clear')}
  const extra=`<p class="money" style="font-size:22px">＋＄${pay}${caught?' ・ 🪢'+C[caught].n:''}</p>`;
  if(HUMAN){jingle('win');await winFx(caught?'つかまえた！':'やったね！');music(R.sid==='hill'?'mapnight':'map')}
  if(spec.kind==='elite')await relicChoice('💀 賞金首の戦いが終わった！');
  await reward(caught?'🪢 つかまえた！':'🎉 やったね！',extra);
  B=null;if(HUMAN)afterNode();
}

/* ---- 演出 ---- */
function ctr(el){const r=el.getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]}
async function fly(from,to,kind='bullet',ms=230){
  if(!HUMAN||!from||!to)return;if(window.CFX)return CFX.shotTo(from,to,CFX._bc==='poison'?'poison':kind==='enemy'?'bomb':kind==='magic'?'magic':'shoot');const [x1,y1]=ctr(from),[x2,y2]=ctr(to);
  const p=document.createElement('div');p.className='proj '+kind;document.body.appendChild(p);const ang=Math.atan2(y2-y1,x2-x1)*180/Math.PI;
  try{await p.animate([{transform:`translate(${x1}px,${y1}px) rotate(${ang}deg) scale(.6)`},{transform:`translate(${x2}px,${y2}px) rotate(${ang}deg) scale(1.15)`}],{duration:Math.max(1,ms*SPEED),easing:'ease-in'}).finished}catch(e){}
  p.remove()}
function impact(el,kind=''){if(!HUMAN||!el)return;const [x,y]=ctr(el);const s=document.createElement('div');s.className='impact '+kind;s.style.left=x+'px';s.style.top=y+'px';document.body.appendChild(s);setTimeout(()=>s.remove(),460);
  el.classList.remove('flashhit');void el.offsetWidth;el.classList.add('flashhit')}
function vignette(){if(!HUMAN)return;const v=document.createElement('div');v.className='vig';document.body.appendChild(v);setTimeout(()=>v.remove(),520)}
function say(t){if(!HUMAN||!t)return;document.querySelectorAll('.saypop').forEach(x=>x.remove());const e=document.createElement('div');e.className='saypop';e.innerHTML=t;document.body.appendChild(e);setTimeout(()=>e.classList.add('out'),1700);setTimeout(()=>e.remove(),2100)}
function floatAt(el,txt,cls=''){if(!el||!HUMAN)return;const f=document.createElement('span');f.className='float '+cls;f.textContent=txt;el.appendChild(f);if(!/heal|info/.test(cls)){el.classList.remove('hit');void el.offsetWidth;el.classList.add('hit')}setTimeout(()=>f.remove(),900)}
const uEl=m=>m&&document.querySelector(`[data-u="${m.uid}"]`);
const heroEl=sd=>$(sd===B.me?'meHero':'foeHero');
const MOJI='繧縺ｦ譁蟄怜喧縺代?繝ｼ縺ｮ縺ｫ';
const mojify=s=>[...s].map(()=>MOJI[rnd(MOJI.length)]).join('');
function updUnit(m){const el=uEl(m);if(!el)return;const h=el.querySelector('.h');if(h){h.textContent=Math.max(0,m.hp);h.classList.toggle('hurt',m.hp<m.max)}}
function updHero(){const a=$('meHero'),b=$('foeHero');if(a)a.querySelector('.hp').textContent=Math.max(0,R.hp);if(b)b.querySelector('.hp').textContent=Math.max(0,B.foe.hp)}
function pillsFor(m){const p=[];
  if(m.kw.has('taunt'))p.push('<i class="pill taunt">🛡かばう</i>');
  if(m.kw.has('shield'))p.push('<i class="pill shield">💠バリア</i>');
  if(m.kw.has('revive')&&!m.revived)p.push('<i class="pill revive">👼復活</i>');
  if(m.kw.has('twice'))p.push('<i class="pill twice">✌2回</i>');
  if(m.kw.has('stealth'))p.push('<i class="pill stealth">👻かくれ</i>');
  if(m.poison)p.push(`<i class="pill poison">☠${m.poison}</i>`);
  if(m.frozen)p.push('<i class="pill stun">💫休み</i>');
  if(m.fuel)p.push(`<i class="pill fuel">⛽${m.fuel}</i>`);
  return p.length?`<div class="pills">${p.slice(0,3).join('')}</div>`:''}
const METC={N:'#c98a4a',R:'#cfd8e0',L:'#ffcd3c'};
function unitEl(sd,m,{selectable,targetable}){
  const el=document.createElement('div');el.dataset.u=m.uid;el.dataset.cid=m.id;el.dataset.clv=m.lv;const d=C[m.id];const a=atkOf(sd,m);const sel=B.sel===m;
  const sleepy=isMe(sd)&&!B.over&&(m.sleep||m.frozen)&&!m.kw.has('noattack');
  el.className='u'+(m.kw.has('taunt')?' taunt':'')+(m.kw.has('shield')?' shield':'')+(m.kw.has('stealth')?' stealth':'')+(m.fresh?' enter':'')+(selectable&&!sel?' ready':'')+(sel?' sel':'')+(targetable?' tgt':'')+(sleepy?' sleepy':'');m.fresh=false;
  el.style.setProperty('--met',METC[d.r]||METC.N);
  el.innerHTML=`${selectable&&!sel?'<span class="rdy"></span><span class="sword">⚔️</span>':''}${artHtml(m.id)}<span class="stat a ${a>m.baseAtk?'up':a<m.baseAtk?'down':''}">${sd.unko&&sd===B.me?'💩':a}</span><span class="stat h ${m.hp<m.max?'hurt':''}">${m.hp}</span>${pillsFor(m)}${isMe(sd)&&m.sleep&&!B.over?'<span class="zzz"><b>Z</b><b>Z</b><b>Z</b></span>':''}`;
  return el}
const TUTOR=()=>false; /* 教えない：自分で遊んで見つける */
function clearCoach(){document.querySelectorAll('.coach').forEach(c=>c.remove())}
function coachAt(el,txt){clearCoach();if(!el||!HUMAN)return;const r=el.getBoundingClientRect();if(!r.width)return;const up=r.top<120;
  const c=document.createElement('div');c.className='coach';c.innerHTML=up?`<span class="f">👆</span><span class="t">${txt}</span>`:`<span class="t">${txt}</span><span class="f">👇</span>`;
  document.body.appendChild(c);const h=c.offsetHeight;c.style.left=Math.max(70,Math.min(innerWidth-70,r.left+r.width/2))+'px';c.style.top=(up?r.bottom-4:r.top-h+6)+'px'}
function coachUpdate(myTurn,tg){clearCoach();if(!TUTOR()||!myTurn||!B||B.over)return;
  if(B.sel){const h=tg.some(t=>t.hero);const t=h?$('foeHero'):document.querySelector('#ef .u.tgt');return coachAt(t,h?'敵の顔をタップ！':'赤く光る敵をタップ！')}
  const rd=document.querySelector('#af .u.ready');if(rd)return coachAt(rd,'光っている仲間をタップ');
  const pc=document.querySelector('#hand .card.can');if(pc)return coachAt(pc,'この なかまを 出そう');
  coachAt($('endt'),'ターン終了をおそう')}
/* 敵のまわりの表示：タップで説明 */
const FOE_TIPS={
  run:f=>['🏃','にげちゃう！',`あと ${Math.max(0,f.escape-B.turn)}ターンで にげる。はやく たおそう！`,'#7a4a2a'],
  catch:f=>['🪢','なげなわ チャンス！','いま なげなわを なげると なかまに できるかも！','#2fbf6a'],
  fcoin:f=>['🪙','あいての コイン','これを つかって 子分を よぶよ。ターンごとに ふえる。','#b97b12'],
  fdeck:f=>['🂠','あいての のこり',`まだ よべる 子分の かず（${f.deck.length}）。子分が ぜんぶ いなくなると こうさん！`,'#b04030'],
  fhand:f=>['✋','あいての てふだ',`つぎに よぶかも しれない 子分（${f.hand.length}）。`,'#7a5a3a']};
function renderBattle(){
  if(!HUMAN||!B)return;
  const keepLine=$('line')?$('line').innerHTML:'';const me=B.me,f=B.foe,myTurn=B.side===me&&!B.busy&&!B.over;
  const tg=B.sel?validTargets(me):[];const heroT=tg.some(t=>t.hero);
  app().innerHTML=`<div class="btop"><span class="sp"></span>${relicRow()}</div>
    <div class="foestage ${heroT?'tgt':''} ${f.hidden?'hid':''}" id="foeStage">
      <div class="fport" id="foeHero">${f.img?`<div class="hart" style="background-image:url(${artUrl(f.img)})"></div>`:`<span>${f.em}</span>`}<span class="hp yk">${Math.max(0,f.hp)}</span>${f.board.length?'<span class="guard">🛡</span>':''}</div>
      ${heroT?'<span class="aim"></span>':''}
      <div class="fname">${f.wanted?`<i class="pill want">${f.boss?'ボス':'賞金首'}</i>`:''}${f.hanage?' 👃':''}${f.unko?' 💩':''}</div>
      
      <div class="fleft">${f.wanted&&f.escape?`<i class="pill run" data-tip="run">🏃 にげるまで あと${Math.max(0,f.escape-B.turn)}</i>`:''}${canLasso()?'<i class="pill catch" data-tip="catch">🪢 つかまえられる！</i>':f.wanted&&f.hp>f.max/2?`<i class="pill lhint" data-tip="catch">🪢 あと${Math.ceil(f.hp-f.max/2)}で なげなわOK</i>`:''}</div>
      <div class="fside"><div class="fsr" data-tip="fcoin"><span>${coinIco}${f.coin}</span><small>コイン</small></div><div class="fsr" data-tip="fdeck"><span class="deckpile red ${f.deck.length?'':'empty'}">${f.deck.length}</span><small>のこり</small></div><div class="fsr" data-tip="fhand"><div class="fh">${f.hand.length?(B.scout?f.hand.map(c=>`<span class="mini">${C[c.id].em||'🃏'}</span>`).join(''):f.hand.map(()=>'<span class="cb"></span>').join('')):'<span class="small">0</span>'}</div><small>てふだ</small></div></div>
    </div>
    <div class="bf ${heroT?'tgthero':''}" id="ef"></div>
    <div class="mid"></div>
    <div class="bf" id="af"></div>
    <div class="bar"><div class="hero" id="meHero"><div class="hart" style="background-image:url(${HERO.img})"></div><span class="hp">${Math.max(0,R.hp)}</span></div><span class="coins" id="coins">${coinIco}${me.coin}<small class="small">/${me.maxCoin}</small></span><span class="deckpile ${me.deck.length?'':'empty'}" id="pile">${me.deck.length}</span>
      <span class="sp"></span>${me.hanage?'<span title="鼻毛">👃</span>':''}${me.unko?'<span>💩</span>':''}${me.moji?'<span>文字化け</span>':''}
      ${canLasso()?`<button class="btn red" id="lasso" style="padding:8px 10px">🪢投げ縄 ${Math.round(lassoChance()*100)}% <small style="font-size:.78em;opacity:.9">あと${lassoLeft()}回</small></button>`:''}
      <button class="pop green" id="endt" style="font-size:15px;padding:10px 16px" ${myTurn?'':'disabled'}>ターン終了 ▶</button></div>
    <div class="hand" id="hand"></div>`;
  bindRelics();
  document.querySelectorAll('#foeStage [data-tip]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();const t=FOE_TIPS[e.dataset.tip];if(t)tipBubble(e,...t(f))});
  const hitHero=()=>{const a=B.sel;B.sel=null;B.busy=true;clearCoach();attack(me,a,heroOf(f)).then(()=>{B.busy=false;if(B.over)finishBattle();else{renderBattle();hintAfter()}})};
  f.board.forEach(m=>{const el=unitEl(f,m,{targetable:tg.includes(m)});
    el.onclick=e=>{e.stopPropagation();if(!myTurn)return sheetCard(m.id,m.lv);if(B.sel&&tg.includes(m)){const a=B.sel;B.sel=null;B.busy=true;clearCoach();attack(me,a,m).then(()=>{B.busy=false;if(B.over)finishBattle();else{renderBattle();hintAfter()}});return}
      if(B.sel){say(m.kw.has('stealth')?'👻 見えない！':'🛡 こっちが先！');return}
      sheetCard(m.id,m.lv)};$('ef').appendChild(el)});
  
  /* 敵の場のあいたところ・敵の顔、どちらをタップしても顔に攻撃 */
  const heroTap=()=>{if(!B.sel){const fh=$('foeHero');if(fh)tipBubble(fh,'❤️','おやぶんの やる気',`アタックすると ビビって へるよ。0に なるか、子分が だれも いなくなると こうさん！`,'#e8642a');return}if(!myTurn)return;if(heroT)hitHero();else{say(f.hidden?'🪨…':'子分が じゃまで とどかない！');const fh=$('foeHero');if(fh)fh.animate([{transform:'translateX(-6px)'},{transform:'translateX(6px)'},{transform:'none'}],{duration:260})}};
  $('foeStage').onclick=heroTap;$('ef').onclick=()=>{if(B.sel&&heroT)hitHero()};
  me.board.forEach(m=>{const can=myTurn&&canAttack(m);const el=unitEl(me,m,{selectable:can});
    el.onclick=()=>{if(!myTurn)return;if(B.sel===m){B.sel=null;renderBattle();return}
      if(can){B.sel=m;SFX.tap();renderBattle();return}
      if(m.sleep&&!document.querySelector('.kwbub'))return tipBubble(el,'💤','ねむってる…','よんだ ばかりの なかまは、つぎの ターンから うごけるよ！','#5a6ab0');
      sheetCard(m.id,m.lv,`<p>${m.sleep?'💤 よんだばかりなので、つぎの ターンから うごける':m.frozen||m.wasFrozen?'💫 休み中':m.kw.has('noattack')?'このキャラは攻撃できない':m.attacks<=0?'このターンはもう攻撃した':''}</p>`)};$('af').appendChild(el)});
  
  me.hand.forEach((c,i)=>{const d=C[c.id];const ok=myTurn&&d.c<=me.coin&&me.board.length<bmax(me);
    const el=cardEl(c.id,c.lv,{cls:(me.unko?'poo ':'')+(ok?'can':myTurn&&d.c>me.coin?'poor':''),plus:c.plus||0});if(me.moji)el.querySelector('.nm').textContent=mojify(d.n);
    el.insertAdjacentHTML('beforeend',coinStack(d.c,me.unko));
    el.onclick=()=>{if(B.busy)return;clearCoach();
      sheetCard(c.id,c.lv,'',`<button class="pop green" id="pl" ${ok?'':'disabled'}>よぶ！ ${coinIco}${me.unko?'💩':d.c}</button>`,c.plus||0);
      const b=$('pl');if(b){if(ok&&TUTOR())setTimeout(()=>coachAt(b,'出す！'),60);b.onclick=async()=>{clearCoach();closeSheet();B.busy=true;await playCard(me,i);B.busy=false;if(B.over)return finishBattle();renderBattle();hintAfter()}}
      const x=$('shX');if(x){const o=x.onclick;x.onclick=()=>{o&&o();renderBattle()}}};$('hand').appendChild(el)});
  $('endt').onclick=()=>{clearCoach();SFX.drum();endTurn()};
  const l=$('lasso');if(l)l.onclick=()=>{if(!B.busy)tryLasso()};
  if(B.coinIn){const n=B.coinIn;B.coinIn=0;coinFly($('meHero'),$('coins'),n)}
  /* 引いたカードが山札から飛んできて、くるっとめくれる */
  const pile=$('pile');const newC=me.hand.filter(c=>c._new);newC.forEach(c=>delete c._new);if(newC.length&&pile&&HUMAN)drawAnim(newC,pile);drawApply();
  coachUpdate(myTurn,tg);
  /* もう何もできない → ターン終了が光る */
  const acts=myTurn?nextActs(tg):null;
  if(acts&&acts.kind==='end')$('endt').classList.add('glow');
  idleArm();
}
function hintAfter(){}
/* ---- 5秒そのままだと「次にできること」がふわっと出る ---- */
function nextActs(tg){const me=B.me;
  if(B.sel)return tg.some(t=>t.hero)?{kind:'sel',t:'おやぶんを タップして ビビらせよう！',el:$('foeHero')}:{kind:'sel',t:'あかく ひかる てきを タップ！',el:document.querySelector('#ef .u.tgt')};
  const rd=document.querySelector('#af .u.ready');if(rd)return{kind:'atk',t:'ひかってる なかまで アタック！',em:'⚔️',el:rd};
  const pc=document.querySelector('#hand .card.can');if(pc)return{kind:'play',t:'コインで なかまを よぼう！',em:'✨',el:pc};
  if(canLasso())return{kind:'lasso',t:'なげなわで つかまえられるかも！',em:'🪢',el:$('lasso')};
  return{kind:'end',t:'やれること ぜんぶ やった！',em:'👍',sub:'ターン終了 ▶',el:$('endt')}}
let IDLE=null;
function idleClear(){clearTimeout(IDLE);IDLE=null;document.querySelectorAll('.idlehint').forEach(h=>{h.classList.add('out');setTimeout(()=>h.remove(),350)});document.querySelectorAll('.nudge').forEach(e=>e.classList.remove('nudge'))}
function idleArm(){idleClear();if(!HUMAN||!B||B.over)return;IDLE=setTimeout(idleShow,5000)}
function idleShow(){if(!B||B.over||B.busy||B.side!==B.me||!$('endt')||!$('sheet').hidden||!$('modal').hidden)return idleArm();
  const tg=B.sel?validTargets(B.me):[];const a=nextActs(tg);
  const h=document.createElement('div');h.className='idlehint';
  h.innerHTML=`<div class="ih">${a.em?`<span class="ie">${a.em}</span>`:''}<b>${a.t}</b>${a.sub?`<small>${a.sub}</small>`:''}</div>`;
  document.body.appendChild(h);SFX.chime&&SFX.chime();
  if(a.el)a.el.classList.add('nudge')}
document.addEventListener('pointerdown',()=>{if(IDLE!==null||document.querySelector('.idlehint'))idleArm()},true);

/* ---- 鼻毛 ---- */
function showHair(){if(!HUMAN)return;const s=$('hair');const W=innerWidth,H=innerHeight;s.setAttribute('viewBox',`0 0 ${W} ${H}`);s.setAttribute('width',W);s.setAttribute('height',H);
  const hair=()=>{const x=Math.random()*W,y=Math.random()*H,l=60+Math.random()*140,a=Math.random()*Math.PI*2;let d=`M${x} ${y}`;let cx=x,cy=y;
    for(let i=0;i<3;i++){const nx=cx+Math.cos(a+i*.8)*l/3,ny=cy+Math.sin(a+i*.8)*l/3;d+=` Q${cx+(Math.random()-.5)*40} ${cy+(Math.random()-.5)*40} ${nx} ${ny}`;cx=nx;cy=ny}
    const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',d);p.setAttribute('stroke','#1a0d05');p.setAttribute('stroke-width',2+Math.random()*2.5);p.setAttribute('fill','none');p.setAttribute('stroke-linecap','round');
    p.onclick=()=>{SFX.tap();p.remove();setTimeout(()=>{if(B&&B.me.hanage)s.appendChild(hair())},1800)};return p};
  s.innerHTML='';for(let i=0;i<34;i++)s.appendChild(hair());s.removeAttribute('hidden')}
function hideHair(){const s=$('hair');if(s){s.setAttribute('hidden','');s.innerHTML=''}}

/* ---- ミニゲーム ---- */
function mgShell(title,inner){const st=$('stage');st.hidden=false;st.innerHTML=`<div style="text-align:center;width:min(88vw,380px)"><div class="title">${title}</div>${inner}</div>`;return st}
function mgMeat(){return new Promise(async res=>{
  mgShell('お肉タップタプ！',`<div class="title" id="mt">よーい…</div><button class="meat" id="meat" aria-label="お肉">🍖</button><div class="result" id="mc">0回</div><div class="sub">3秒間、お肉をできるだけたくさんタップ！</div>`);
  let n=0,on=false;$('meat').onpointerdown=e=>{e.preventDefault();if(!on)return;n++;SFX.tap();$('mc').textContent=n+'回';burst($('meat'),['🍖','✨'],2,60)};
  await sleep(900);on=true;const t0=performance.now();
  const tick=setInterval(()=>{const left=Math.max(0,3-(performance.now()-t0)/1000);$('mt').textContent=left.toFixed(1);if(left<=0){clearInterval(tick);on=false;$('mt').textContent='しゅうりょう！';setTimeout(()=>{$('stage').hidden=true;res(n)},1000)}},50)})}
function mgQuick(){return new Promise(async res=>{
  const cpuMs=260+rnd(220);
  mgShell('早撃ち勝負！',`<div class="qd" id="qd">…まだだ…</div><div class="sub">「バン！」が出たら、すぐタップ！早すぎるとフライング</div><div class="result" id="qr"></div>`);
  let state='wait',t0=0,done=false;
  const fin=(win,msg)=>{if(done)return;done=true;$('qr').textContent=msg;(win?SFX.win:SFX.lose)();setTimeout(()=>{$('stage').hidden=true;res(win)},1200)};
  $('qd').onpointerdown=e=>{e.preventDefault();if(state==='wait'){state='x';return fin(false,'フライング！')}
    if(state==='go'){const ms=Math.round(performance.now()-t0);state='x';fin(ms<cpuMs,`あなた ${ms}ミリ秒 ／ あいて ${cpuMs}ミリ秒`)}};
  await sleep(1200+rnd(2000));if(state!=='wait')return;
  state='go';t0=performance.now();$('qd').textContent='バン！';$('qd').classList.add('go');SFX.shot();
  setTimeout(()=>{if(state==='go'){state='x';fin(false,'おそかった！')}},1500)})}

/* ---- はじまり ---- */
