/* 最初に絵をぜんぶ読みこむ（とちゅうで絵が消えたり、真っ暗になったりしないように） */
/* 読みこみ：最初はオープニングと基本の絵だけ。冒険に出るときに、そのステージの絵を読む */
const LOADED=new Set();
async function loadAssets(list,icon='🌵'){
  list=[...new Set(list)].filter(u=>u&&!LOADED.has(u));if(!list.length||!HUMAN)return;
  const st=$('stage');const was=st.hidden;st.hidden=false;
  const bootSeg=pc=>{const f=$('bootfill');if(!f)return;[...f.children].forEach((b,i)=>{const r=Math.max(0,Math.min(1,(pc-i*20)/20));b.firstChild.style.clipPath=`inset(0 ${(1-r)*100}% 0 0)`;b.classList.toggle('on',r>=1)})};
  st.innerHTML=`<div class="boot"><div class="bootic"><img src="@@D6@@" alt=""></div><div class="bootbar"><div class="bseg" id="bootfill">${"<b><i></i></b>".repeat(5)}</div></div><div id="bootpc" style="font-family:var(--display);font-size:18px;margin-top:6px">0%</div><div class="tip" id="tip"></div><div class="small" style="opacity:.6;margin-top:6px">タップで スキップ</div></div>`;
  const showTip=async()=>{const t=$('tip');if(!t)return;if(t.innerHTML.trim()){t.classList.remove('in');t.classList.add('poof');await sleep(420);if(!document.body.contains(t))return}
    const [h,b]=pickTip();t.classList.remove('poof');t.innerHTML=`<b>${h}</b><p><span class="tw"></span><i class="caret"></i></p>`;void t.offsetWidth;t.classList.add('in');SFX.pop();
    const tw=t.querySelector('.tw'),tmp=document.createElement('div');tmp.innerHTML=b;const txt=tmp.textContent;const ch=[...txt];const dt=Math.max(14,Math.min(34,520/ch.length));
    for(let i=0;i<ch.length;i++){if(!document.body.contains(tw))return;tw.textContent+=ch[i];if(i%2===0&&ch[i].trim())tone(1500+Math.random()*300,.02,{type:'square',vol:.012});await sleep(dt)}
    if(document.body.contains(tw)){tw.parentNode.innerHTML=b}};showTip();const tipT=setInterval(showTip,7000);const t0=performance.now();
  let done=0;const step=()=>{done++;const pc=Math.round(done/list.length*100);bootSeg(pc);const t=$('bootpc');if(t)t.textContent=pc+'%'};
  const one=src=>fetchImg(src).then(()=>step());
  
  let skip;const sk=new Promise(r=>skip=r);st.onclick=()=>skip();
  await Promise.race([Promise.all(list.map(one)),new Promise(r=>setTimeout(r,window.__booted?20000:7000)),sk]);window.__booted=1;st.onclick=null;bootSeg(100);
  const left=(window.LOAD_MIN??1200)-(performance.now()-t0);if(left>0)await Promise.race([new Promise(r=>setTimeout(r,left)),sk]);clearInterval(tipT);
  st.hidden=was;if(was)st.innerHTML='';
}
const BASE_ASSETS=()=>{const u=['@@D1@@','@@D0@@','@@D4@@','@@D5@@','@@D2@@','@@D3@@','@@D7@@','@@D8@@','@@D9@@','@@D10@@','@@D11@@','bg/bg_town.jpg','bg/bg_sunset.jpg',HERO.img];
  if(typeof UI_FILES!=='undefined')UI_FILES.forEach(f=>{if(/^ui\/(u_|t_|bd_)/.test(f)&&!/^ui\/u_k_/.test(f))u.push(f)});u.push('bg/tumbleweed.png');WANTED_UI.forEach(w=>u.push(w.img));u.push('bg/stage_hill.jpg');return u};
const cardArt=id=>C[id]&&C[id].img?`${artUrl(C[id].img)}`:null;
const STAGE_ASSETS=sid=>{const s=STAGES[sid],u=['bg/bg_map.jpg',s.bg];for(let i=1;i<=9;i++)u.push(HERO.face(i));for(let i=1;i<=4;i++)u.push(HERO.pose(i));
  [...(s.mooks||[]),...(s.elites||[]),s.boss].forEach(id=>u.push(cardArt(id)));
  s.pool.forEach(id=>u.push(cardArt(id)));Object.keys(G.col).forEach(id=>u.push(cardArt(id)));
  ['tenshu','gantetsu','haboob','ragtime','tumble','garako','boya','snakeoil','hanage','clover','herb','funkoro'].forEach(id=>u.push(cardArt(id)));return u};
/* 最初は待たせない：タイトルをすぐ出して、うしろで基本の絵をこっそり読む */
/* 画像は「順番待ち」で少しずつ取りにいく（いっぺんに頼むと失敗しやすい）。失敗したら3回までやりなおす */
const IMGQ={q:[],low:[],n:0,p:new Map(),max:5,live:new Set()};
/* いますぐ要る絵（q）を先に。うしろで こっそり読む絵（low）は すいている時だけ */
function fetchImg(src){if(!src)return Promise.resolve(false);if(LOADED.has(src)||src.startsWith('data:'))return Promise.resolve(true);
  if(IMGQ.p.has(src)){const i=IMGQ.low.findIndex(j=>j.src===src);if(i>=0){IMGQ.q.unshift(IMGQ.low.splice(i,1)[0]);pump()}return IMGQ.p.get(src)}
  const pr=new Promise(res=>{IMGQ.q.push({src,res,tries:0});pump()});IMGQ.p.set(src,pr);return pr}
function fetchLow(src){if(!src||LOADED.has(src)||src.startsWith('data:')||IMGQ.p.has(src))return;const pr=new Promise(res=>{IMGQ.low.push({src,res,tries:0})});IMGQ.p.set(src,pr);pump()}
function pump(){while(IMGQ.n<IMGQ.max&&IMGQ.q.length){const job=IMGQ.q.shift();IMGQ.n++;tryImg(job)}
  while(IMGQ.n<2&&!IMGQ.q.length&&IMGQ.low.length){const job=IMGQ.low.shift();IMGQ.n++;tryImg(job)}}
/* 読みこみ中の画像は手元に持っておく（持っていないと iPhone が途中で捨てて、読みこみ完了の合図が来ない） */
function tryImg(job){const im=new Image();IMGQ.live.add(im);let fin=false;const end=ok=>{if(fin)return;fin=true;IMGQ.n--;IMGQ.live.delete(im);
    if(ok){LOADED.add(job.src);job.res(true)}else if(job.tries++<3){setTimeout(()=>{IMGQ.q.unshift(job);pump()},700*job.tries)}else{IMGQ.p.delete(job.src);job.res(false)}pump()};
  const t=setTimeout(()=>end(false),8000);im.onload=()=>{clearTimeout(t);end(true)};im.onerror=()=>{clearTimeout(t);end(false)};im.src=job.src+(job.tries?(job.src.includes('?')?'&':'?')+'r='+job.tries:'')}
/* 読みこみ前の絵は見せない：読めたら ふわっと出す */
function waitBg(el){const m=/url\(["']?([^"')]+)/.exec(el.style.backgroundImage||'');if(!m)return;const src=m[1];if(src.startsWith('data:')||LOADED.has(src)||el.__wb===src)return;el.__wb=src;
  (window.LATE=window.LATE||[]).push(src);el.style.opacity='0';fetchImg(src).then(()=>{el.style.backgroundImage=`url(${src})`;el.style.transition='opacity .35s';el.style.opacity=''})}
if(window.MutationObserver)new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes){if(n.nodeType!==1)continue;if(n.style&&n.style.backgroundImage)waitBg(n);n.querySelectorAll&&n.querySelectorAll('[style*="background-image"]').forEach(waitBg)}}).observe(document.documentElement,{childList:true,subtree:true});
/* うしろ読みにも 順番：いまの冒険で使う絵（bgLoad）は、図鑑ぜんぶの絵より 先に読む */
/* 絵が見つからなかったら 記録（ためしプレイで 0 か チェック） */
addEventListener('error',e=>{const t=e.target;if(t&&t.tagName==='IMG'){(window.BROKEN=window.BROKEN||[]).push(t.getAttribute('src').slice(0,80))}},true);
function bgLoad(list){const L=list.filter(Boolean);for(let k=L.length-1;k>=0;k--){const src=L[k];if(LOADED.has(src)||src.startsWith('data:'))continue;
  if(IMGQ.p.has(src)){const i=IMGQ.low.findIndex(j=>j.src===src);if(i>0)IMGQ.low.unshift(IMGQ.low.splice(i,1)[0]);continue}
  const pr=new Promise(res=>{IMGQ.low.unshift({src,res,tries:0})});IMGQ.p.set(src,pr)}pump()}

/* エラーが起きたら画面に出す（スクショで原因がわかるように） */
window.addEventListener('error',e=>{try{const d=document.createElement('div');d.style.cssText='position:fixed;left:8px;right:8px;bottom:8px;z-index:999;background:#c0392b;color:#fff;font:12px/1.4 monospace;padding:8px;border-radius:8px;white-space:pre-wrap';d.textContent='⚠ '+(e.message||e)+' @'+(e.lineno||'');document.body.appendChild(d);setTimeout(()=>d.remove(),12000)}catch(_){}});
