/* 能力の見える化：出たときに1〜2秒、何の力かを大きく見せる */
const KW_FX={taunt:'fx-taunt',shield:'fx-shield',revive:'fx-revive',twice:'fx-twice',quick:'fx-quick',stealth:'fx-stealth'};
async function kwFx(m){if(!HUMAN)return;const L=effList(m.id,m.lv).filter(x=>x[4]!=='見参'&&!/^この子が 出ると/.test(String(x[2]))&&!/^やられると/.test(String(x[2])));if(!L.length)return;
  for(const x of L.slice(0,2)){const el=uEl(m);if(!el)return;const k=Object.keys(KW_SHORT).find(k=>KW_SHORT[k]===x[4]);
    const p=document.createElement('div');p.className='kwpop '+(KW_FX[k]||'');p.style.setProperty('--k',x[3]);p.innerHTML=`<span class="i">${x[0]}</span><span class="t">${x[4]}</span>`;el.appendChild(p);
    ({shield:SFX.shieldUp,revive:SFX.reviveUp,twice:SFX.twiceUp,quick:SFX.zap,stealth:SFX.sneaky}[k]||(()=>{}))();if(k==='shield'){}else if(k==='taunt'){SFX.tauntUp();el.animate([{transform:'translateY(-14px)'},{transform:'translateY(4px)'},{transform:'none'}],{duration:380})}else SFX.sparkle&&SFX.sparkle();
    await sleep(1150);p.remove();await firstKw(m,x)}}
async function bcFx(m){const el=uEl(m);if(!el)return;if(window.CFX){await CFX.kenzan(m);if(CFX._after){const af=CFX._after;CFX._after=null;try{await af()}catch(e){}}const x0=effList(m.id,m.lv).find(x=>x[1]==='見参！');if(x0)await firstKw(m,x0);return}const p=document.createElement('div');p.className='kwpop fx-bc';p.style.setProperty('--k',KW_COL.bc);p.innerHTML=`<span class="i"><img class="kwi" src="ui/u_k_bc.png" alt=""></span>`;el.appendChild(p);
  el.animate([{transform:'scale(1)'},{transform:'scale(1.25)',filter:'brightness(1.6)'},{transform:'scale(1)'}],{duration:600});SFX.fanfare();await sleep(1000);p.remove();const x=effList(m.id,m.lv).find(x=>x[1]==='見参！');if(x)await firstKw(m,x)}
/* はじめて見たマークは、5秒くらい説明を出す（タップで閉じる） */
async function firstKw(m,x){if(!HUMAN||!G)return;G.kwSeen=G.kwSeen||{};if(G.kwSeen[x[1]])return;G.kwSeen[x[1]]=1;save();
  const el=uEl(m);if(!el)return;kwBubble(el,x);const b=document.querySelector('.kwbub');if(!b)return;b.classList.add('first');
  const t0=performance.now();while(document.body.contains(b)&&!b.classList.contains('out')&&performance.now()-t0<5000)await sleep(100);
  if(document.body.contains(b)&&!b.classList.contains('out')){b.classList.add('out');setTimeout(()=>b.remove(),200)}}

/* 10/26：カードを ひく演出。①山札から とんでくる → ②まんなかで くるっと めくれる → ③手札の 場所へ はいる（ほかのカードは そのとき よける）
   とちゅうで 画面が かきなおされても、ひいている カードは かくしたまま（drawApply） */
const DRAWP=new Set();
const handElOf=c=>{if(!B)return null;const i=B.me.hand.indexOf(c);return i<0?null:$('hand').children[i]||null};
function drawApply(){if(!DRAWP.size)return;const gap=parseFloat(getComputedStyle($('hand')).columnGap)||8;
  for(const c of DRAWP){const el=handElOf(c);if(!el){if(!B||!B.me.hand.includes(c))DRAWP.delete(c);continue}
    if(c._dp==='done')continue;el.style.visibility='hidden';el.style.transition='none';
    el.style.marginRight=c._dp==='open'?'0px':`-${el.getBoundingClientRect().width+gap}px`}}
/* 山札（右）から 手札の その場所へ とんで、そこで くるっと めくれる。山札は 1まい とぶごとに うすくなる */
function drawAnim(cards,pile){cards.forEach(c=>{c._dp='wait';DRAWP.add(c)});drawApply();drawPileN();
  cards.forEach((c,k)=>{setTimeout(async()=>{let wt=0;while(document.querySelector('#bmov,#cutin')&&wt++<200)await sleep(100);await sleep(k*260*(wt?1:0));if(!B||!handElOf(c)){DRAWP.delete(c);drawPileN();return}
    c._dp='open';let el=handElOf(c);el.style.transition='margin-right .18s ease-out';el.style.marginRight='0px';
    c._dp='fly';drawPileN();const pl=$('pile')||pile;try{pl.classList.remove('lift');void pl.offsetWidth;pl.classList.add('lift')}catch(e){}
    await sleep(190);el=handElOf(c);if(!el){DRAWP.delete(c);return}el.style.transition='none';
    const a=pl.getBoundingClientRect(),r=el.getBoundingClientRect();
    const back=document.createElement('div');back.className='card back flyc';back.style.cssText=`position:fixed;left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;--cw:${r.width}px;z-index:75;pointer-events:none;margin:0`;document.body.appendChild(back);
    const dx=a.left+a.width/2-(r.left+r.width/2),dy=a.top+a.height/2-(r.top+r.height/2),s0=Math.max(.25,a.width/r.width);SFX.draw&&SFX.draw();
    try{await back.animate([{transform:`translate(${dx}px,${dy}px) scale(${s0}) rotate(-12deg)`},{transform:`translate(${dx*.45}px,${dy*.45-34}px) scale(1.06) rotate(5deg)`,offset:.55},{transform:'none'}],{duration:420,easing:'cubic-bezier(.3,.8,.4,1)',fill:'forwards'}).finished}catch(e){}
    try{await back.animate([{transform:'rotateY(0)'},{transform:'rotateY(90deg)'}],{duration:130,fill:'forwards'}).finished}catch(e){}back.remove();
    c._dp='done';DRAWP.delete(c);el=handElOf(c);if(el){el.style.visibility='';el.style.marginRight='';el.style.transition='';
      el.animate([{transform:'rotateY(-90deg)'},{transform:'rotateY(0)'}],{duration:150,easing:'ease-out'})}},k*260)})}
/* 山札の あつみ：まだ とんでいない カードの ぶんは 山に のこして 見せる */
