  bomb:{ranged:1,proj:'💣',spin:1,arc:1,on:['ドッカーン！'],col:'#ff5a3a',sfx:()=>{SFX.whoosh&&SFX.whoosh()},hit:()=>{SFX.thunder&&SFX.thunder();shakeApp()},chips:['💥','💨']},
  wind:{ranged:1,proj:'img:x_tornado',on:['ビュオォ！'],col:'#cfe8ff',sfx:()=>{SFX.wind&&SFX.wind()},chips:['🍃','💨']},
  water:{ranged:1,proj:'img:x_sweat',on:['バシャッ！'],col:'#5ab8ff',sfx:()=>{noise(.2,{vol:.2,freq:2500})},chips:['💧','💦']},
  ice:{ranged:1,proj:'img:x_ice',spin:1,on:['カチーン！'],col:'#bff4ff',sfx:()=>{tone(2600,.15,{vol:.06})},chips:['❄️']},
