let SPSVG_N=0;
function spSvg(name,w){const v=SPSVG[name];const s=typeof v==='function'?v():v;const id='g'+(++SPSVG_N);const e=document.createElement('div');e.className='spimg spsvg';e.style.width=Math.round(w)+'px';e.innerHTML=(s||'').replace(/\$/g,id);document.body.appendChild(e);return e}
function spArt(id,w){const e=document.createElement('div');e.className='spimg spart';const u=typeof cardArt==='function'?cardArt(id):null;e.style.width=e.style.height=Math.round(w)+'px';if(u)e.style.backgroundImage=`url(${u})`;document.body.appendChild(e);return e}
function spBub(w){const e=document.createElement('div');e.className='spimg spbub';e.style.width=e.style.height=Math.round(w)+'px';document.body.appendChild(e);return e}
/* ふきだし・擬音は エフェクトの あとに（いまの位置で 少しおくれて出す） */
/* 読みやすい 擬音：1.3秒 表示 */
function onomaX(el,txt,col){if(!HUMAN||!el)return;const [x,y]=ctr(el);const o=document.createElement('div');o.className='onoma';o.textContent=txt;o.style.cssText=`left:${x+(Math.random()*20-10)}px;top:${y-24}px;--oc:${col};--rot:${(Math.random()*16-8).toFixed(0)}deg;animation-duration:1.3s`;document.body.appendChild(o);setTimeout(()=>o.remove(),1350)}
function onomaL(el,t,c,ms=330){if(!el)return;const r=el.getBoundingClientRect();const f={getBoundingClientRect:()=>r};setTimeout(()=>onomaX(f,t,c),ms)}
function noteFx(x,y,hue,size=30,rainbow){const i=document.createElement('img');i.src='ui/x_note.png';i.className='fximg fxnote';i.style.cssText=`left:${x}px;top:${y}px;width:${Math.round(size)}px;filter:hue-rotate(${rainbow?Math.random()*360:hue}deg) saturate(1.4) drop-shadow(0 2px 2px rgba(0,0,0,.4))`;document.body.appendChild(i);setTimeout(()=>i.remove(),1100)}
/* 曲のレシピ：inst=音色 / bpm / notes=[音の高さ,何拍目,長さ] / hue=音符の色 / dance=おどり方 */
const SONGS={
  banjo:{prop:'img:banjo',inst:'banjo',beat:.16,hue:0,dance:'bounce',on:'ラララ♪',col:'#ff8fd0',stage:'pink',
    notes:[[523,0],[659,1],[784,2],[659,3],[880,4],[784,5],[659,6],[523,7],[587,8],[698,9],[880,10],[784,11],[659,12],[784,13],[1047,14]],bass:[131,196]},
  violin:{prop:'svg:violin',inst:'violin',beat:.42,hue:190,dance:'sway',on:'リ〜リ〜♪',col:'#9fd8ff',stage:'blue',
    notes:[[659,0,2],[784,2],[880,3,2],[784,5],[659,6,2],[587,8,3]],bass:[165,220]},
  piano:{prop:'svg:piano',inst:'piano',beat:.2,hue:40,dance:'clap',on:'チャチャ♪',col:'#ffd34a',stage:'gold',
    notes:[[523,0],[659,1],[784,2],[1047,3],[784,4],[880,6],[784,7],[659,8],[523,10],[587,11],[659,12]],chord:[[262,330,392],[294,349,440],[262,330,392]],bass:[131,147]},
  voice:{prop:'svg:mic',inst:'voice',beat:.38,hue:300,dance:'sway',on:'ラ〜♪',col:'#ffb0e0',stage:'spot',hearts:1,
    notes:[[784,0,2],[880,2],[988,3,3],[880,6],[784,7,3]],bass:[196,262]},
  drunk:{prop:'img:ui/m_o_mug.png',inst:'drunk',beat:.26,hue:80,dance:'wobble',on:'ヒック♪',col:'#c8ff8a',stage:'green',
    notes:[[392,0],[440,1],[349,2,2],[392,4],[330,5],[294,6,2],[262,8,2]],bass:[98,110]},
  chip:{prop:'svg:radio',inst:'chip',beat:.09,hue:0,rainbow:1,dance:'shake',on:'ピコピコ♪',col:'#7fffd0',stage:'rave',
    notes:Array.from({length:24},(_,i)=>[[523,659,784,1047,784,659][i%6]*(i>=12?1.5:1),i]),bass:[131,131]},
};
function playSong(S){const b=S.beat;
  S.notes.forEach(([f,i,len=1])=>{const at=i*b,d=len*b*.92;
    if(S.inst==='banjo')tone(f,d,{type:'triangle',vol:.06,at});
    else if(S.inst==='violin')vo(f,{type:'sawtooth',at,dur:d+.15,vol:.04,att:.09,vib:7,vibF:5.5,lp:1800});
    else if(S.inst==='piano'){vo(f,{type:'triangle',at,dur:d+.25,vol:.06});vo(f*2,{type:'sine',at,dur:d,vol:.015})}
    else if(S.inst==='voice')vo(f,{type:'sine',at,dur:d+.2,vol:.06,att:.12,vib:9,vibF:5});
    else if(S.inst==='drunk')vo(f,{type:'triangle',at,dur:d,vol:.06,slide:f*(Math.random()<.5?.92:1.07),vib:12,vibF:3});
    else if(S.inst==='chip')tone(f,d,{type:'square',vol:.035,at})});
  const total=Math.max(...S.notes.map(([f,i,l=1])=>i+l));
  for(let i=0;i<total;i+=2){tone(S.bass[(i/2)%2],b*1.6,{type:S.inst==='chip'?'square':'sine',vol:S.inst==='chip'?.03:.07,at:i*b});
    if(S.inst==='chip'||S.inst==='banjo'||S.inst==='piano')noise(.04,{vol:S.inst==='chip'?.08:.04,at:(i+1)*b,freq:3500,type:'highpass'})}
  if(S.chord)S.chord.forEach((c,k)=>c.forEach(f=>vo(f,{type:'sine',at:k*4*b,dur:b*3,vol:.025})));
  if(S.inst==='drunk')setTimeout(()=>{tone(700,.12,{vol:.06,slide:1100});},total*b*500);
  return total*b*1000}
const DANCE={bounce:i=>`rotate(${i%2?10:-10}deg) translateY(${i%2?-8:0}px)`,sway:i=>`rotate(${i%2?5:-5}deg)`,clap:i=>`scale(${i%2?1.08:.96}) translateY(${i%2?-5:0}px)`,
  wobble:i=>`skewX(${i%2?12:-12}deg) rotate(${i%2?-6:6}deg)`,shake:i=>`translate(${(i%3-1)*7}px,${i%2?-6:4}px) rotate(${(i%3-1)*8}deg)`};
async function musicFx(sd,m,el,key){const S=SONGS[key];const [ox,oy]=ctr(el);
  const opp=[...document.querySelectorAll(isMe(sd)?'#ef .u':'#af .u')],oh=isMe(sd)?$('foeHero'):$('meHero'),dance=[...opp,oh].filter(Boolean);
  const pr=S.prop.startsWith('img:')?spImg(S.prop.slice(4),100,'origin-b'):S.prop.startsWith('svg:')?spSvg(S.prop.slice(4),S.prop==='svg:piano'?120:S.prop==='svg:radio'?110:76):spEmo(S.prop.slice(4),70);pr.classList.add('origin-b');
  const at=`translate(${ox}px,${oy-40}px) translate(-50%,-100%)`;
  document.body.classList.add('spstage','st-'+S.stage);
  await spAnim(pr,[{transform:at+' scale(0)'},{transform:at+' scale(1.15)'},{transform:at+' scale(1)'}],300,'cubic-bezier(.2,1.6,.5,1)');
  const dur=playSong(S),steps=Math.max(4,Math.round(dur/(S.beat*1000*2)));
  pr.animate(Array.from({length:steps},(_,i)=>({transform:at+' '+(S.dance==='shake'?`rotate(${(i%3-1)*16}deg) scale(1.1)`:`rotate(${i%2?14:-14}deg)`)})),{duration:dur*SPEED,easing:'ease-in-out',fill:'forwards'});
  dance.forEach((u,k)=>u.animate(Array.from({length:steps},(_,i)=>({transform:DANCE[S.dance](i)})).concat([{transform:'none'}]),{duration:dur*SPEED,easing:'ease-in-out',delay:k*50}));
  const iv=Math.max(70,S.beat*1000*.8);const nt=setInterval(()=>{noteFx(ox+(Math.random()-.5)*130,oy-80-Math.random()*40,S.hue,26+Math.random()*24,S.rainbow);
    const u=pick(dance);if(u){const [ux,uy]=ctr(u);noteFx(ux+(Math.random()-.5)*50,uy-30,S.hue,22,S.rainbow);if(S.hearts&&Math.random()<.4)fxImg(ux,uy-20,'x_hearts',40,'fxup',900)}},iv);
  setTimeout(()=>onomaX(el,S.on,S.col),380);
  await sleep(dur);clearInterval(nt);document.body.classList.remove('spstage','st-'+S.stage);spAnim(pr,[{opacity:1},{opacity:0}],250);spGone(pr,260)}
Object.assign(SPECIAL,{ragtime:(s,m,e)=>musicFx(s,m,e,'banjo'),korokichi:(s,m,e)=>musicFx(s,m,e,'violin'),mog:(s,m,e)=>musicFx(s,m,e,'piano'),
  lily:(s,m,e)=>musicFx(s,m,e,'voice'),bard:(s,m,e)=>musicFx(s,m,e,'drunk'),gadget:(s,m,e)=>musicFx(s,m,e,'chip')});
