/* ---- 出したとき：カードが「着地」する動き（キャラごとに ちがう）＋けむり・つぶつぶ。おもしろ技の子だけ 専用演出 ---- */
function spFor(id){const d=C[id];if(!d)return null;const fun=typeof FUN_IDS!=='undefined'&&FUN_IDS.includes(id);
  if(fun&&SPECIAL[id])return SPECIAL[id];return d.bc&&typeof BC_FX!=='undefined'&&BC_FX[d.bc]||null}
function entranceFx(m,from,mine){const el=uEl(m);if(!el||!HUMAN)return Promise.resolve();const d=C[m.id];
  const big=d.c>=6||d.r==='L';const pats=['flutter','bounce','spin','wobble','sprout','hop'];let h=7;for(const ch of m.id)h=(h*31+ch.charCodeAt(0))%9973;const pat=big?'slam':pats[h%pats.length];
  const r=el.getBoundingClientRect();let dx=0,dy=mine?160:-200;if(from){dx=from.left+from.width/2-(r.left+r.width/2);dy=from.top+from.height/2-(r.top+r.height/2)}
  const T=(x,y,ro=0,sx=1,sy=sx)=>`translate(${x}px,${y}px) rotate(${ro}deg) scale(${sx},${sy})`;let K,dur,landAt;
  if(pat==='flutter'){K=[{transform:T(dx,dy,0,.7),opacity:.6},{transform:T(dx*.3,-110,-18,.95),opacity:1,offset:.3},{transform:T(18,-60,14,1),offset:.55},{transform:T(-12,-20,-10,1),offset:.78},{transform:T(0,0,0,1.06,.92),offset:.9},{transform:T(0,0)}];dur=1000;landAt=.9}
  else if(pat==='bounce'){K=[{transform:T(dx,dy,0,.7)},{transform:T(dx*.3,-120,0,1),offset:.32},{transform:T(0,0,0,1.18,.82),offset:.5},{transform:T(0,-38,0,.95,1.05),offset:.64},{transform:T(0,0,0,1.1,.9),offset:.78},{transform:T(0,-12),offset:.88},{transform:T(0,0)}];dur=900;landAt=.5}
  else if(pat==='spin'){K=[{transform:T(dx,dy,-540,.3),opacity:.5},{transform:T(0,-30,-60,1.1),opacity:1,offset:.7},{transform:T(0,0,8,1.08,.94),offset:.85},{transform:T(0,0)}];dur=780;landAt=.85}
  else if(pat==='wobble'){K=[{transform:T(dx,dy,0,.7)},{transform:T(dx*.3,-90,0,1),offset:.35},{transform:T(0,0,0,1.1,.9),offset:.52},{transform:T(0,0,-12),offset:.64},{transform:T(0,0,9),offset:.74},{transform:T(0,0,-5),offset:.84},{transform:T(0,0,2),offset:.92},{transform:T(0,0)}];dur=950;landAt=.52}
  else if(pat==='sprout'){K=[{transform:T(dx*.5,dy*.5,0,.5),opacity:0},{transform:T(0,10,0,1,.05),opacity:1,offset:.35},{transform:T(0,0,0,.85,1.3),offset:.6},{transform:T(0,0,0,1.1,.88),offset:.8},{transform:T(0,0)}];dur=800;landAt=.6}
  else if(pat==='hop'){K=[{transform:T(dx,dy,0,.7)},{transform:T(dx*.5,dy*.5-70,-10,.9),offset:.3},{transform:T(dx*.2,dy*.2,0,1.05,.9),offset:.45},{transform:T(dx*.1,-50,8,1),offset:.62},{transform:T(0,0,0,1.12,.88),offset:.8},{transform:T(0,0)}];dur=900;landAt=.8}
  else {K=[{transform:T(0,-300,0,1.4),opacity:0},{transform:T(0,-300,0,1.4),opacity:1,offset:.25},{transform:T(0,0,0,1.25,.75),offset:.6},{transform:T(0,-14,0,.95,1.05),offset:.78},{transform:T(0,0)}];dur=760;landAt=.6}
  el.style.transformOrigin='50% 100%';const an=el.animate(K,{duration:dur,easing:'cubic-bezier(.35,.1,.4,1)'});
  setTimeout(()=>{if(!document.body.contains(el))return;const rr=el.getBoundingClientRect(),cx=rr.left+rr.width/2,by=rr.bottom-6;
    try{fxImg(cx,by,'x_smoke',rr.width*(big?2:1.5),'fxpuff',big?900:650)}catch(e){}try{fxImg(cx-rr.width*.45,by,'x_dust2',rr.width*.7,'fxpuff flipx',600);fxImg(cx+rr.width*.45,by,'x_dust2',rr.width*.7,'fxpuff',600)}catch(e){}
    burst(el,d.r==='N'?['✨']:['✨','⭐'],d.r==='N'?6:big?16:10,big?95:65);
    try{tone(big?70:120,big?.3:.14,{type:'sine',vol:big?.3:.16,slide:big?35:70});noise(big?.3:.12,{vol:big?.22:.1,freq:big?500:900})}catch(e){}
    if(big){shakeApp&&shakeApp()}},dur*landAt);
  return an.finished.catch(()=>{}).then(()=>{el.style.transformOrigin=''})}
{const _pc=playCard;playCard=async function(sd,i){
  if(!HUMAN)return _pc(sd,i);
  const c=sd.hand[i],d=c&&C[c.id];if(!c||!d||d.c>sd.coin||sd.board.length>=bmax(sd)||B.over)return false;
  let from=null;if(isMe(sd)){const he=$('hand')&&$('hand').children[i];if(he)from=he.getBoundingClientRect()}
  const sp=spFor(c.id),fun=typeof FUN_IDS!=='undefined'&&FUN_IDS.includes(c.id)&&SPECIAL[c.id];
  if(!fun)quietOn();
  sd.coin-=d.c;sd.hand.splice(i,1);const m=summon(sd,c.id,c.lv,c.plus||0,c);m.fresh=false;
  if(isMe(sd)&&hasRelic('twin')&&!B.firstPlay){m.sleep=false;m.attacks=m.kw.has('twice')?2:1}
  if(isMe(sd))B.firstPlay=true;
  if(!isMe(sd)){await showPlay(c.id,c.lv);from=null}
  const ce=$('coins');SFX.place();renderBattle();if(isMe(sd)&&ce&&d.c)coinFly($('coins'),uEl(m),d.c);SFX.summon();
  await entranceFx(m,from,isMe(sd));
  /* 10/26：おもしろ技の アニメは「出る → ひとこと → マーク」の あと、効果の ちょくぜんに（battlecry の中で）ながす */
  await sleep(250);
  B._spDone=null;
  {const el=uEl(m);if(el){speak(d.s,m.id,'v_'+m.id+'_s');sayBubble(el,d.s,!isMe(sd))}}
  await sleep(isMe(sd)?650:450);await kwFx(m);
  quietOn();try{await battlecry(sd,m,c)}finally{if(B)B._spDone=null}
  quietOff();await cleanup();if(HUMAN)renderBattle();return true}}

