/* ---- マップ：スクロールなし。今いる場所だけ見せる＋「ぜんたい」で縮小マップ ---- */
(function(){const st=document.createElement('style');st.textContent=`
.mapvp{position:relative;overflow:hidden;border-radius:14px;touch-action:none;margin:4px 0 0}
.mapvp.pan{-webkit-mask-image:linear-gradient(transparent 0,#000 44px,#000 calc(100% - 20px),transparent);mask-image:linear-gradient(transparent 0,#000 44px,#000 calc(100% - 20px),transparent)}
.mapvp>.amap{margin:0!important;transition:transform .7s cubic-bezier(.3,.8,.3,1);will-change:transform}
.mapall{position:fixed;inset:0;z-index:66;background:rgba(20,10,4,.82);display:grid;place-items:center;animation:sgin .25s ease-out}
.mapall .mbox{position:relative;border-radius:16px;overflow:hidden;box-shadow:0 0 0 3px #c99a4a,0 10px 30px rgba(0,0,0,.6);background:url(bg/bg_map.jpg) center/cover}
.mapall .mbox>.amap{position:absolute;left:0;top:0;transform-origin:0 0;margin:0!important;pointer-events:none}
.mapall .mbox .an3.now,.mapall .mbox .an3.cur{filter:drop-shadow(0 0 10px #fff36a) drop-shadow(0 0 22px #ffb300)}
.mapall .mhere{position:absolute;transform:translate(-50%,-100%);font-family:var(--display);font-size:14px;color:#3a1a06;background:#ffe27a;border:2px solid #7a4a12;border-radius:999px;padding:2px 10px;white-space:nowrap;animation:tpbeat 1.2s infinite;z-index:99}
.mapall .mcap{position:absolute;bottom:max(18px,env(safe-area-inset-bottom));left:0;right:0;text-align:center;color:#fff3d6;font-weight:800;font-size:13px;opacity:.85}
`;document.head.appendChild(st)})();
{const _mv=mapView;mapView=function(){_mv();if(!HUMAN)return;const map=$('map');if(!map)return;
  const vp=document.createElement('div');vp.className='mapvp';map.parentNode.insertBefore(vp,map);vp.appendChild(map);
  const H=map.offsetHeight;const fit=()=>{const top=vp.getBoundingClientRect().top;const h=Math.max(260,innerHeight-top-10);vp.style.height=h+'px';return h};
  const focusY=()=>{const n=map.querySelector('.an3.now')||[...map.querySelectorAll('.an3.done')].pop();if(n)return parseFloat(n.style.top)||0;return H-60};
  /* 見切れ防止：ノード（ボス台・看板・はみ出す飾りも）の 実際の上下はしを 測って、その範囲で動かす */
  const bounds=()=>{const t=map.style.transform;map.style.transform='none';const mr=map.getBoundingClientRect();let a=0,b=H;
    map.querySelectorAll('.an3,.an3 *').forEach(e=>{if(e.matches('.mbeam,.mrays,.mspk'))return;const r=e.getBoundingClientRect();if(!r.height)return;a=Math.min(a,r.top-mr.top);b=Math.max(b,r.bottom-mr.top)});map.style.transform=t;return[a-8,b+8]};
  const clampY=(ty,h)=>{const[a,b]=bounds();const lo=h-b,hi=-a;return lo>hi?(lo+hi)/2:Math.max(lo,Math.min(hi,ty))};
  /* スクロールするマップでも、マスが はしで半分 切れないように 位置をずらす（今いるマスは かならず見える） */
  const nodeBoxes=()=>{const t=map.style.transform;map.style.transform='none';const mr=map.getBoundingClientRect();const out=[...map.querySelectorAll('.an3')].map(n=>{let a=1e9,b=-1e9;[n,...n.querySelectorAll('*')].forEach(e=>{if(e.matches('.mbeam,.mrays,.mspk'))return;const r=e.getBoundingClientRect();if(!r.height)return;a=Math.min(a,r.top-mr.top);b=Math.max(b,r.bottom-mr.top)});return[a,b,n]});map.style.transform=t;return out};
  const snapY=(ty,h)=>{const bx=nodeBoxes();const[a,b]=bounds();const lo=h-b,hi=-a;const cur=map.querySelector('.an3.now')||[...map.querySelectorAll('.an3.done')].pop();
    const cuts=t=>bx.filter(([p,q])=>(p<-t&&q>-t)||(p<-t+h&&q>-t+h)).length;const curOk=t=>{const c=bx.find(x=>x[2]===cur);return !c||(c[0]>=-t-1&&c[1]<=-t+h+1)};
    const cand=[ty];bx.forEach(([p,q])=>{cand.push(-p+6,-q,h-q-6,h-p)});
    let best=ty,bs=1e9;cand.forEach(t=>{t=Math.max(lo,Math.min(hi,t));if(!curOk(t))return;const sc=cuts(t)*1000+Math.abs(t-ty);if(sc<bs){bs=sc;best=t}});return best};
  /* ぜんぶ入りきる／少しだけ はみ出す マップは、ちぢめて まるごと見せる（はしが切れない） */
  const fitAll=h=>{const[a,b]=bounds();const need=b-a;if(need>h/.72)return null;const sc=Math.min(1,h/need);return `translateY(${(-a*sc+(h-need*sc)/2).toFixed(1)}px) scale(${sc.toFixed(4)})`};
  map.style.transformOrigin='50% 0';
  const place=(anim)=>{const h=fit();const fa=fitAll(h);vp.classList.toggle('pan',!fa);if(fa){if(!anim)map.style.transition='none';map.style.transform=fa;if(!anim){void map.offsetWidth;map.style.transition=''}return}const y=focusY();const ty=snapY(clampY(h/2-y,h),h);if(!anim)map.style.transition='none';map.style.transform=`translateY(${ty}px)`;if(!anim){void map.offsetWidth;map.style.transition=''}};
  /* はじめは 一つ前の場所から、今の場所へ すーっと動く */
  const h0=fit();const y0=focusY();const start=clampY(h0/2-(y0+104),h0);map.style.transition='none';map.style.transform=fitAll(h0)||`translateY(${start}px)`;void map.offsetWidth;map.style.transition='';
  requestAnimationFrame(()=>place(true));map.querySelectorAll('img').forEach(im=>{if(!im.complete)im.addEventListener('load',()=>{if($('map')===map)place(true)},{once:true})});
  window.onresize=()=>{if($('map')===map)place(false)};
  /* ぜんたいボタン */
  const row=document.querySelector('#app .panel.row');if(row&&!$('mapall')){const b=document.createElement('button');b.className='btn ghost';b.id='mapall';b.textContent='🗺';b.title='マップ ぜんたい';const dk=$('dk');row.insertBefore(b,dk||null);
    b.onclick=()=>{SFX.tap&&SFX.tap();const ov=document.createElement('div');ov.className='mapall';const W=map.offsetWidth;
      const[ba,bb]=bounds();const HH=bb-ba;const sc=Math.min((innerWidth-40)/W,(innerHeight-120)/HH);const box=document.createElement('div');box.className='mbox';box.style.width=W*sc+'px';box.style.height=HH*sc+'px';
      const cl=map.cloneNode(true);cl.removeAttribute('id');cl.style.transformOrigin='0 0';cl.style.transform=`translateY(${-ba*sc}px) scale(${sc})`;cl.style.transition='none';cl.style.width=W+'px';cl.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));box.appendChild(cl);
      const n=[...map.querySelectorAll('.an3.done')].pop()||map.querySelector('.an3.now');if(n){const tag=document.createElement('div');tag.className='mhere';tag.textContent='いま ここ！';tag.style.left=Math.max(48,Math.min(W*sc-48,parseFloat(n.style.left)/100*W*sc))+'px';tag.style.top=Math.max(22,(parseFloat(n.style.top)-ba)*sc-26)+'px';box.appendChild(tag);
        const cn=cl.querySelectorAll('.an3')[[...map.querySelectorAll('.an3')].indexOf(n)];if(cn)cn.classList.add('cur')}
      ov.appendChild(box);ov.insertAdjacentHTML('beforeend','<div class="mcap">タップで もどる</div>');document.body.appendChild(ov);ov.onclick=()=>{SFX.tap&&SFX.tap();ov.remove()}}}
}}


