  const x=Math.max(8,Math.min(innerWidth-bw-8,cx-bw/2));let y=below?r.bottom+12:r.top-bh-12;if(!below&&y<6){b.classList.add('dn');y=r.bottom+12}if(below&&y+bh>innerHeight-6){b.classList.remove('dn');y=r.top-bh-12}
