const MOJI_DONE=new WeakSet(),MOJI_ORIG=new Map();let MOJI_OBS=null;
const MOJI_SKIP='#funpick,#funfoe,#funnoatk,#funhome,#funlab,script,style,#hair';
function mojiNode(n){if(MOJI_DONE.has(n))return;const p=n.parentElement;if(!p||!n.nodeValue.trim()||p.closest(MOJI_SKIP))return;MOJI_DONE.add(n);MOJI_ORIG.set(n,n.nodeValue);const v=mojiTxt(n.nodeValue);if(v!==n.nodeValue)n.nodeValue=v}
function mojiAll(root){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const ns=[];while(w.nextNode())ns.push(w.currentNode);ns.forEach(mojiNode)}
function mojiOn(on){if(on&&!MOJI_OBS){mojiAll(document.body);MOJI_OBS=new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')mojiNode(m.target);else m.addedNodes.forEach(a=>{if(a.nodeType===3)mojiNode(a);else if(a.nodeType===1)mojiAll(a)})}});MOJI_OBS.observe(document.body,{childList:true,subtree:true,characterData:true})}
  else if(!on&&MOJI_OBS){MOJI_OBS.disconnect();MOJI_OBS=null;MOJI_ORIG.forEach((v,n)=>{if(n.isConnected)n.nodeValue=v});MOJI_ORIG.clear()}}
{const _rb=renderBattle;renderBattle=function(){_rb();mojiOn(!!(B&&B.me&&B.me.moji>0&&!B.me.mojiLite&&HUMAN&&!B.over))}}
{const _fb=finishBattle;finishBattle=async function(...a){mojiOn(false);document.body.classList.remove('mojibake');return _fb.apply(this,a)}}
{const _bt=battle;battle=function(...a){mojiOn(false);return _bt.apply(this,a)}}


