(function(){const s=document.createElement('style');s.textContent=`
.sp0b{position:fixed;z-index:92;pointer-events:none;transform:translate(-50%,-100%);background:#fffaf0;color:#3a2412;border:3px solid #3a2412;border-radius:14px;padding:4px 10px;font-family:var(--display,inherit);font-size:15px;font-weight:900;white-space:nowrap;box-shadow:0 3px 0 rgba(0,0,0,.35);animation:sp0b .25s cubic-bezier(.2,1.6,.5,1)}
.sp0b:after{content:'';position:absolute;left:50%;bottom:-9px;margin-left:-7px;border:7px solid transparent;border-top-color:#3a2412;border-bottom:0}
@keyframes sp0b{0%{transform:translate(-50%,-100%) scale(.2)}100%{transform:translate(-50%,-100%) scale(1)}}
.sp0dark{position:fixed;inset:0;z-index:87;pointer-events:none;background:radial-gradient(circle at var(--x) var(--y),rgba(0,0,0,0) 0 70px,rgba(0,0,0,.75) 140px)}
.sp0flash{position:fixed;inset:0;z-index:91;pointer-events:none;background:#fff}
.sp0face{border-radius:50%;object-fit:cover;object-position:50% 22%;border:3px solid #ffd84a;box-shadow:0 0 0 2px #5a3410,0 6px 10px rgba(0,0,0,.45);background:#fff}
.sp0beam{position:fixed;z-index:86;pointer-events:none;width:120px;transform:translateX(-50%);background:linear-gradient(180deg,rgba(255,240,170,.0),rgba(255,240,170,.75) 40%,rgba(255,255,255,.9));filter:blur(2px)}`;document.head.appendChild(s)})();
const S0={
  img:(n,w)=>spImg(n.startsWith('x_')?`ui/${n}.png`:n,w),
  bub(){return null},
  _bubOld(x,y,t,ms=1100){const dl=Math.max(0,380-(performance.now()-(S0.t0||0)));if(dl>20){setTimeout(()=>S0.bub(x,y,t,ms),dl);return null}const b=document.createElement('div');b.className='sp0b';b.textContent=t;b.style.left=x+'px';b.style.top=y+'px';document.body.appendChild(b);setTimeout(()=>b.remove(),ms);return b},
  bark(at=0,f=700){vo(f,{type:'square',at,dur:.09,vol:.05,slide:f*.6,lp:1600});vo(f*.8,{type:'square',at:at+.11,dur:.1,vol:.05,slide:f*.45,lp:1600})},
  gun(at=0){nz(.18,{at,vol:.22,f0:2500,f1:300,type:'lowpass'});tone(90,.15,{type:'sine',vol:.12,at,slide:40})},
  clang(at=0){[620,930,1240].forEach((f,i)=>tone(f,.4,{type:'square',vol:.03,at:at+i*.005}));nz(.15,{at,vol:.1,f0:4000,type:'highpass'})},
  thud(at=0){tone(70,.25,{type:'sine',vol:.2,at,slide:35});nz(.2,{at,vol:.14,f0:300,type:'lowpass'})},
  hop:(el,n=3,h=18,ms=180)=>spAnim(el,Array.from({length:n*2+1},(_,i)=>({transform:`translateY(${i%2?-h:0}px) scale(${i%2?1.04:1},${i%2?.96:1})`})),ms*n*2,'ease-in-out'),
  shake:(el,n=6,d=5,ms=320)=>spAnim(el,Array.from({length:n+1},(_,i)=>({transform:i===n?'none':`translateX(${i%2?d:-d}px) rotate(${i%2?2:-2}deg)`})),ms,'linear'),
  dark(x,y){const d=document.createElement('div');d.className='sp0dark';d.style.setProperty('--x',x+'px');d.style.setProperty('--y',y+'px');document.body.appendChild(d);spAnim(d,[{opacity:0},{opacity:1}],250);return d},
  flash(ms=180){const f=document.createElement('div');f.className='sp0flash';document.body.appendChild(f);spAnim(f,[{opacity:.9},{opacity:0}],ms);spGone(f,ms+20)},
};

