    spAnim(sp,[{transform:SPT(ox,oy-60,1,-20)},{transform:SPT(ox,oy-60,1,20)},{transform:SPT(ox,oy-60,1,-20)},{transform:SPT(ox,oy-60,1,0)}],600,'ease-in-out');
    for(let i=0;i<8;i++)nz(.03,{at:.1+i*.06,vol:.06,f0:7000,type:'highpass'});onomaX(el,'ワシャワシャ…','#d0a0ff');
