/* =====================================================================
   おもしろ技アニメ その3（f11_sp2）：まだ専用アニメがなかった子たち
   ===================================================================== */
(()=>{const st=document.createElement('style');st.textContent=`
.sp2-line{position:fixed;left:0;top:0;height:3px;transform-origin:0 50%;z-index:88;pointer-events:none;border-radius:3px}
.sp2-fog{position:fixed;z-index:88;pointer-events:none;border-radius:50%;background:radial-gradient(closest-side,rgba(240,245,255,.9),rgba(220,230,245,0));filter:blur(4px)}
.sp2-txt{position:fixed;left:0;top:0;z-index:90;pointer-events:none;font-family:var(--display,sans-serif);font-weight:900;color:#fff;-webkit-text-stroke:1.5px #3a2410;paint-order:stroke;white-space:nowrap}
.sp2-gold{position:fixed;inset:0;z-index:58;pointer-events:none;background:radial-gradient(circle at 50% 40%,rgba(255,220,90,.45),rgba(120,60,0,.35) 70%)}
.sp2-dim{position:fixed;inset:0;z-index:58;pointer-events:none;background:rgba(20,10,40,.5)}
`;document.head.appendChild(st)})();
const sp2X=n=>'ui/x_'+n+'.png';
const sp2fly=(e,a,b,ms,ease='ease-out',delay=0)=>spAnim(e,[{transform:SPT(a[0],a[1],a[2]??1,a[3]??0),opacity:a[4]??1},{transform:SPT(b[0],b[1],b[2]??1,b[3]??0),opacity:b[4]??1}],ms,ease,delay);
function sp2div(cls,css=''){const d=document.createElement('div');d.className=cls;d.style.cssText=css;document.body.appendChild(d);return d}
function sp2txt(t,size,col='#fff'){const d=sp2div('sp2-txt',`font-size:${size}px;color:${col}`);d.textContent=t;return d}
function sp2lineEl(x1,y1,x2,y2,col='#fff',w=3){const d=sp2div('sp2-line',`background:${col};height:${w}px`);const len=Math.hypot(x2-x1,y2-y1),a=Math.atan2(y2-y1,x2-x1)*180/Math.PI;
  d.style.transform=`translate(${x1}px,${y1}px) rotate(${a}deg) scaleX(0)`;d.style.width=len+'px';return {d,go:ms=>d.animate([{transform:`translate(${x1}px,${y1}px) rotate(${a}deg) scaleX(0)`},{transform:`translate(${x1}px,${y1}px) rotate(${a}deg) scaleX(1)`}],{duration:ms,fill:'forwards'}).finished.catch(()=>{})}}
const sp2fe=(x,y)=>fakeEl(x,y);

