function sp2art(k,size,arg){const d=document.createElement('div');d.className='spimg';d.style.width=Math.round(size*1.25)+'px';d.innerHTML=SP2SVG[k](arg);d.firstChild.style.cssText='display:block;width:100%;height:auto;overflow:visible';document.body.appendChild(d);return d}
/* キャラの顔の まるいカットイン（カードの絵） */
function sp2face(id,size){const d=document.createElement('div');d.className='spimg sp2-face';const u=typeof cardArt==='function'?cardArt(id):null;
  d.style.cssText=`width:${size*1.3}px;height:${size*1.3}px;border-radius:50%;background:#d9b47a ${u?`url(${u}) center 22%/cover`:''};border:4px solid #ffd34a;box-shadow:0 0 0 3px #6a3a0a,0 6px 12px rgba(0,0,0,.5)`;document.body.appendChild(d);return d}


