/* =====================================================================
   おもしろ技アニメ その3（ゾンビ・ならず者・ギャングなど 28人）
   ===================================================================== */
(()=>{if(document.getElementById('sp3css'))return;const s=document.createElement('style');s.id='sp3css';s.textContent=`
.sp3-bub{position:fixed;z-index:91;pointer-events:none;background:#fffdf3;color:#3a2410;border:3px solid #3a2410;border-radius:16px;padding:5px 10px;font:900 14px/1.25 var(--display,sans-serif);white-space:nowrap;transform:translate(-50%,-100%);box-shadow:0 4px 0 rgba(0,0,0,.25);animation:sp3bub .25s cubic-bezier(.2,1.6,.5,1) both}
.sp3-bub::after{content:'';position:absolute;left:50%;bottom:-10px;margin-left:-7px;border:7px solid transparent;border-top-color:#3a2410}
@keyframes sp3bub{0%{transform:translate(-50%,-100%) scale(.2);opacity:0}100%{transform:translate(-50%,-100%) scale(1);opacity:1}}
.sp3-box{position:fixed;left:0;top:0;z-index:88;pointer-events:none}
.sp3-poem{position:fixed;z-index:90;pointer-events:none;background:linear-gradient(#fff6dc,#f1dcae);color:#5a3a1a;border:2px solid #8a6230;border-radius:6px;padding:8px 12px;font:italic 800 13px/1.5 serif;transform:translate(-50%,-50%);white-space:pre;box-shadow:0 6px 12px rgba(0,0,0,.35)}
.sp3-spot{position:fixed;inset:0;z-index:87;pointer-events:none;background:radial-gradient(circle at var(--x) var(--y),transparent 60px,rgba(10,5,20,.78) 130px)}
.sp3-gold{position:fixed;inset:0;z-index:86;pointer-events:none;background:radial-gradient(circle at var(--x) var(--y),rgba(255,220,90,.55),transparent 55%);mix-blend-mode:screen}
`;document.head.appendChild(s)})();
