const tLogoHTML=()=>{const mk=t=>[...t].map((c,k)=>`<b data-c="${c}" style="--k:${k}"><i data-c="${c}">${c}</i></b>`).join('');return `<div class="tl-in"><img class="tl-base" src="ui/t_logo.webp" alt=""><div class="tl-txt tl-wippy">${mk('ウィピィ')}<b class="tl-no" data-c="の" style="--k:5"><i data-c="の">の</i></b></div><div class="tl-txt tl-main">${mk('賞金稼ぎの旅')}</div><div class="tl-txt tl-sub">${mk('ウィピィのモンスターカードバトル')}</div></div>`};
function slotsWithLogo(){app().classList.add('slotscr');const keep=typeof MUS!=='undefined'&&MUS.cur&&MUS.cur!=='story';if(keep)window.NOMUS=1;try{_titleSlots()}finally{window.NOMUS=0}const l=document.querySelector('#app .logo');if(l){l.outerHTML=`<div class="tlogo static" style="width:min(86vw,420px);margin:0 auto -2px">${tLogoHTML()}</div>`;const t=document.querySelector('#app .tlogo.static');if(t)t.onclick=()=>{TITLE_PASSED=false;titleSplash()}}}
