/* ---- iPhoneでも 音量が かわるように：音は ぜんぶ WebAudio の 音量つまみを 通す ---- */
let SEVOL=null,BGMVOL=null;
sfxOut=function(){const a=ac();if(!a)return null;if(!SFXOUT){const c=a.createDynamicsCompressor();c.threshold.value=-18;c.ratio.value=4;const g=a.createGain();g.gain.value=2.2;SEVOL=a.createGain();g.connect(c);c.connect(SEVOL);SEVOL.connect(a.destination);SFXOUT=g;optApply()}return SFXOUT};
function bgmVol(){const a=ac();if(!a)return null;if(!BGMVOL){BGMVOL=a.createGain();BGMVOL.connect(a.destination);optApply()}return BGMVOL}
musBus=function(){const a=ac();if(!a)return null;if(!MUS.bus){MUS.bus=a.createGain();MUS.bus.gain.value=.8;MUS.bus.connect(bgmVol())}return MUS.bus};
const vcurve=v=>v<=0?0:Math.pow(v,1.8);  /* 小さい音まで こまかく えらべる */
function seFix(){if(SFXOUT&&!SEVOL&&AC){try{SFXOUT.disconnect();const c=AC.createDynamicsCompressor();c.threshold.value=-18;c.ratio.value=4;SEVOL=AC.createGain();SFXOUT.connect(c);c.connect(SEVOL);SEVOL.connect(AC.destination)}catch(e){}}}
optApply=function(){seFix();const bv=OPT.bgmOn?vcurve(OPT.bgm):0,sv=OPT.seOn?vcurve(OPT.se):0;
  try{if(SEVOL)SEVOL.gain.value=sv}catch(e){}try{if(BGMVOL)BGMVOL.gain.value=bv}catch(e){}
  VOICE.on=OPT.voiceOn&&OPT.voice>0;try{lsSet('wippy-voice',VOICE.on?'1':'0')}catch(e){}};
/* mp3 の曲は 読みこんで ループ再生（audio要素は iPhone で音量が きかないので つかわない） */
const MBUF={},MLOAD={};let MSRC=null,MNOW=null;
function mp3Buf(src){if(MBUF[src])return Promise.resolve(MBUF[src]);if(MLOAD[src])return MLOAD[src];const a=ac();if(!a)return Promise.resolve(null);
  return MLOAD[src]=fetch(src).then(r=>r.arrayBuffer()).then(ab=>new Promise((ok,ng)=>a.decodeAudioData(ab,ok,ng))).then(b=>(MBUF[src]=b)).catch(()=>null)}
const MPOS={};let MSTART=0;
function mp3Stop(){if(MSRC&&MNOW&&MBUF[MNOW]&&AC){MPOS[MNOW]=(AC.currentTime-MSTART)%MBUF[MNOW].duration}if(MSRC){try{MSRC.stop()}catch(e){}try{MSRC.disconnect()}catch(e){}MSRC=null}MNOW=null}
function mp3Play(src){if(MNOW===src&&MSRC)return;mp3Stop();MNOW=src;const a=ac();if(!a)return;
  mp3Buf(src).then(b=>{if(!b&&MNOW===src){try{const g=mediaGain(FP);if(g){try{g.disconnect()}catch(e){}g.connect(bgmVol());g.gain.value=1}if(FP.getAttribute('src')!==src){FP.src=src}FP.loop=true;FP.play().catch(()=>{});MSRC={stop(){FP.pause()},disconnect(){}}}catch(e){}return}if(!b||MNOW!==src||MSRC)return;const s=a.createBufferSource();s.buffer=b;s.loop=true;const g=a.createGain();g.gain.value=.9;s.connect(g).connect(bgmVol());const off=(src.includes('bgm_town')?(MPOS[src]||0):0)%b.duration;s.start(0,off);MSTART=a.currentTime-off;MSRC=s})}
/* 曲は 少なめに：町・マップ・お店＝町の曲 / バトル＝冒険の曲 / オープニング＝荒野の曲 / タイトル＝ウィピィのテーマ */
const MFILE2={title:'audio/bgm_title.mp3',story:'audio/western_story_short.mp3',town:'audio/bgm_town.mp3',map:'audio/bgm_town.mp3',mapnight:'audio/bgm_town.mp3',shop:'audio/bgm_town.mp3',saloon:'audio/bgm_town.mp3',event:'audio/bgm_town.mp3',battle:'audio/bgm_map.mp3',elite:'audio/bgm_map.mp3',bossmovie:'audio/western_story_short.mp3',boss:'audio/bgm_boss.mp3'};
music=function(n){if(window.NOMUS)return;window._lastMus=n;if(!HUMAN)return;MUS.cur=n;
  try{$('bgm').pause()}catch(e){}
  if(MUTED||!OPT.bgmOn){musStop();mp3Stop();return}
  if(MFILE2[n]){musStop();mp3Play(MFILE2[n]);return}
  mp3Stop();const tr=TRACKS[n];const a=ac();if(!tr||!a)return;musStop();
  if(musLoop(n,a.currentTime+.05))return;
  MUS.step=0;MUS.nextT=a.currentTime+.08;const spb=60/tr.bpm/2;
  MUS.timer=setInterval(()=>{if(MUTED||!AC)return;if(MUS.nextT<AC.currentTime)MUS.nextT=AC.currentTime+.05;while(MUS.nextT<AC.currentTime+1.5){playStep(tr,MUS.step,MUS.nextT);MUS.nextT+=spb;MUS.step=(MUS.step+1)%32}},60);
  renderTrack(n).then(b=>{if(!b||MUS.cur!==n||!MUS.timer)return;clearInterval(MUS.timer);MUS.timer=null;musLoop(n,MUS.nextT,MUS.step*spb)})};
{const _ms=musStop;musStop=function(){_ms();mp3Stop()}}
/* musLoop は バス（BGMの音量）を 通す */
musLoop=function(name,at,offset=0){const b=MUS.buf[name];if(!b||!AC)return false;const s=AC.createBufferSource();s.buffer=b;s.loop=true;s.connect(musBus());s.start(at,offset%b.duration);MUS.src=s;return true};
/* 声（読みあげ）の音量 */
try{if(window.speechSynthesis){const _sp=speechSynthesis.speak.bind(speechSynthesis);speechSynthesis.speak=u=>{try{u.volume=Math.min(1,OPT.voiceOn?vcurve(OPT.voice)*1.2:0)}catch(e){}_sp(u)}}}catch(e){}
/* 画面を とじたら 止める */
document.addEventListener("visibilitychange",()=>{try{if(!AC||AC.state==="closed")return;if(document.hidden)AC.suspend().catch(()=>{});else AC.resume().catch(()=>{})}catch(e){}});
/* 先に 曲を 読んでおく */
setTimeout(()=>{['audio/bgm_title.mp3','audio/bgm_town.mp3'].forEach(u=>{try{mp3Buf(u)}catch(e){}});setTimeout(()=>{try{mp3Buf('audio/bgm_map.mp3')}catch(e){}setTimeout(()=>{try{mp3Buf('audio/bgm_boss.mp3')}catch(e){}},6000)},4000)},1500);
/* むかしの #bgm（町の曲を audio要素で ならしていた）は 使わない：タップで いきなり大音量に なっていた */
try{const el=$('bgm');if(el){el.pause();el.removeAttribute('src');el.load();el.play=function(){return Promise.resolve()}}}catch(e){}

/* ---- ほかのアプリ・タブから もどってきたら、かならず 曲が また鳴る ---- */
(function(){let armed=false;
  const want=()=>HUMAN&&!MUTED&&OPT.bgmOn&&MUS.cur&&!window.NOMUS;
  const restart=()=>{if(!want()||!AC||AC.state!=='running')return;const n=MUS.cur;
    if(MFILE2[n]){const src=MFILE2[n];if(!(MNOW===src&&MSRC)){mp3Stop();mp3Play(src)}}
    else if(!MUS.timer&&!MUS.src){try{music(n)}catch(e){}}};
  const tryResume=()=>{if(!AC||document.hidden)return;const p=AC.state==='running'?Promise.resolve():AC.resume();
    Promise.resolve(p).catch(()=>{}).then(()=>setTimeout(()=>{if(AC.state==='running'){restart();disarm()}else arm()},120))};
  /* iPhone は 自動で もどせないことが ある → つぎに さわった しゅんかんに もどす */
  const onTouch=()=>{if(!AC)return;try{if(AC.state!=='running')AC.resume().catch(()=>{})}catch(e){}
    /* しずかな音を 1回 ならすと iPhone の音が もどりやすい */
    try{const b=AC.createBuffer(1,1,22050),s=AC.createBufferSource();s.buffer=b;s.connect(AC.destination);s.start(0)}catch(e){}
    setTimeout(()=>{if(AC.state==='running'){restart();disarm()}},150)};
  const ev=['pointerdown','touchend','keydown','click'];
  function arm(){if(armed)return;armed=true;ev.forEach(e=>addEventListener(e,onTouch,{capture:true,passive:true}))}
  function disarm(){if(!armed)return;armed=false;ev.forEach(e=>removeEventListener(e,onTouch,{capture:true}))}
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){tryResume();setTimeout(tryResume,600)}});
  addEventListener('pageshow',()=>tryResume());addEventListener('focus',()=>tryResume());
  /* 見はり：鳴っているはずなのに 止まっていたら なおす */
  setInterval(()=>{if(document.hidden||!want()||!AC)return;if(AC.state!=='running'){tryResume();return}restart()},2500);
  /* もどすときに 古い mp3 を とめたまま なら 位置から 再開できるよう、とじる前に 位置を おぼえる */
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&MSRC&&MNOW&&MBUF[MNOW]&&AC){MPOS[MNOW]=(AC.currentTime-MSTART)%MBUF[MNOW].duration}});
})();


