function comboFound(c){G.combos=G.combos||{};if(G.combos[c.id])return;G.combos[c.id]=Date.now();try{save()}catch(e){}
  if(!HUMAN)return;SFX.legend&&SFX.legend();
  const d=document.createElement('div');d.className='cbpop';d.innerHTML=`<small>💡 ひらめいた！</small><b>${c.ic} ${c.n}</b><span>${c.d}</span>`;document.body.appendChild(d);
  setTimeout(()=>d.classList.add('out'),2300);setTimeout(()=>d.remove(),2800)}
function comboCheck(){if(!B||!B.me)return;const b=B.me.board.filter(m=>m.hp>0),f=B.foe.board.filter(m=>m.hp>0);G.combos=G.combos||{};
  for(const c of CB){if(G.combos[c.id]||!c.t)continue;try{if(c.ev==='foe'?c.t(f):!c.ev&&c.t(b))comboFound(c)}catch(e){}}}
{const _pc=playCard;playCard=async function(sd,i){const c=sd&&sd.hand[i];const coinBefore=sd&&sd.coin;const ok=await _pc.apply(this,arguments);
  if(ok&&B&&sd===B.me){if(c&&C[c.id].bc==='coin')B._coinT=B.turn;if(c&&C[c.id].c>=4&&B._coinT===B.turn)comboFound(CB.find(x=>x.id==='coinbig'));comboCheck()}return ok}}
{const _cu=cleanup;cleanup=async function(){const r=await _cu.apply(this,arguments);if(B&&!B.over)comboCheck();return r}}
{const _st=startTurn;startTurn=async function(sd){const r=await _st.apply(this,arguments);if(B&&!B.over&&sd===B.me)comboCheck();return r}}
(function(){const st=document.createElement('style');st.textContent=`
.cbpop{position:fixed;left:50%;top:22%;transform:translate(-50%,0) scale(.6);z-index:9999;background:linear-gradient(#fff6c8,#ffd76a);color:#5a2a00;border:3px solid #fff;border-radius:18px;padding:10px 18px;text-align:center;box-shadow:0 0 0 4px #e9a400,0 10px 30px rgba(0,0,0,.5);animation:cbIn .45s cubic-bezier(.2,1.6,.4,1) forwards;pointer-events:none;min-width:220px}
.cbpop small{display:block;font-weight:900;letter-spacing:.15em;color:#c0392b}.cbpop b{display:block;font-family:var(--display);font-size:22px}.cbpop span{font-size:12px}
.cbpop.out{animation:cbOut .4s ease-in forwards}
@keyframes cbIn{to{transform:translate(-50%,0) scale(1)}}@keyframes cbOut{to{transform:translate(-50%,-30px) scale(.8);opacity:0}}
.cbgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px;padding:4px}
.cbgrid div{background:rgba(255,240,190,.12);border:2px solid #e9b949;border-radius:10px;padding:6px 8px;font-size:12px}
.cbgrid div b{display:block;font-size:14px}.cbgrid div.no{opacity:.5;border-style:dashed}`;document.head.appendChild(st)})();
