{const _dx=FACS.dex;FACS.dex=function(){_dx.apply(this,arguments);G.combos=G.combos||{};const got=CB.filter(c=>G.combos[c.id]).length;
  const p=document.createElement('div');p.className='panel';p.innerHTML=`<h2>💡 コンボ図鑑 <small>${got} / ${CB.length}</small></h2><div class="cbgrid">${CB.map(c=>G.combos[c.id]?`<div><b>${c.ic} ${c.n}</b>${c.d}</div>`:`<div class="no"><b>？？？</b>まだ ひらめいていない</div>`).join('')}</div>`;
  const first=document.querySelector('#app .panel');if(first)first.before(p);else app().prepend(p)}}


