const NEWTOK=(id,n,a,h,em,o={})=>TOK(id,n,a,h,em,o);
function NEWC(o){const {id,n,f,r,c,a,h,em,stage,stages,lines,note,...rest}=o;if(!id||C[id])return;
  def(id,n,f||'',r||'N',+c||1,+a||0,+h||1,em||'❔',{...rest,note,newc:1});if(lines&&lines.length)LINES[id]=lines;
  const ss=stages&&stages.length?stages:[stage];C[id].stages=ss.filter(s=>STAGES[s]);C[id].stage=C[id].stages[0];
  C[id].stages.forEach(s=>{if(!STAGES[s].pool.includes(id))STAGES[s].pool.push(id)});NEW_IDS.push(id)}

/* ---- ことば ---- */
const WX={sun:['はれ','☀️'],rain:['あめ','🌧️'],sand:['すなあらし','🌪️'],snow:['ゆき','❄️']};
Object.assign(KW_COL,{wx:'#f0a020',grow:'#58b04a',evo:'#e05aa0',rank:'#d0a020',gattai:'#4a90a8',fuse:'#d04020',jail:'#6a6a6a',wanted:'#a0602a',get:'#2a9a6a',healone:'#4ab04a',shave:'#8a8a8a',swap:'#7a5ad0',gold:'#d0a020',link:'#d07a3a'});
/* そだつ：合成（レベル）で のびる。Lv1 +0/+1×3回 → Lv3 +1/+1×4回 → Lv5 +1/+1×6回（おともの子は そのまま） */
function growOf(d,lv){const g=d.growT||0;if(d.tok)return{a:g,h:g,n:Math.max(1,Math.floor(6/g))};lv=lv||1;return{a:lv>=3?g:0,h:g,n:lv>=5?6:lv>=3?4:3}}
function newEff(d,lv){const L=[];const E=(k,ic,n,t,sh)=>L.push([ic,n,t,KW_COL[k],sh]);
  if(d.wx)E('wx',WX[d.wx][1],'天気',`見参！で「${WX[d.wx][0]}」を ${d.wv||1}つ よぶ（同じ天気は たまる）`,WX[d.wx][0]);
  if(d.growT){const G=growOf(d,lv);E('grow','🌱','うえるとそだつ',`自分のターンのはじめに +${G.a}/+${G.h}（${G.n}回まで）`+(d.tok?'':`　合成で のびる`),'そだつ')}
  if(d.evoK)E('evo','✨','しんかする！',`敵を${d.evoK}体 たおすと「${(d.evoF&&d.evoF.n)||'しんか'}」に しんか`,'しんか');
  if(d.rankK)E('rank','🎖️','昇進',`敵を${d.rankK}体 たおすごとに ⭐ +1/+1（2回まで）`,'昇進');
  if(d.gattai)E('gattai','🔩','がったい！','見参！：ほかのロボットがいたら、パーツになって がったい','がったい');
  const b={fuse:['🧨','ダイナマイト',`見参！：2ターン後に ドカン！ 敵キャラぜんいんに${d.v||2}`],jail:['🔒','牢屋','見参！：いちばん強い敵を 2ターン 牢屋へ'],wanted:['📜','手配書','見参！：いちばん強い敵に手配書。たおすと＄3＋1人ひく'],
    get:['🎁','手にいれる！',`見参！：同じしゅぞくの カードを${d.v||1}まい 手にいれる`],healone:['💚','ちりょう',`見参！：いちばん けがした仲間を${d.v||3}いやす`],shave:['✂️','効果けし','見参！：いちばん強い敵の とくべつな力を なくす'],swap:['🔄','さかさま','見参！：敵1体の 攻撃と体力を 入れかえる']}[d.bc];
  if(b)E(d.bc,b[0],b[1],b[2],b[1]);
  if(d.dr==='gold')E('gold','🪙','金塊',`やられたら 旅の賞金+＄${d.dv||2}`,'金塊');
  if(d.dr==='fuse')E('fuse','🧨','ダイナマイト',`やられたら 2ターン後に ドカン！ 敵キャラぜんいんに${d.dv||2}`,'ドカン');
  if(d.aura==='link')E('link','🤝','連携','となりの仲間が攻撃すると、同じ相手に 1ダメージ','連携');
  if(d.aura==='wxboost')E('wx','🌈','天気の名人','いるあいだ、天気の数が +1','天気+1');
  return L}
{const _el=effList;effList=function(id,lv){const L=_el.apply(this,arguments).filter(x=>x[2]);const d=C[id];return d?[...L,...newEff(d,lv)]:L}}
{const _ct=cardText;cardText=function(id,lv){let t=_ct.apply(this,arguments);t=t.split('。').filter(x=>x&&!['見参！','やられたら：','いるあいだ、'].includes(x)).join('。')||'とくになし';const d=C[id];if(!d)return t;const add=newEff(d,lv).map(x=>x[1]+'：'+x[2]);if(!add.length)return t;return (t==='とくになし'?'':t+'。')+add.join('。')}}

/* ---- 天気 ---- */
function wxN(){if(!B||!B.wx)return 0;const side=B.wx.side;return B.wx.n+(side?side.board.filter(m=>m.hp>0&&C[m.id].aura==='wxboost').length:0)}
function setWeather(sd,k,n){if(!B)return;if(B.wx&&B.wx.k===k){B.wx.n+=n;B.wx.side=sd}else B.wx={k,n,side:sd};
  if(HUMAN){say(`${WX[k][1]} 天気が「${WX[k][0]}」に！（×${wxN()}）`);try{renderBattle()}catch(e){}}}
async function wxEnd(sd){const w=B&&B.wx;if(!w||B.over)return;const n=wxN();const o=opp(sd);
  if(w.k==='sun'&&sd===w.side){for(let i=0;i<Math.min(n,6)&&!B.over;i++){const ts=[...o.board.filter(m=>m.hp>0),heroOf(o)];await damage(o,pick(ts),1,{quiet:true,fx:'magic',el:'fire'})}}
  if(w.k==='rain'&&sd===w.side){const x=Math.min(3,n);for(const s of [B.me,B.foe])s.board.forEach(m=>{if(m.frozen>0&&m.fzType!=='ice'){m.frozen=0;floatAt(uEl(m),'💧 目がさめた！','info')}});for(const s of [B.me,B.foe])s.board.forEach(m=>{if(m.hp>0&&m.hp<m.max){m.hp=Math.min(m.max,m.hp+x);floatAt(uEl(m),'+'+x,'heal')}});heal(1);B.foe.hp=Math.min(B.foe.max,B.foe.hp+1)}
  if(w.k==='snow'&&sd===w.side){const all=[...B.me.board,...B.foe.board].filter(m=>m.hp>0&&!m.frozen);for(let i=0;i<(n>=3?2:1);i++){const t=all.splice(rnd(all.length),1)[0];if(t){t.frozen=1;t.fzType='ice';floatAt(uEl(t),'🧊','info')}}}
}
{const _rb=renderBattle;renderBattle=function(){const r=_rb.apply(this,arguments);try{if(B&&B.wx&&HUMAN){const app_=$('app');let el=document.querySelector('.wxbadge');if(!el){el=document.createElement('div');el.className='wxbadge';document.body.appendChild(el)}
  el.textContent=`${WX[B.wx.k][1]} ${WX[B.wx.k][0]} ×${wxN()}`;el.style.cssText='position:fixed;top:8px;left:50%;transform:translateX(-50%);z-index:60;background:rgba(20,30,60,.8);color:#fff;border:2px solid #9ad0ff;border-radius:99px;padding:2px 12px;font-weight:900;font-size:14px;pointer-events:none'}else{const el=document.querySelector('.wxbadge');if(el&&(!B||!B.wx))el.remove()}}catch(e){}return r}}

/* ---- 見参！の新しい力 ---- */
{const _bc=battlecry;battlecry=async function(sd,m,c){await _bc.apply(this,arguments);const d=C[c.id];if(!d||!B||B.over)return;const o=opp(sd);const me=isMe(sd);
  const foesM=()=>o.board.filter(e=>e.hp>0),mine=()=>sd.board.filter(b=>b!==m&&b.hp>0);const v=d.v||0;
  if(d.wx)setWeather(sd,d.wx,(d.wv||1)+lvN(c.lv));
  switch(d.bc){
    case 'fuse':B.fuses=B.fuses||[];B.fuses.push({side:sd,left:2,v:(v||2)+lvN(c.lv)});floatAt(uEl(m),'🧨 2','info');if(HUMAN)say('🧨 ダイナマイト！ 2ターン後に ドカン！');break;
    case 'jail':{const t=strongest(foesM());if(t){o.board=o.board.filter(x=>x!==t);B.jail=B.jail||[];B.jail.push({m:t,side:o,left:2});if(HUMAN){say(`🔒 ${C[t.id].n}を 牢屋に入れた！（2ターン）`);renderBattle()}}break}
    case 'wanted':{const t=strongest(foesM());if(t){if(HUMAN&&typeof wantedFx==='function')try{await wantedFx(m,t)}catch(e){}t._wanted=sd;if(HUMAN)try{renderBattle()}catch(e){}}break}
    case 'get':{const pool=Object.keys(C).filter(id=>!C[id].token&&!C[id].out&&C[id].f===d.f&&id!==c.id&&C[id].r!=='L');for(let i=0;i<(v||1)+lvN(c.lv);i++){const id=pick(pool);if(id&&sd.hand.length<8)sd.hand.push({id,lv:c.lv||1,plus:0,_new:0,_tmp:1})}if(HUMAN)say('🎁 手にいれる！');break}
    case 'healone':{const t=mine().concat([m]).sort((a,b)=>(b.max-b.hp)-(a.max-a.hp))[0];if(t){const hx=(v||3)+lvB(c.lv);t.hp=Math.min(t.max,t.hp+hx);floatAt(uEl(t),'+'+hx,'heal')}break}
    case 'shave':{const t=strongest(foesM());if(t){t.kw.clear();t._shaved=1;floatAt(uEl(t),'✂️ 効果けし','info')}break}
    case 'swap':{const t=pick(foesM());if(t){const a=t.atk,h=t.hp;t.atk=h;t.hp=Math.max(1,a);t.max=Math.max(t.max,t.hp);floatAt(uEl(t),'🔄 さかさま','info')}break}
  }}}
/* オーラ「いるあいだ」の効果けし：けされた子のオーラは数えない */
{const _ab=auraBonus;auraBonus=function(sd,m){const sv=sd.board.filter(b=>b._shaved);if(!sv.length)return _ab.apply(this,arguments);const keep=sd.board;sd.board=sd.board.filter(b=>!b._shaved||b===m);try{return _ab.apply(this,arguments)}finally{sd.board=keep}}}

/* ---- ターンのはじめ：そだつ・ダイナマイト・牢屋 ---- */
{const _st=startTurn;startTurn=async function(sd){const r=await _st.apply(this,arguments);if(!B||B.over)return r;
  for(const m of sd.board){const d=C[m.id];if(!d.growT||m.hp<=0)continue;const G=growOf(d,m.lv);if((m.growN||0)>=G.n)continue;m.atk+=G.a;m.hp+=G.h;m.max+=G.h;m.growN=(m.growN||0)+1;m.grown=(m.grown||0)+G.h;floatAt(uEl(m),`🌱+${G.a}/+${G.h}`,'heal')}
  if(B.fuses)for(const f of B.fuses.filter(f=>f.side===sd)){f.left--;if(f.left<=0){f.done=1;const o=opp(sd);if(HUMAN){say('🧨 ドッカーン！');shakeApp&&shakeApp()}for(const e of o.board.filter(e=>e.hp>0))await damage(o,e,f.v,{quiet:true,fx:'enemy'})}}
  if(B.fuses)B.fuses=B.fuses.filter(f=>!f.done);
  if(B.jail)for(const j of B.jail.filter(j=>j.side===sd)){j.left--;if(j.left<=0&&sd.board.length<bmax(sd)){j.done=1;j.m.sleep=true;sd.board.push(j.m);if(HUMAN)say(`🔓 ${C[j.m.id].n}が 牢屋から 出てきた！`)}}
  if(B.jail)B.jail=B.jail.filter(j=>!j.done);
  await cleanup();if(HUMAN)try{renderBattle()}catch(e){}return r}}
{const _et=endTurnFx;endTurnFx=async function(sd){try{await wxEnd(sd)}catch(e){}return _et.apply(this,arguments)}}

/* ---- 攻撃：すなあらし・しんか・昇進・手配書・連携 ---- */
{const _at=attack;attack=async function(sd,m,t){
  if(B&&B.wx&&B.wx.k==='sand'&&m&&canAttack(m)&&Math.random()<Math.min(.5,.1*wxN())){m.attacks--;m.kw.delete('stealth');floatAt(uEl(m),'🌪️ スカッ！','info');if(HUMAN){try{renderBattle()}catch(e){}}return}
  const o=sd&&opp(sd);const r=await _at.apply(this,arguments);if(!B||!m)return r;
  const killed=t&&!t.hero&&t.hp<=0;
  if(killed){m.kills=(m.kills||0)+1;const d=C[m.id];
    if(d.evoK&&!m.evolved&&m.kills>=d.evoK){m.evolved=1;const e=d.evoF||{};m.atk+=e.a||2;m.hp+=e.h||2;m.max+=e.h||2;(e.kw||'').split(' ').filter(Boolean).forEach(k=>m.kw.add(k));m.evoName=e.n;floatAt(uEl(m),'✨ しんか！','crit');if(HUMAN){say(`✨ ${d.n}が「${e.n||'しんか'}」に しんかした！`);SFX.legend&&SFX.legend()}}
    if(d.rankK&&(m.rank||0)<2&&m.kills%d.rankK===0){m.rank=(m.rank||0)+1;m.atk++;m.hp++;m.max++;floatAt(uEl(m),'⭐ 昇進！','crit');if(HUMAN)say(`🎖️ ${d.n}が 昇進！ ${'⭐'.repeat(m.rank)}`)}
    if(t._wanted===sd){if(isMe(sd)){R.money+=3;drawCard(sd,1);if(HUMAN)say('📜 手配書の敵を たおした！ ＄3＋1人ひく')}}}
  if(t&&!killed&&!B.over&&o){const i=sd.board.indexOf(m);for(const nb of [sd.board[i-1],sd.board[i+1]])if(nb&&nb.hp>0&&C[nb.id].aura==='link'){if(t.hero||t.hp>0){await damage(o,t,1+lvP(nb.lv),{quiet:true});floatAt(uEl(nb),'🤝','info')}}await cleanup()}
  if(HUMAN)try{renderBattle()}catch(e){}
  return r}}

/* ---- 出したとき：がったい！ ---- */
{const _pc=playCard;playCard=async function(sd,i){const c=sd&&sd.hand[i];
  /* 場がいっぱいでも、ロボットがいれば がったいできる */
  if(c&&B&&!B.over&&C[c.id].gattai&&sd.board.length>=bmax(sd)&&C[c.id].c<=sd.coin){const base=sd.board.find(x=>x.hp>0&&C[x.id].f==='ro');
    if(base){sd.coin-=C[c.id].c;sd.hand.splice(i,1);const m=mkMinion(sd,c.id,c.lv,c.plus||0);base.atk+=m.atk;base.hp+=m.hp;base.max+=m.hp;m.kw.forEach(k=>base.kw.add(k));base.parts=(base.parts||0)+1;sd.grave.push(c);
      floatAt(uEl(base),'🔩 がったい！','crit');if(HUMAN){say(`🔩 がったい！ ${C[base.id].n}が パワーアップ！`);SFX.legend&&SFX.legend();renderBattle()}return true}}
  const ok=await _pc.apply(this,arguments);
  if(ok&&B&&c&&C[c.id].gattai){const m=sd.board.find(x=>x.card===c)||sd.board[sd.board.length-1];const base=sd.board.find(x=>x!==m&&x.hp>0&&(C[x.id].f==='ro'||x.f==='ro'));
    if(m&&base){base.atk+=m.atk;base.hp+=m.hp;base.max+=m.hp;m.kw.forEach(k=>base.kw.add(k));sd.board=sd.board.filter(x=>x!==m);base.parts=(base.parts||0)+1;floatAt(uEl(base),'🔩 がったい！','crit');if(HUMAN){say(`🔩 がったい！ ${C[base.id].n}が パワーアップ！`);SFX.legend&&SFX.legend();renderBattle()}}}
  return ok}}

/* ---- やられたら：金塊・ダイナマイト ---- */
{const _cu=cleanup;cleanup=async function(){if(B){for(const sd of [B.me,B.foe])for(const m of sd.board){if(m.hp>0||m._drd)continue;if(m.kw.has('revive')&&!m.revived)continue;const d=C[m.id];m._drd=1;
    if(d.dr==='gold'&&isMe(sd)&&R){const gx=(d.dv||2)+lvB(m.lv);R.money+=gx;floatAt(uEl(m),`🪙＄${gx}`,'heal')}
    if(d.dr==='fuse'){B.fuses=B.fuses||[];B.fuses.push({side:sd,left:2,v:(d.dv||2)+lvN(m.lv)})}}}
  return _cu.apply(this,arguments)}}


