NEW_IDS.forEach(id=>{const c=C[id];if(!c||c.token)return;if(!COLLECT.includes(id))COLLECT.push(id);if(!c.out&&c.st===1&&!PACK_POOL.includes(id))PACK_POOL.push(id);if(!c.out&&c.r!=='L'&&c.st===1&&!RUN_POOL.includes(id))RUN_POOL.push(id)});

/* ---- ぜんキャラ図鑑（データ画面の「コードを読みこむ」に book と入れる） ---- */
const BOOK_ST=['all','boss','new',...Object.keys(STAGES),'etc'];const BOSS_IDS=Object.keys(STAGES).map(s=>STAGES[s].boss);
function bookStages(id){const c=C[id];if(c.stages)return c.stages;return Object.keys(STAGES).filter(s=>STAGES[s].pool.includes(id)||(STAGES[s].elites||[]).includes(id)||STAGES[s].boss===id)}
function bookView(filter='all',page=0){
  if(!G){G=freshSave();G._book=1}
  const ids=COLLECT.filter(id=>C[id]&&!C[id].token).filter(id=>filter==='all'||(filter==='boss'?BOSS_IDS.includes(id):filter==='new'?C[id].newc:filter==='etc'?!bookStages(id).length:bookStages(id).includes(filter)));
  const order='LRN';if(filter==='boss')ids.sort((a,b)=>BOSS_IDS.indexOf(a)-BOSS_IDS.indexOf(b));else ids.sort((a,b)=>order.indexOf(C[a].r)-order.indexOf(C[b].r)||C[a].c-C[b].c);
  const nm=s=>s==='all'?'ぜんぶ':s==='boss'?'👑ボス':s==='new'?'🆕新':s==='etc'?'ほか':STAGES[s].ic+STAGES[s].n.replace(/ダストタウン|ブーツヒル|まぼろしの|ぐらぐら|まほうの|ホタルの|ゴールドラッシュ|小屋|走る|の街/g,'').slice(0,4);
  /* 1ページに 入るだけ（スクロールなし） */
  const W=Math.min(innerWidth,480),cw=Math.min(W*.22,92),ch=cw*1.48+8,cols=4,rows=Math.max(2,Math.floor((innerHeight-150)/ch)),per=cols*rows;
  const pages=Math.max(1,Math.ceil(ids.length/per));page=Math.max(0,Math.min(pages-1,page));
  app().innerHTML=`<div class="bkhead"><button class="bkback" id="bkb">←</button><button class="bkarrow" id="bkp" ${page?'':'disabled'}>◀</button><b>${page+1} / ${pages}</b><button class="bkarrow" id="bkn" ${page<pages-1?'':'disabled'}>▶</button><span class="small">${ids.length}体</span></div>
    <div class="bkchips">${BOOK_ST.map(s=>`<button data-s="${s}" class="${s===filter?'on':''}">${nm(s)}</button>`).join('')}</div>
    <input type="range" class="bkbar" id="bkr" min="0" max="${pages-1}" value="${page}" ${pages>1?'':'disabled'}>
    <div class="bkgrid" id="bkg" style="grid-template-columns:repeat(${cols},1fr)"></div>`;
  const g=$('bkg');ids.slice(page*per,page*per+per).forEach(id=>{const el=cardEl(id,1,{hideLv:true,badge:C[id].newc?'🆕':''});el.style.setProperty('--cw',cw+'px');el.onclick=()=>{SFX.tap();sheetCard(id,1,C[id].note?`<p class="small" style="opacity:.75">📝 ${C[id].note}</p>`:'')};g.appendChild(el)});
  const go=p=>{SFX.tap();bookView(filter,p)};
  $('bkp').onclick=()=>go(page-1);$('bkn').onclick=()=>go(page+1);$('bkr').onchange=e=>go(+e.target.value);
  let x0=null;g.ontouchstart=e=>{x0=e.touches[0].clientX};g.ontouchend=e=>{if(x0==null)return;const dx=e.changedTouches[0].clientX-x0;x0=null;if(dx<-50&&page<pages-1)go(page+1);else if(dx>50&&page>0)go(page-1)};
  document.querySelectorAll('.bkchips button').forEach(b=>b.onclick=()=>{SFX.tap();bookView(b.dataset.s,0)});
  const on=document.querySelector('.bkchips .on');if(on)on.scrollIntoView({inline:'center',block:'nearest'});
  $('bkb').onclick=()=>{SFX.tap();if(G&&G._book)G=null;title()}}
(function(){const st=document.createElement('style');st.textContent=`
.bkhead{display:flex;align-items:center;gap:8px;justify-content:center;background:rgba(40,20,8,.85);border:2px solid #6b4a2a;border-radius:14px;padding:4px 8px;margin:4px 6px}
.bkhead b{font-family:var(--display);font-size:20px;color:#ffe9b0;min-width:76px;text-align:center}
.bkhead .small{position:absolute;right:16px;opacity:.8}
.bkback{position:absolute;left:12px;border:2px solid #a07a4a;background:rgba(255,255,255,.08);color:#ffe9b0;border-radius:10px;padding:2px 10px;font:inherit;font-size:16px}
.bkarrow{border:0;background:#e9b949;color:#4a2400;border-radius:10px;width:44px;height:36px;font-size:18px;font-weight:900;box-shadow:0 3px 0 #8a5a10}
.bkarrow:disabled{opacity:.3}
.bkchips{display:flex;gap:4px;overflow-x:auto;padding:2px 8px;scrollbar-width:none;height:26px;align-items:center}
.bkchips::-webkit-scrollbar{display:none}
.bkchips button{flex:none;height:22px;line-height:18px;border:1.5px solid #e9b949;background:rgba(60,30,10,.75);color:#ffe9b0;border-radius:99px;padding:0 8px;font:inherit;font-size:11px;font-weight:900;white-space:nowrap}
.bkchips button.on{background:#e9b949;color:#4a2400}
.bkbar{width:calc(100% - 24px);margin:2px 12px;accent-color:#e9b949;height:18px}
.bkgrid{display:grid;gap:4px;justify-items:center;padding:2px 6px}`;document.head.appendChild(st)})();
{const _rc=readCode;readCode=function(code){if(typeof code==='string'&&code.trim().toLowerCase()==='book'){setTimeout(()=>{closeModal();bookView()},0);return null}return _rc.apply(this,arguments)}}
