/* =====================================================================
   
   ・酔っぱらい と カチコチ（こおりづけ）は 同じ「1回休み」。
     酔っぱらいは 💧みずダメージで 目がさめる／カチコチは 🔥ほのおダメージで とける
   ・カードの マークは 2つまで（3つ目からは「+1」）→ Lv の札と かさならない
   ・book図鑑：カードの説明に「合成前」「合成後」ボタン
   ===================================================================== */
const ICE_RE=/氷|雪|ゆき|こおり|フォクシア|ユキ|シロクマ|ふぶき/;
const FIRE_RE=/火|炎|マグマ|ダイナマイト|ばくはつ|ボイラー|竜|ドラゴン|ひくいどり|ヒノ|チャッカ|ノーベル|ほのお|たいよう|太陽/;
const WATER_RE=/水|雨|あめ|レイン|カエル|しずく|滴|ケロ|ワニ|タコ|セレスティア|みず|ミズ|オアシス/;
for(const id in C){const c=C[id];if(c.token)continue;if(ICE_RE.test(c.n))c.iceK=1;if(!c.el){if(FIRE_RE.test(c.n))c.el='fire';else if(WATER_RE.test(c.n))c.el='water'}}
if(C.ice)C.ice.iceK=1;
Object.assign(KW_COL,{fire:'#e8501a',water:'#2a8ad8'});
{const _bt=bcText;bcText=function(d,lv){if(d&&d.iceK){if(d.bc==='stun')return 'いちばん強い敵を カチコチに こおらせる（1回休み）';if(d.bc==='stunall')return '敵ぜんいんを カチコチに こおらせる（1回休み）'}return _bt.apply(this,arguments)}}
{const _el=effList;effList=function(id,lv){const L=_el.apply(this,arguments);const d=C[id];if(!d)return L;
  if(d.el==='fire')L.push(['🔥','ほのお','この子の ダメージで カチコチが とける',KW_COL.fire,'ほのお']);
  if(d.el==='water')L.push(['💧','みず','この子の ダメージで 酔っぱらいが さめる',KW_COL.water,'みず']);return L}}
/* 見参！で 1回休みに なった子の 種類を きめる */
{const _bc=battlecry;battlecry=async function(sd,m,c){const all=B?[...B.me.board,...B.foe.board]:[];const before=new Set(all.filter(x=>x.frozen>0));await _bc.apply(this,arguments);
  if(B){const ice=C[c.id]&&C[c.id].iceK;[...B.me.board,...B.foe.board].forEach(x=>{if(x.frozen>0&&!before.has(x)){x.fzType=ice?'ice':'drunk';if(ice)floatAt(uEl(x),'🧊 カチコチ！','info')}})}}}
{const _dm=damage;damage=async function(sd,t,n,o={}){
  if(t&&!t.hero&&t.frozen>0&&t.hp>0&&B){const el=(o&&o.el)||(o&&o.src&&C[o.src.id]&&C[o.src.id].el);
    if(el==='fire'&&t.fzType==='ice'){t.frozen=0;t._ice=0;t._iceA=0;floatAt(uEl(t),'🔥 とけた！','heal')}
    else if(el==='water'&&t.fzType!=='ice'){t.frozen=0;floatAt(uEl(t),'💧 目がさめた！','heal')}}
  return _dm.call(this,sd,t,n,o)}}
/* 休みが おわったら 種類を わすれる */
{const _st=startTurn;startTurn=async function(sd){const r=await _st.apply(this,arguments);if(B)sd.board.forEach(m=>{if(!m.frozen)delete m.fzType});return r}}
/* 場の子の上の マーク：カチコチは 🧊 */
{const _rb=renderBattle;renderBattle=function(){const r=_rb.apply(this,arguments);try{if(B&&HUMAN)for(const sd of [B.me,B.foe])sd.board.forEach(m=>{const el=uEl(m);if(!el)return;el.querySelectorAll('.fzmark').forEach(x=>x.remove());
  if(m.frozen>0)el.insertAdjacentHTML('beforeend',`<i class="fzmark">${m.fzType==='ice'?'🧊':'🍺'}</i>`)})}catch(e){}return r}}

/* ---- カードの マークは 2つまで ---- */
{const _ce=cardEl;cardEl=function(id,lv,o){const el=_ce.apply(this,arguments);try{const k=el.querySelector('.kws');if(k){const is=[...k.children];is.forEach((x,i)=>x.dataset.i=i);if(is.length>2){k.classList.add('ico');if(is.length>3){const aw=is.findIndex(x=>x.textContent.includes('覚醒'));const keep=aw>=0?[is[0],is[1],is[aw]]:is.slice(0,3);is.forEach(x=>{if(!keep.includes(x))x.remove()})}}}}catch(e){}return el}}

/* ---- book図鑑：合成前／合成後 ---- */
function bookSheet(id,lv,aw){const c=C[id];const can=typeof AWK!=='undefined'&&AWK[id]&&BX[id];if(aw&&!can)aw=0;lv=Math.max(1,Math.min(MAX_LV,lv||1));
  const lvb=`<div class="lvbar">${Array.from({length:MAX_LV},(_,i)=>`<i class="${i<lv?'on':''}"></i>`).join('')}<b>${lv>=MAX_LV?'Lv MAX':'Lv'+lv}</b></div>`;
  const head=aw?lvb+`<div class="awbox"><b>👑 覚醒後：${BX[id].nm}</b><span>${BX[id].d}</span></div>`
    :`<div class="lvbar">${Array.from({length:MAX_LV},(_,i)=>`<i class="${i<lv?'on':''}"></i>`).join('')}<b>${lv>=MAX_LV?'Lv MAX':'Lv'+lv}</b></div>`;
  sheetCard(id,lv,head,
    `<button class="btn bkpre" id="bkpre" ${lv<=1?'disabled':''}>合成前</button><button class="btn bkpost" id="bkpost" ${lv>=MAX_LV?'disabled':''}>合成後</button>${can?`<button class="btn bkaw${aw?' on':''}" id="bkaw">覚醒後</button>`:''}`,aw?((AWK[id]&&AWK[id].plus)||2):0);
  $('bkpre').onclick=()=>{SFX.tap();bookSheet(id,lv-1,aw)};$('bkpost').onclick=()=>{SFX.tap();bookSheet(id,lv+1,aw)};const a=$('bkaw');if(a)a.onclick=()=>{SFX.tap();bookSheet(id,lv,aw?0:1)}}
{const _bv=bookView;bookView=function(){_bv.apply(this,arguments);document.querySelectorAll('#bkg .card').forEach(el=>{const id=el.dataset.cid;if(id)el.onclick=()=>{SFX.tap();bookSheet(id,1)}})}}
