/* ケッチャム：敵の手札から えらぶ */
function pickFromHand(o,n){return new Promise(res=>{if(!o.hand.length)return res([]);
  if(!HUMAN){res([...o.hand].sort((a,b)=>C[b.id].c-C[a.id].c).slice(0,n));return}
  const chosen=[];modal(`<h2>🎩 ${AWN.ketcham[0]}</h2><p class="small" style="text-align:center">${n}まい えらぼう</p><div class="grid" id="kh"></div>`);
  o.hand.forEach(c=>{const el=cardEl(c.id,c.lv||1,{});el.style.setProperty('--cw','min(26vw,100px)');el.onclick=()=>{if(chosen.includes(c))return;chosen.push(c);el.classList.add('glowL');SFX.tap();if(chosen.length>=Math.min(n,o.hand.length)){setTimeout(()=>{closeModal();res(chosen)},250)}};$('kh').appendChild(el)})})}
const AWS={
  async bibiri(sd,m){const o=opp(sd);for(let i=0;i<10&&B&&!B.over;i++){const ts=[...o.board.filter(e=>e.hp>0),heroOf(o)];await damage(o,pick(ts),1,{quiet:true});if(HUMAN)await sleep(70)}},
  zombino(sd){while(roomOf(sd)>0)summon(sd,'zombieT',2)},
  async eagle(sd){const o=opp(sd);for(const e of foesOf(sd)){e._wntA=1;e._wanted=sd}for(let k=0;k<2;k++)for(const e of foesOf(sd))await damage(o,e,2,{quiet:true})},
  mustache(sd){B.foe._coinZero=1;if(HUMAN)say('🎩 グランドサロン貸し切り！ 敵は つぎのターン コイン0')},
  async bunyan(sd){const o=opp(sd);if(HUMAN)shakeApp&&shakeApp();for(const e of foesOf(sd))await damage(o,e,5,{quiet:true});await damage(o,heroOf(o),5);for(let i=0;i<2;i++)if(roomOf(sd))summon(sd,'logT',1)},
  nanashi(sd,m){sd.board.filter(x=>x!==m).forEach(x=>{if(x.card)sd.grave.push(x.card)});sd.board=[m];sd.grave.push(...sd.hand,...sd.deck);sd.hand=[];sd.deck=[];m.atk=99;m.hp=99;m.max=99;m.baseAtk=99;if(HUMAN){shakeApp&&shakeApp();say('名無しのガンマン「……」 すべてを すてた。 99/99')}},
  async ketcham(sd){const o=opp(sd);const got=await pickFromHand(o,2);for(const c of got){const i=o.hand.indexOf(c);if(i<0)continue;o.hand.splice(i,1);if(roomOf(sd)>0){const nm=summon(sd,c.id,c.lv||1,c.plus||0,c);if(nm){nm.sleep=false;nm.attacks=nm.kw.has('twice')?2:1}}else if(sd.hand.length<8)sd.hand.push(c)}},
  ruler(sd){const pool=Object.keys(C).filter(id=>!C[id].token&&!C[id].out&&C[id].f==='st'&&C[id].c<=4);while(roomOf(sd)>0){summon(sd,pick(pool),3)}},
  ma(sd,m){const n=Math.min(2,roomOf(sd));for(let i=0;i<n;i++)summon(sd,'goonT',3)},
  ice(sd){foesOf(sd).forEach(e=>{e.frozen=1;e._iceA=1;e.fzType='ice';floatAt(uEl(e),'🧊','info')})},
  ikoku(sd){const o=opp(sd);const ts=foesOf(sd).sort((a,b)=>b.atk+b.hp-a.atk-a.hp).slice(0,Math.min(2,roomOf(sd)));for(const t of ts){o.board=o.board.filter(x=>x!==t);t.sleep=false;t.attacks=t.kw.has('twice')?2:1;sd.board.push(t)}},
  adara(sd,m){m.bar=3;sd.board.forEach(b=>{if(b.hp>0)b.kw.add('shield')})},
  amelie(sd){foesOf(sd).forEach(e=>{const a=e.atk,h=e.hp;e.atk=h;e.hp=Math.max(1,a);e.max=Math.max(e.hp,1)});{const n=Math.min(2,roomOf(sd));for(let i=0;i<n;i++)summon(sd,'illuT',2)}},
  capone(sd){sd.maxB=5;const T=['nyaBari','nyaHaya','nyaMamo','nyaNoro'];while(roomOf(sd)>0)summon(sd,pick(T),3);sd.board.forEach(b=>{if(b.hp>0){b.atk+=2;floatAt(uEl(b),'+2','heal')}})},
};
