  if(all.some(m=>m.parts))hint('gattai');if(B.fuses&&B.fuses.length)hint('fuse');if(B.jail&&B.jail.length)hint('jail');if(all.some(m=>m.evolved))hint('evolve');if(all.some(m=>m.rank))hint('rank');
