const NN_MOVES={
  nerai:{ic:'🎯',n:'ねらいうち',d:'ひとりを ねらって ズドン！'},
  midare:{ic:'🔫',n:'みだれうち',d:'バン！バン！バン！'},
  reload:{ic:'🔄',n:'リロード',d:'たまを こめなおして 体力回復'},
  nirami:{ic:'👁️',n:'にらみ',d:'ギロッ… 敵ぜんいん 攻撃-1'}};
async function nnAnnounce(k,foe){if(!HUMAN)return;let w=0;while(uiBusy()&&w++<40)await sleep(150);const M=NN_MOVES[k];
  const d=document.createElement('div');d.className='nnann'+(foe?' foe':'');d.innerHTML=`<i>${M.ic}</i><b>${M.n}</b><small>${M.d}</small>`;document.body.appendChild(d);
  WSFX&&WSFX.cock&&WSFX.cock();await sleep(1100);d.classList.add('out');await sleep(260);d.remove()}
function nnReticle(el){if(!HUMAN||!el)return null;const r=el.getBoundingClientRect();const t=document.createElement('div');t.className='nnret';t.style.cssText=`left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;width:${Math.max(r.width,r.height)*1.1}px`;t.innerHTML='<i></i>';document.body.appendChild(t);tone(1800,.08,{vol:.05});tone(1800,.08,{vol:.05,at:.18});return t}
function nnBullets(el,n,onEach){return new Promise(res=>{if(!HUMAN||!el){for(let i=0;i<n;i++)onEach(i);return res()}const r=el.getBoundingClientRect();let k=0;
  for(let i=0;i<n;i++)setTimeout(()=>{const b=document.createElement('div');b.className='nnbul';document.body.appendChild(b);const x0=r.left+r.width/2,y0=r.top+r.height*.35,dx=(i%2?1:-1)*(20+Math.random()*40);
    tone(2400+i*120,.06,{type:'square',vol:.04});
    b.animate([{transform:`translate(${x0}px,${y0}px) rotate(0)`,opacity:1},{transform:`translate(${x0+dx*.5}px,${y0-46}px) rotate(200deg)`,opacity:1,offset:.35},{transform:`translate(${x0+dx}px,${y0+90}px) rotate(560deg)`,opacity:0}],{duration:620,easing:'cubic-bezier(.2,.6,.5,1)',fill:'forwards'}).onfinish=()=>b.remove();
    onEach(i);if(++k===n)setTimeout(res,650)},i*190)})}
/* 技の 中身（sd＝つかう がわ、m＝名無しの ユニット か null（ボス）） */
async function nnDo(k,sd,m){const o=opp(sd);const foe=sd===B.foe;const selfEl=m?uEl(m):heroEl(sd);
  await nnAnnounce(k,foe);if(!B||B.over)return;
  if(k==='nerai'){const us=o.board.filter(e=>e.hp>0);const t=us.sort((a,b)=>b.atk+b.hp-a.atk-a.hp)[0]||heroOf(o);const n=foe?4:6;
    const el=t.hero?heroEl(o):uEl(t);const ret=nnReticle(el);if(HUMAN)await sleep(700);if(HUMAN){SFX.shot&&SFX.shot();onoma(el,'ズドン！','#ffd23a');shakeApp&&shakeApp()}ret&&ret.remove();
    await damage(o,t,n,{quiet:true})}
  if(k==='midare'){B._bang=(B._bang||0)+1;try{for(let i=0;i<3&&B&&!B.over;i++){const ts=[...o.board.filter(e=>e.hp>0),heroOf(o)];const t=pick(ts);const el=t.hero?heroEl(o):uEl(t);
      if(HUMAN){SFX.shot&&SFX.shot();onoma(el,'バン！','#ffd23a')}await damage(o,t,2,{quiet:true});if(HUMAN)await sleep(230)}}finally{if(B)B._bang--}}
  if(k==='reload'){await nnBullets(selfEl,6,()=>{if(m){m.hp+=1;m.max=Math.max(m.max,m.hp)}else if(foe){B.foe.hp=Math.min(B.foe.max,B.foe.hp+1)}else heal(1);
      if(HUMAN){floatAt(selfEl,'+1','heal');try{if(m)renderBattle();else updHero()}catch(e){}}})}
  if(k==='nirami'){if(HUMAN){onoma(selfEl,'ギロッ…','#c06cff');tone(140,.5,{type:'sawtooth',vol:.05,slide:90});await sleep(450)}
    for(const e of o.board.filter(e=>e.hp>0)){e.atk=Math.max(0,e.atk-1);if(HUMAN)floatAt(uEl(e),'攻撃-1','info')}if(HUMAN)await sleep(400)}
  if(B&&!B.over)await cleanup();if(HUMAN&&B)try{renderBattle()}catch(e){}}
