function deRope(root){if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.nodeValue.includes('🪢')&&!(n.parentNode&&/^(SCRIPT|STYLE|TEXTAREA|OPTION|TITLE)$/.test(n.parentNode.nodeName))?1:3});const L=[];while(w.nextNode())L.push(w.currentNode);
  for(const n of L){const f=document.createDocumentFragment();n.nodeValue.split('🪢').forEach((t,i)=>{if(i){const im=document.createElement('img');im.className='ico-lasso';im.src=LASSO_IMG;im.alt='';f.appendChild(im)}if(t)f.appendChild(document.createTextNode(t))});n.parentNode.replaceChild(f,n)}}
