const NEWBC_T={
  trade:'じぶんの 手札と 敵の 手札を ぜんぶ とりかえる',
  mimic:'いちばん強い 敵と 同じ 攻撃と 体力に なる',
  twin:'じぶんと 同じ子が もう1体 あらわれる（体力1）',
  hug:'いちばん強い 敵に だきついて、いっしょに たおれる',
  lullaby:'場の ぜんいん（敵も なかまも）が ねむって、1回休み',
  wish:'手札で いちばん コストの高い なかまを、ただで 場に出す',
  swap:'いちばん弱い なかまと、いちばん強い 敵が 入れかわる',
  party:'お祭りだ！ 場の ぜんいん（敵も なかまも）+1/+1',
  kick:'いちばん強い 敵を、敵の 山札の いちばん下へ けっとばす',
  forge:'手札を 1まい とかして、そのコストぶん +○/+○',
  steal:'敵の 手札を 1まい もらう',
  echo:'つぎに 出す なかまの 見参が 2回 おきる',
  balloon:'いちばん強い なかまが ふうせんで うかんで、ねらわれなくなる（かくれんぼ）',
  encore:'アンコール！ 場の なかま1人の 見参が もう1回 おきる',
  plant:'場に「たね」を 1つ うえる',
  depart:'しゅっぱつ しんこう！ なかま ぜんいん、すぐ 攻撃できる'};

const NEWBC={
  async trade(sd,m,c,o){const a=sd.hand,b=o.hand;sd.hand=b;o.hand=a;sd.hand.forEach(x=>x._new=isMe(sd)?1:0);if(HUMAN)say('🔄 手札を ぜんぶ とりかえた！')},
  async mimic(sd,m,c,o){const t=strongest(o.board.filter(e=>e.hp>0));if(!t){if(HUMAN)say('🪞 …まねする 敵が いない！');return}m.atk=t.atk;m.baseAtk=t.atk;m.hp=t.hp;m.max=t.hp;floatAt(uEl(m),`🪞 ${t.atk}/${t.hp}`,'heal');if(HUMAN)say(`🪞 ${C[t.id].n}の まねっこ！`)},
  async twin(sd,m,c){if(roomOf(sd)<=0){if(HUMAN)say('👯 …場が いっぱいで ふえられない！');return}const t=summon(sd,c.id,c.lv,c.plus||0,null);if(t){t.hp=1;t.max=1;t.out=1;floatAt(uEl(t),'👯','info')}if(HUMAN)say('👯 ふえちゃった！')},
  async hug(sd,m,c,o){const t=strongest(o.board.filter(e=>e.hp>0));if(!t){if(HUMAN)say('🤗 …だきつく 敵が いない！');return}if(HUMAN)say(`🤗 ${C[t.id].n}に だきついた！ いっしょに たおれる！`);await damage(o,t,999,{fx:'magic'});await damage(sd,m,999,{quiet:true})},
  async lullaby(sd,m){[...B.me.board,...B.foe.board].forEach(u=>{if(u.hp>0&&!u.kw.has('nostun')){u.frozen=1;floatAt(uEl(u),'💤','info')}});if(HUMAN)say('💤 こもりうた… みんな ねむっちゃった')},
  async wish(sd,m){const units=sd.hand.filter(x=>C[x.id]&&!C[x.id].spell).sort((a,b)=>C[b.id].c-C[a.id].c);const h=units[0];if(!h||roomOf(sd)<=0){if(HUMAN)say('🌠 …ねがいごとが とどかなかった');return}sd.hand.splice(sd.hand.indexOf(h),1);const u=summon(sd,h.id,h.lv,h.plus||0,h);if(u)floatAt(uEl(u),'🌠','heal');if(HUMAN)say(`🌠 ねがいごと！ ${C[h.id].n}が ただで 来てくれた！`)},
  async swap(sd,m,c,o){const mine=sd.board.filter(x=>x!==m&&x.hp>0).sort((a,b)=>(a.atk+a.hp)-(b.atk+b.hp))[0];const t=strongest(o.board.filter(e=>e.hp>0));if(!mine||!t){if(HUMAN)say('🔀 …入れかえる 相手が いない！');return}
    sd.board[sd.board.indexOf(mine)]=t;o.board[o.board.indexOf(t)]=mine;t.sleep=true;mine.sleep=true;t.attacks=0;mine.attacks=0;if(HUMAN)say(`🔀 ${C[mine.id].n}と ${C[t.id].n}が 入れかわった！`)},
  async party(sd){[...B.me.board,...B.foe.board].forEach(u=>{if(u.hp>0){u.atk++;u.baseAtk=(u.baseAtk||0)+1;u.hp++;u.max++;floatAt(uEl(u),'🎉+1/+1','heal')}});if(HUMAN)say('🎉 お祭りだ！ みんな +1/+1')},
  async kick(sd,m,c,o){const t=strongest(o.board.filter(e=>e.hp>0));if(!t){if(HUMAN)say('🦶 …けとばす 敵が いない！');return}o.board=o.board.filter(x=>x!==t);o.deck.push(t.card||{id:t.id,lv:t.lv||1,plus:0});if(HUMAN){burst(uEl(m),['💨'],6);say(`🦶 ${C[t.id].n}を 山札の いちばん下へ けとばした！`)}},
  async forge(sd,m){const h=sd.hand.slice().sort((a,b)=>C[b.id].c-C[a.id].c)[0];if(!h){if(HUMAN)say('🔨 …とかす カードが ない！');return}sd.hand.splice(sd.hand.indexOf(h),1);sd.grave.push(h);const k=C[h.id].c;m.atk+=k;m.baseAtk=(m.baseAtk||0)+k;m.hp+=k;m.max+=k;floatAt(uEl(m),`🔨+${k}/+${k}`,'heal');if(HUMAN)say(`🔨 ${C[h.id].n}を とかして、+${k}/+${k}！`)},
  async steal(sd,m,c,o){if(!o.hand.length){if(HUMAN)say('🫳 …敵の 手札が からっぽ！');return}const x=o.hand.splice(rnd(o.hand.length),1)[0];if(sd.hand.length<8){x._new=isMe(sd)?1:0;sd.hand.push(x)}if(HUMAN)say(isMe(sd)?`🫳 ${C[x.id].n}を もらった！`:`🫳 ${C[x.id].n}を とられた！`)},
  async echo(sd,m){sd._echo=1;if(HUMAN)say('📢 つぎの なかまの 見参が 2回 おきるよ！')},
  async balloon(sd,m){const t=strongest(sd.board.filter(x=>x!==m&&x.hp>0))||m;t.kw.add('stealth');floatAt(uEl(t),'🎈','info');if(HUMAN)say(`🎈 ${C[t.id].n}が ふうせんで うかんだ！`)},
  async encore(sd,m){if(B._encoreDepth)return;const t=pick(sd.board.filter(x=>x!==m&&x.hp>0&&C[x.id]&&C[x.id].bc&&!['encore','echo','twin','wish'].includes(C[x.id].bc)));if(!t){if(HUMAN)say('🎤 …アンコールに こたえる なかまが いない！');return}if(HUMAN)say(`🎤 アンコール！ ${C[t.id].n}の 見参を もう1回！`);B._encoreDepth=1;try{await battlecry(sd,t,t.card||{id:t.id,lv:t.lv||1,plus:0})}finally{if(B)B._encoreDepth=0}},
  async plant(sd){const t=summon(sd,'seedT',1);if(t)floatAt(uEl(t),'🌱','heal');if(HUMAN)say(t?'🌱 たねを うえた！':'🌱 …場が いっぱい！')},
  async depart(sd,m){sd.board.forEach(x=>{if(x.hp>0){x.sleep=false;x.attacks=x.kw.has('twice')?2:1}});if(HUMAN)say('🚂 しゅっぱつ しんこう！ みんな すぐ 攻撃できる！')}};
{const _bc=battlecry;battlecry=async function(sd,m,c){const d=c&&C[c.id];if(!d||!d.bc)return _bc.apply(this,arguments);
  const run=async()=>{if(NEWBC[d.bc]){if(HUMAN&&typeof bcFx==='function')await bcFx(m);await NEWBC[d.bc](sd,m,c,opp(sd))}else await _bc.call(this,sd,m,c)};
  await run();if(B&&!B.over&&sd._echo&&d.bc!=='echo'){sd._echo=0;if(HUMAN)say('📢 もう1回！');await run()}}}
{const _bt=bcText;bcText=function(d,lv){if(d&&NEWBC_T[d.bc])return NEWBC_T[d.bc].replace('+○/+○','+コスト/+コスト');return _bt.apply(this,arguments)}}
