/* 状態の 表示：敵の ようすを 右上の わくの 下に 色つきの 文字で（ウンチで 画面が のびないように） */
const STATUS_DEF=[{k:'unko',n:'ウンチ',c:'#c98a4a',t:f=>f.unko>0},{k:'hanage',n:'はなげ',c:'#bdbdbd',t:f=>f.hanage>0}];
{const _rb5=renderBattle;renderBattle=function(){const r=_rb5.apply(this,arguments);try{if(!B||!HUMAN)return r;const fs=$('foeStage');if(!fs)return r;
  const fn=fs.querySelector('.fname');if(fn)fn.innerHTML=fn.innerHTML.replace(/\s*💩/g,'').replace(/\s*👃/g,'');
  const on=STATUS_DEF.filter(s=>s.t(B.foe));let box=fs.querySelector('.fstat');if(!on.length){if(box)box.remove();return r}
  if(!box){box=document.createElement('div');box.className='fstat';fs.appendChild(box)}const side=fs.querySelector('.fside');const top=side?side.offsetTop+side.offsetHeight+6:110;box.style.top=top+'px';
  box.innerHTML=on.map(s=>`<span class="st">じょうたい：<b style="color:${s.c}">${s.n}</b></span>`).join('')}catch(e){}return r}}
/* おこぼれ：敵や 味方が たおれると、その場所に お肉 → おこぼれの子へ すいこまれる。たべるたびに ハゲタカの 鳴き声 */
function vultureCry(){try{tone(1300,.18,{type:'sawtooth',vol:.05,slide:700});tone(1500,.22,{type:'square',vol:.03,slide:600,at:.16})}catch(e){}}
{const _ko=koFx;koFx=async function(m,el,mine){const r=_ko.apply(this,arguments);try{if(HUMAN&&B&&el){const eaters=[...B.me.board,...B.foe.board].filter(u=>u!==m&&u.hp>0&&u.kw&&u.kw.has('feed'));
  if(eaters.length){const a=el.getBoundingClientRect();eaters.forEach((u,i)=>{const ue=uEl(u);if(!ue)return;const b=ue.getBoundingClientRect();const meat=document.createElement('div');meat.className='meatfly';meat.textContent='🍖';
    meat.style.left=(a.left+a.width/2-15)+'px';meat.style.top=(a.top+a.height/2-15)+'px';document.body.appendChild(meat);
    setTimeout(()=>{meat.style.transform=`translate(${b.left+b.width/2-a.left-a.width/2}px,${b.top+b.height/2-a.top-a.height/2}px) scale(.5)`;meat.style.opacity='.2'},350+i*120);
    setTimeout(()=>{meat.remove();vultureCry();try{floatAt(ue,'🍖 もぐもぐ','heal')}catch(e){}},950+i*120)})}}}catch(e){}return r}}
