async function bShoot(n,who){const t=who||bStrong()||heroOf(B.me);if(HUMAN){const el=t.hero?heroEl(B.me):uEl(t);if(el){try{fxAt(el,'x_hit',90,'fxpop',450)}catch(e){}}}await damage(B.me,t,n,{fx:'enemy'});await cleanup()}
