function bHeal(n){B.foe.hp=Math.min(B.foe.max,B.foe.hp+n);if(HUMAN){floatAt(heroEl(B.foe),`+${n}`,'heal');try{fxAt(heroEl(B.foe),'x_heal',80,'fxup',700)}catch(e){}}}
