function bBuff(a,h){B.foe.board.filter(m=>m.hp>0).forEach(m=>{m.atk+=a;m.baseAtk=(m.baseAtk||0)+a;m.hp+=h;m.max+=h;floatAt(uEl(m),`+${a}/+${h}`,'heal')})}
