const bMoveEvery=()=>BTIER()<4?3:BTIER()<8?2:1;
function bNext(){const L=BMOVES[STAGES[R.sid].boss];if(!L)return null;let k;do{k=rnd(L.length)}while(L.length>1&&k===B._bmLast);return k}
