const LINEUP_IDS={};
(function(){if(typeof ART_HOME==='undefined')return;const BOSSES=new Set(Object.values(STAGES).map(s=>s.boss).filter(Boolean));const byN={};Object.keys(C).forEach(id=>{if(C[id]&&!C[id].token)byN[C[id].n]=byN[C[id].n]||id});
  for(const sid in LINEUP){const s=STAGES[sid];if(!s)continue;const L=LINEUP[sid];const ok=id=>id&&C[id]&&!C[id].token&&!BOSSES.has(id)&&!C[id].out&&ART_HOME[id]===sid;
    const th=(L.f?Object.keys(ART_HOME).filter(id=>ok(id)&&C[id].f===L.f):(L.n||[]).map(n=>byN[n]).filter(ok));LINEUP_IDS[sid]=th;const T=new Set(th);if(th.length<3)continue;
    const ti=Object.keys(STAGES).indexOf(sid);
    const home=Object.keys(ART_HOME).filter(ok);const rar=id=>ti===0?C[id].r==='N':ti<=2?(C[id].r==='N'||(ti===2&&C[id].r==='R'&&C[id].c<=3)):C[id].r!=='L';
    /* ざこ：その ステージの 子（安い ノーマル）。テーマの子は 2ばい */const mk=home.filter(id=>C[id].r==='N'&&C[id].c<=(ti<=2?2:3));if(mk.length>=3)s.mooks=[...mk,...mk.filter(id=>T.has(id))];
    /* 賞金首：その ステージの 子 */const elOk=id=>ti<=2?((C[id].r==='N'&&C[id].c>=3)||(ti>0&&C[id].r==='R'&&C[id].c<=4)):ti<=6?((C[id].r==='R'&&C[id].c<=4)||(C[id].r==='N'&&C[id].c>=4)):((C[id].r==='R'&&C[id].c<=5)||(C[id].r==='N'&&C[id].c>=4));
    const el=home.filter(elOk);if(el.length>=2)s.elites=el;
    /* 敵の デッキ：その ステージの 子 ぜんいん（テーマの子は 2ばい、重い子は 1ばい） */const heavy=new Set((L.heavy||[]));const hp=home.filter(rar);
    let pool=[...hp,...hp.filter(id=>T.has(id)&&!heavy.has(C[id].n))];
    /* 安い子が たりない ときだけ、前の 子を すこし まぜる */const cheap=hp.filter(id=>C[id].c<=2).length;if(cheap<5){const old=(s.pool||[]).filter(id=>C[id]&&ART_HOME[id]!==sid&&C[id].c<=2&&!BOSSES.has(id));pool=[...pool,...old.slice(0,5-cheap)]}
    if(pool.length>=6)s.pool=pool}
  /* ランダムな 特色は やめて、テーマの 名前だけ */
  for(const k in STAGE_THEME)delete STAGE_THEME[k];for(const sid in LINEUP)STAGE_THEME[sid]={ic:LINEUP[sid].ic,t:LINEUP[sid].t,d:'この ステージの なかまたちが 出てくるよ'}})();
/* バランス：顔ぶれ変更後の ボス体力 */
