/* =====================================================================
   敵の 考え（10/27）：だれでも つっこまない。攻撃0や 損な ぶつかりは まつ。たおせる子・強い子を ねらう。勝てるときは 顔へ
   ===================================================================== */
{const _aa=aiAttack;aiAttack=async function(sd){if(isMe(sd))return _aa.apply(this,arguments);
  const o=opp(sd);
  const scoreOf=(m,t)=>{const a=atkOf(sd,m);if(a<=0&&!m.kw.has('deadly'))return -99;
    if(t.hero){let s=2.4;if(R&&R.hp<=a)s=60;return s}
    const kills=t.hp<=a||(m.kw.has('deadly')&&!t.kw.has('shield'))||false;const back=atkOf(o,t);const dies=back>=m.hp&&!m.kw.has('shield');
    let s=0;if(kills)s+=2.2+back*.7+(t.atk||0)*.2;else s+=Math.min(a,t.hp)/Math.max(1,t.hp)*0.8;
    if(dies)s-=1.4+a*.35+(m.max||m.hp)*.15;else s+=.4;if(t.kw.has('taunt'))s+=.6;if(t._wanted)s+=.2;return s};
  for(let k=0;k<12;k++){if(B.over)return;const ms=sd.board.filter(canAttack);if(!ms.length)return;
    const ts=validTargets(sd);if(!ts.length){ms.forEach(m=>m.attacks=0);return}
    /* 勝てるなら ぜんいんで 顔へ */
    const faceOk=ts.some(t=>t.hero);const total=ms.reduce((a,m)=>a+Math.max(0,atkOf(sd,m)),0);
    let pickM=null,pickT=null,best=-99;
    for(const m of ms)for(const t of ts){let s=scoreOf(m,t);if(faceOk&&t.hero&&R&&total>=R.hp)s+=40;s+=Math.random()*.3;if(s>best){best=s;pickM=m;pickT=t}}
    /* いい 手が ない子は まつ（攻撃0、損な ぶつかり） */
    if(!pickM||best<0.25){ms.forEach(m=>m.attacks=0);if(HUMAN&&ms.length)try{const m=ms[0];floatAt(uEl(m),'…まつ','info')}catch(e){}return}
    await attack(sd,pickM,pickT);if(HUMAN)await sleep(600)}}}
