peddler=function(){
  const offers=offerCards(3);let relic=pick(RELIC_IDS.filter(x=>!R.relics.includes(x)));R.bag=R.bag||[];
  if(!HUMAN){if(R.money>=6&&Math.random()<.5&&offers[0]){R.money-=6;R.deck.push(offers[0])}if(R.money>=4&&R.hp<R.maxhp*.6){R.money-=4;heal(8)}return}
  music('shop');let busy=false;
  const draw_=(say)=>{modal(`<div class="pdhead"><h2>🏪 行商人</h2></div><p class="muted">「旅の役に立つもの、あるよ」 旅の賞金：<b id="pdm">＄${R.money}</b></p><div class="grid" id="og"></div>
    <div class="choice"><button id="hl"><span class="i">🩹</span><div>手当て ＄4<small>体力を8いやす（今${R.hp}/${R.maxhp}）</small></div></button>
    ${relic?`<button id="rl"><span class="i">${RELICS[relic].ic}</span><div>${RELICS[relic].n} ＄${RELIC_PRICE(relic)}<small>${RELICS[relic].d}（この冒険のあいだ ずっと）</small></div></button>`:''}</div>
    <div class="pdsell"><div class="pdst">どうぐを 売る</div><div class="pdsl" id="sl">${R.bag.length?'':'<span class="muted">売れる どうぐは ないよ</span>'}</div></div>
    <button class="btn" id="ok" style="width:100%">先へ進む</button>`);
    if(say)pdSay(say);else pdPos();
    offers.forEach((c,i)=>{if(!c)return;const el=cardEl(c.id,c.lv,{badge:'＄6'});el.style.setProperty('--cw','min(27vw,100px)');
      el.onclick=async()=>{if(busy)return;if(R.money<6)return toast('お金がたりない');busy=true;R.money-=6;R.deck.push(c);offers[i]=null;await pdBuyFx(el);busy=false;draw_()};$('og').appendChild(el)});
    $('hl').disabled=R.money<4||R.hp>=R.maxhp;$('hl').onclick=async()=>{if(busy)return;busy=true;R.money-=4;heal(8);SFX.heal&&SFX.heal();await pdBuyFx($('hl'),{fly:false});busy=false;draw_()};
    const rl=$('rl');if(rl){rl.disabled=R.money<RELIC_PRICE(relic);rl.onclick=async()=>{if(busy)return;busy=true;R.money-=RELIC_PRICE(relic);const k=relic;relic=null;await pdBuyFx(rl);giveRelic(k);busy=false;draw_()}}
    R.bag.forEach((k,i)=>{const it=ITEMS[k];if(!it)return;const b=document.createElement('button');b.className='pdit';b.innerHTML=`<span class="i">${it.ic}</span><b>${it.n}</b><em>＋＄${SELL_P(k)}</em>`;
      b.onclick=()=>{if(busy)return;busy=true;const p=SELL_P(k);R.bag.splice(i,1);R.money+=p;SFX.kaching();pdFloat(b,'＋＄'+p);
        b.animate([{transform:'scale(1)',opacity:1},{transform:'scale(1.1)',opacity:1,offset:.3},{transform:'translateY(-30px) scale(.5)',opacity:0}],{duration:450,fill:'forwards'}).onfinish=()=>{busy=false;draw_(pick(['いい品だね！ 買い取るよ','おっ、これは いいね！','まいど！ たすかるよ']))}};$('sl').appendChild(b)});
    $('ok').onclick=()=>{closeModal();afterNode()}};
  draw_();
};
