const KJ_ONE={"撃": "う", "弾": "ひ", "匹": "ひき", "酔": "よ", "尋": "たず", "吹": "ふ", "吉": "きち", "捕": "つか", "斧": "おの", "影": "かげ", "突": "つ", "銃": "じゅう", "杯": "はい", "竜": "りゅう", "霧": "きり", "逃": "に", "怖": "こわ", "沼": "ぬま", "剣": "けん", "掘": "ほ", "亀": "かめ", "倒": "たお", "娘": "むすめ", "伸": "の", "抜": "ぬ", "郎": "ろう", "鐘": "かね", "爺": "じい", "占": "うらな", "絆": "きずな", "腕": "うで", "眠": "ねむ", "肩": "かた", "弦": "げん", "鍛": "きた", "狙": "ねら", "爪": "つめ", "寝": "ね", "澄": "す", "輝": "かがや", "嫌": "きら", "刃": "は", "払": "はら", "迎": "むか", "匂": "にお", "頃": "ころ", "還": "かえ", "滴": "しずく", "僕": "ぼく", "瓶": "びん", "盾": "たて", "駆": "か", "押": "お", "怒": "いか", "舞": "ま", "枠": "わく", "婆": "ばば", "釣": "つ", "炎": "ほのお", "崖": "がけ", "汗": "あせ", "怪": "かい", "塔": "とう", "獲": "え", "稼": "かせ", "醒": "せい", "冒": "ぼう", "牢": "ろう", "塊": "かい", "昇": "しょう", "盗": "とう", "帽": "ぼう", "魔": "ま", "鑑": "かん", "了": "りょう", "峡": "きょう", "携": "けい", "拍": "はく", "闘": "とう", "騒": "さわ", "脱": "だつ", "零": "れい", "袋": "ふくろ", "盤": "ばん", "逮": "たい", "仙": "せん", "拳": "けん", "陣": "じん", "鼓": "こ", "簿": "ぼ", "葬": "そう", "罰": "ばつ", "励": "はげ", "甲": "こう", "羅": "ら", "威": "い", "緒": "しょ", "頼": "たの", "巡": "めぐ", "吟": "ぎん", "叡": "えい", "智": "ち", "呪": "のろ", "徴": "ちょう", "嵐": "あらし", "狼": "おおかみ", "援": "えん", "召": "め", "溶": "と", "豪": "ごう", "貫": "かん", "禄": "ろく", "撤": "てっ", "悟": "ご", "控": "こう", "訴": "そ", "儀": "ぎ", "緊": "きん", "爆": "ばく", "胞": "ほう", "喪": "も", "泰": "たい", "依": "い", "貢": "こう", "礁": "しょう", "敢": "かん", "騎": "き", "冶": "や", "妖": "よう", "霊": "れい", "獄": "ごく", "裕": "ゆう", "卑": "ひ", "怯": "きょう", "蹄": "てい", "巨": "きょ", "僧": "そう", "賊": "ぞく", "床": "とこ", "凶": "きょう", "閃": "せん", "姫": "ひめ", "妃": "ひ", "姐": "ねえ", "坊": "ぼう", "荒": "あら", "輩": "はい", "噴": "ふん", "睡": "すい"};
const KJ_CH="動酒亀了仙伸依倒僕僧儀冒冶凶刃剣励匂匹卑占叡召吉吟吹呪喪噴坊塊塔妃妖姐姫威娘婆嫌寝尋峡崖嵐巡巨帽床弦弾影徴怒怖怪怯悟払抜押拍拳捕掌掘控援携撃撤攻敢斧昇智杯枠汗沼泰溶滴澄炎爆爪爺牢狙狼獄獲瓶甲盗盤盾眠睡礁禄稼突竜簿絆緊緒罰羅肩胞脱腕舞荒葬袋裕訴豪貢貫賊蹄輝輩迎逃逮還郎酔醒釣銃鍛鐘鑑閃闘陣零霊霧頃頼駄駆騎騒魔鼓";
const KJ_TEST=new RegExp('['+KJ_CH+']');
const KJ_KEEP='賞金稼ぎの旅';
function kjFix(t){if(!t||!KJ_TEST.test(t))return t;let s=t.split(KJ_KEEP);s=s.map(x=>{for(const [a,b] of KJ_PAIRS)if(x.indexOf(a)>=0)x=x.split(a).join(b);
  x=x.replace(/弾(?![きかくけこい])/g,'だん').replace(/撃(?![ちつっった])/g,'げき');
  return x.replace(new RegExp('['+KJ_CH+']','g'),c=>KJ_ONE[c]||c)});return s.join(KJ_KEEP)}
function kjWalk(root){try{if(!root)return;if(root.nodeType===3){if(root.parentElement&&root.parentElement.closest('.tlogo,[data-nokj]'))return;const v=root.nodeValue;if(KJ_TEST.test(v)){const n=kjFix(v);if(n!==v)root.nodeValue=n}return}
  if(root.nodeType!==1||/^(SCRIPT|STYLE|TEXTAREA|INPUT)$/.test(root.nodeName))return;if(root.closest&&root.closest('.mojibake,[data-nokj],.tlogo,#tscr .tl-txt'))return;
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(n.parentElement&&n.parentElement.closest('.tlogo,[data-nokj]'))continue;const v=n.nodeValue;if(KJ_TEST.test(v)){const x=kjFix(v);if(x!==v)n.nodeValue=x}}}catch(e){}}
(function(){const go=()=>{kjWalk(document.body);new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')kjWalk(m.target);else m.addedNodes.forEach(kjWalk)}}).observe(document.body,{subtree:true,childList:true,characterData:true})};
  if(document.body)go();else addEventListener('DOMContentLoaded',go)})();


/* 10/28：「にげられた＝まけ」に あわせて ボスを 調整（バランスbotで 確認）
   ・ゾンビーノ：2ターンに 1回 ゾンビが 1体（2体まで）
   ・ボスが にげるまで 24ターン／ボスの 体力 すこし ひくめ／ボスの 子分の レベル ひくめ */
BX.zombino.foeEnd=async function(){if(B.turn%2)return;const z=foeLive().filter(m=>m.id==='zombieT').length;const n=Math.min(z>=2?0:1,roomFoe());for(let i=0;i<n;i++)summon(B.foe,'zombieT',zl());if(n){bsay('「ゾンビが かけつけた！」');if(HUMAN){renderBattle();await sleep(500)}}};
BX.zombino.d='2ターンに 1回、ゾンビが 1体 かけつける（2体まで）。ゾンビが いるあいだ ドン・ゾンビーノは ダメージを うけない';
Object.assign(STAGES.hill,{bossHp:26});Object.assign(STAGES.mine,{bossHp:38});Object.assign(STAGES.steam,{bossHp:40});Object.assign(STAGES.bayou,{bossHp:50});
Object.assign(TUNE.bossLvAdd,{hill:-2,canyon:-2,saloon:-4,mine:-3,ranch:-4,train:-2,steam:0,bayou:-2,snow:-2,oasis:1});TUNE.bossHpMul=.85;
{const _mb=makeBoss;makeBoss=function(){const sp=_mb();if(sp&&sp.foe&&sp.foe.escape<100)sp.foe.escape=24+(hasRelic('badge')?2:0);return sp}}
/* 10/28：山札を もどす しくみは なし。かわりに ボスの 子分の 数を へらして、もってる カードで 勝てるように */
{const _mb=makeBoss;makeBoss=function(){const sp=_mb();try{if(!TUT_RUN()){const idx=Object.keys(STAGES).indexOf(R.sid);const keep=6+Math.floor(idx/2);const self=sp.deck.filter(c=>c.bossSelf);let rest=sp.deck.filter(c=>!c.bossSelf);rest=rest.slice(0,keep);sp.deck=shuffle([...rest,...self]);sp.foe.hp=sp.foe.max=Math.max(8,Math.round(sp.foe.hp*.85))}}catch(e){}return sp}}
Object.assign(STAGES.bayou,{bossHp:44});Object.assign(TUNE.bossLvAdd,{oasis:-1});


/* 10/28：ウィピィの 顔を セリフに あわせる（ねむい→ねむそう、こわい→こまり顔 …）
   新しい顔（ねむい・こわい・キラキラ・おいしそう）は 絵が できたら HFACE_NEW に 入れる */
const HFACE_NEW={};/* 例：{sleepy:'art/w/f10.jpg'} */
const HFACE_FB={sleepy:6,scared:6,sparkle:2,yummy:3};
const HFACE_RULES=[
  [/ねむ|ふぁ〜|ふわぁ|Zzz|すやすや/,'sleepy'],
  [/目が まわる|め、目が|目が まわ|くるくる〜/,9],
  [/こわ(い|く|そう)|ぶるぶる|ガクガク|たすけて|にげて〜|ひぃ|ひえ/,'scared'],
  [/泣|ぐすん|うぅ/,7],
  [/かわいい|きれい|すてき|もふもふ|かっこいい|だっこ/,'sparkle'],
  [/おいしそう|のみたい|ごはん|おべんとう|お昼|パン|にんじん はいってる/,'yummy'],
  [/びっくり|わわっ|わっ、|えっ|！？|\?！|うわわ/,4],
  [/いや〜|やめて〜|だめ〜|いたい|ぬれちゃう|くっつ|ねばねば|ネバネバ|あつい あつい|さむい|寒い|ずるい〜|しずむ/,6],
  [/ゆるさ|おしおき|ニセモノ|だめ！|うるさ/,5],
  [/ありがと|わ〜い|わーい|やったよ|たのしい|♪/,2],
  [/(\.\.\.|…)\s*(かな|の)？$|ないの？|うごかないの/,6]];
function heroFace(line,def){const t=String(line||'');for(const [re,f] of HFACE_RULES)if(re.test(t))return f;return def}
{const _hf=HERO.face;HERO.face=function(n){if(typeof n==='string'){if(HFACE_NEW[n])return HFACE_NEW[n];return _hf(HFACE_FB[n]||2)}return _hf(n)}}
{const _ts=talkScene;talkScene=function(foe,heroLine,result,face){const f=heroFace(heroLine,null);return _ts.call(this,foe,heroLine,result,f!=null?f:face)}}
{const _fi=foeIntro;foeIntro=async function(spec){const p=_fi.apply(this,arguments);try{setTimeout(()=>{const row=document.querySelector('#stage .trow.me');if(!row)return;const line=(row.querySelector('p')||{}).textContent||'';const f=heroFace(line,null);if(f==null)return;const h=row.querySelector('.hart');if(h)h.style.backgroundImage=`url(${HERO.face(f)})`},0)}catch(e){}return p}}
/* マップの かざり（さく・花・ほね など）は 背景に なじませる */
{const _mv=mapView;mapView=function(){const r=_mv.apply(this,arguments);try{document.body.dataset.msid=R?R.sid:''}catch(e){}return r}}
