{const _rb=renderBattle;renderBattle=function(){const r=_rb.apply(this,arguments);try{if(B&&HUMAN){const els=[...document.querySelectorAll('#hand .card')];B.me.hand.forEach((c,i)=>{const el=els[i];if(el&&c&&c._tmp&&!el.querySelector('.tmpl')){el.classList.add('tmpc');el.insertAdjacentHTML('beforeend','<i class="tmpl">この戦いだけ</i>')}})}}catch(e){}return r}}
