  keyf(u,{t:0,d:450,fn:(v,k)=>{v.gray=k;v.ox=k>=1?0:(Math.random()-.5)*8;v.rot=k*.3}});tween(u,{t:450,d:280,sc:.2,alpha:0,e:E.io});
